/**
 * AsyncAPI specification generator for AI Team WebSocket API.
 * 
 * Loads pre-generated JSON schemas (created at build time from TypeScript interfaces).
 * The source TypeScript types are in ws/chat-handler.ts.
 * Schemas are generated by scripts/generate-ws-schemas.mjs during build.
 * 
 * @see https://www.asyncapi.com/docs/reference/specification/v2.6.0
 */

import { readFileSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

/**
 * Load schemas generated at build time
 */
function loadGeneratedSchemas() {
  try {
    const schemasPath = resolve(__dirname, 'ws-schemas.json');
    const content = readFileSync(schemasPath, 'utf-8');
    return JSON.parse(content);
  } catch (error) {
    console.warn('Failed to load ws-schemas.json. Did you run build?', error);
    // Return empty schemas for tests or when file is not generated yet
    return { ChatWebSocketMessage: {}, ChatWebSocketEvent: {} };
  }
}

/**
 * Generate AsyncAPI 2.6.0 specification for the WebSocket chat endpoint.
 * 
 * Creates individual message definitions for each message type and uses
 * AsyncAPI oneOf references to support discriminated unions.
 * 
 * @returns Complete AsyncAPI specification object
 */
export function generateAsyncApiSpec(): any {
  // Load base schemas for reference (optional, mainly for documentation)
  const schemas = loadGeneratedSchemas();

  return {
    asyncapi: '2.6.0',
    info: {
      title: 'AI Team WebSocket API',
      version: '0.1.0',
      description: 'Real-time streaming chat API for AI agents with interactive question/answer flows.',
    },
    servers: {
      development: {
        url: 'ws://localhost:3002',
        protocol: 'ws',
        description: 'Development server',
      },
    },
    channels: {
      '/ws/chat/{agentId}': {
        description: 'Real-time chat channel for communicating with AI agents',
        parameters: {
          agentId: {
            description: 'Agent ID or query string to identify which agent to chat with',
            schema: { type: 'string' },
          },
        },
        subscribe: {
          summary: 'Receive streaming events from the agent',
          message: {
            oneOf: [
              { $ref: '#/components/messages/TokenEvent' },
              { $ref: '#/components/messages/StatusEvent' },
              { $ref: '#/components/messages/ToolEvent' },
              { $ref: '#/components/messages/QuestionEvent' },
              { $ref: '#/components/messages/ErrorEvent' },
              { $ref: '#/components/messages/DoneEvent' },
            ],
          },
        },
        publish: {
          summary: 'Send messages and commands to the agent',
          message: {
            oneOf: [
              { $ref: '#/components/messages/ChatMessage' },
              { $ref: '#/components/messages/CancelMessage' },
              { $ref: '#/components/messages/AnswerMessage' },
            ],
          },
        },
      },
    },
    components: {
      messages: {
        // Client -> Server Messages
        ChatMessage: {
          name: 'ChatMessage',
          contentType: 'application/json',
          payload: {
            type: 'object',
            required: ['type', 'content'],
            properties: {
              type: { type: 'string', const: 'message' },
              content: { type: 'string', description: 'The chat message content' },
              options: { type: 'object', description: 'Additional options for the chat interaction' },
            },
          },
          examples: [
            {
              payload: {
                type: 'message',
                content: 'What tasks are assigned to me?',
              },
            },
          ],
        },
        CancelMessage: {
          name: 'CancelMessage',
          contentType: 'application/json',
          payload: {
            type: 'object',
            required: ['type'],
            properties: {
              type: { type: 'string', const: 'cancel' },
            },
          },
          examples: [
            {
              payload: { type: 'cancel' },
            },
          ],
        },
        AnswerMessage: {
          name: 'AnswerMessage',
          contentType: 'application/json',
          payload: {
            type: 'object',
            required: ['type', 'answer'],
            properties: {
              type: { type: 'string', const: 'answer' },
              answer: {
                type: 'object',
                required: ['questionId', 'value'],
                properties: {
                  questionId: { type: 'string', description: 'Question ID from the QuestionEvent' },
                  value: {
                    description: 'Answer value (string for input/select/password, boolean for confirm, string[] for checklist)',
                    anyOf: [
                      { type: 'string' },
                      { type: 'boolean' },
                      { type: 'array', items: { type: 'string' } },
                    ],
                  },
                },
              },
            },
          },
          examples: [
            {
              name: 'Input answer',
              payload: {
                type: 'answer',
                answer: { questionId: 'q1', value: 'feature-branch' },
              },
            },
            {
              name: 'Confirm answer',
              payload: {
                type: 'answer',
                answer: { questionId: 'q2', value: true },
              },
            },
            {
              name: 'Checklist answer',
              payload: {
                type: 'answer',
                answer: { questionId: 'q3', value: ['option1', 'option2'] },
              },
            },
          ],
        },

        // Server -> Client Events
        TokenEvent: {
          name: 'TokenEvent',
          contentType: 'application/json',
          payload: {
            type: 'object',
            required: ['type', 'data'],
            properties: {
              type: { type: 'string', const: 'token' },
              data: {
                type: 'object',
                properties: {
                  token: { type: 'string', description: 'A streaming text token from the agent' },
                },
              },
            },
          },
          examples: [
            {
              payload: { type: 'token', data: { token: 'Hello' } },
            },
          ],
        },
        StatusEvent: {
          name: 'StatusEvent',
          contentType: 'application/json',
          payload: {
            type: 'object',
            required: ['type', 'data'],
            properties: {
              type: { type: 'string', const: 'status' },
              data: {
                type: 'object',
                properties: {
                  status: { type: 'string', description: 'Current status of the agent' },
                },
              },
            },
          },
          examples: [
            {
              payload: { type: 'status', data: { status: 'ready' } },
            },
          ],
        },
        ToolEvent: {
          name: 'ToolEvent',
          contentType: 'application/json',
          payload: {
            type: 'object',
            required: ['type', 'data'],
            properties: {
              type: { type: 'string', const: 'tool' },
              data: {
                type: 'object',
                description: 'Information about tool execution',
              },
            },
          },
          examples: [
            {
              payload: { type: 'tool', data: { name: 'search', status: 'running' } },
            },
          ],
        },
        QuestionEvent: {
          name: 'QuestionEvent',
          contentType: 'application/json',
          payload: {
            type: 'object',
            required: ['type', 'data'],
            properties: {
              type: { type: 'string', const: 'question' },
              data: {
                type: 'object',
                required: ['questionId', 'kind', 'message'],
                properties: {
                  questionId: { type: 'string', description: 'Unique ID for this question' },
                  kind: { 
                    type: 'string', 
                    enum: ['input', 'confirm', 'select', 'password', 'checklist'],
                    description: 'Type of question being asked',
                  },
                  message: { type: 'string', description: 'Question text to display' },
                  defaultValue: { description: 'Default value for the input' },
                  options: { 
                    type: 'array',
                    items: { type: 'string' },
                    description: 'Options for select/checklist questions',
                  },
                },
              },
            },
          },
          examples: [
            {
              name: 'Input question',
              payload: {
                type: 'question',
                data: {
                  questionId: 'q1',
                  kind: 'input',
                  message: 'Enter branch name',
                },
              },
            },
            {
              name: 'Confirm question',
              payload: {
                type: 'question',
                data: {
                  questionId: 'q2',
                  kind: 'confirm',
                  message: 'Continue with operation?',
                },
              },
            },
            {
              name: 'Select question',
              payload: {
                type: 'question',
                data: {
                  questionId: 'q3',
                  kind: 'select',
                  message: 'Choose an option',
                  options: ['option1', 'option2', 'option3'],
                },
              },
            },
          ],
        },
        ErrorEvent: {
          name: 'ErrorEvent',
          contentType: 'application/json',
          payload: {
            type: 'object',
            required: ['type', 'data'],
            properties: {
              type: { type: 'string', const: 'error' },
              data: {
                type: 'object',
                required: ['error'],
                properties: {
                  error: { type: 'string', description: 'Error message' },
                },
              },
            },
          },
          examples: [
            {
              payload: { type: 'error', data: { error: 'Agent not found' } },
            },
          ],
        },
        DoneEvent: {
          name: 'DoneEvent',
          contentType: 'application/json',
          payload: {
            type: 'object',
            required: ['type'],
            properties: {
              type: { type: 'string', const: 'done' },
            },
          },
          examples: [
            {
              payload: { type: 'done' },
            },
          ],
        },
      },
      schemas: {
        ChatWebSocketMessage: schemas.ChatWebSocketMessage || {},
        ChatWebSocketEvent: schemas.ChatWebSocketEvent || {},
      },
    },
  };
}

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import type { Server } from 'http';
import type { AddressInfo } from 'net';
import { WebSocket } from 'ws';
import { startServer } from '../server.js';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

// Module-level handle — closed in beforeAll if a previous test run crashed
// before afterAll could clean up (e.g. vitest watch-mode restart, Ctrl-C).
let _lingering: { httpServer: Server; wss: any; storage: { close(): Promise<void> } } | null = null;

async function closeServer(s: typeof _lingering): Promise<void> {
  if (!s) return;
  // Close WebSocket server first so in-flight connections drain.
  if (s.wss) await new Promise<void>(r => s!.wss.close(r));
  // Close SQLite before HTTP so Windows does not report EBUSY.
  if (s.storage) await s.storage.close();
  if (s.httpServer?.listening) await new Promise<void>(r => s!.httpServer.close(() => r()));
}

describe('Session-Message Integration', () => {
  let server: { httpServer: Server; wss: any; storage: { close(): Promise<void> } };
  let workspaceRoot: string;
  let port: number;

  beforeAll(async () => {
    // Kill any server that survived a previous crashed run (watch-mode, Ctrl-C, etc.).
    await closeServer(_lingering);
    _lingering = null;

    // Create temporary workspace
    workspaceRoot = await fs.mkdtemp(path.join(os.tmpdir(), 'ai-team-integration-test-'));
    
    // Create .ai-team directory structure
    await fs.mkdir(path.join(workspaceRoot, '.ai-team', 'config'), { recursive: true });
    await fs.mkdir(path.join(workspaceRoot, '.ai-team', 'private', 'chats'), { recursive: true });
    await fs.mkdir(path.join(workspaceRoot, '.ai-team', 'agents'), { recursive: true });
    
    // Create a test agent
    await fs.writeFile(
      path.join(workspaceRoot, '.ai-team', 'agents', 'test-agent.md'),
      `---
name: Test Agent
role: developer
contextLevel: module
---

# Test Agent

A test agent for integration testing.
`
    );
    
    // Create basic config
    await fs.writeFile(
      path.join(workspaceRoot, '.ai-team', 'config', 'config.json'),
      JSON.stringify({
        providers: [],
        models: [],
        defaultProvider: null,
        defaultModel: null
      })
    );
    
    // Port 0 lets the OS assign a guaranteed-free ephemeral port.
    // Read the actual assigned port from httpServer.address() after listen.
    server = await startServer({
      port: 0,
      workspaceRoot,
      serveStaticFiles: false,
    });
    _lingering = server;
    port = (server.httpServer.address() as AddressInfo).port;
  }, 30000);

  afterAll(async () => {
    await closeServer(server);
    _lingering = null;
    // Clean up workspace
    try {
      await fs.rm(workspaceRoot, { recursive: true, force: true });
    } catch (error) {
      console.warn('Failed to clean up workspace:', error);
    }
  });

  it('should create a session via REST API', async () => {
    const response = await fetch(`http://localhost:${port}/api/sessions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        agentId: 'test-agent',
        developerId: 'test-developer',
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      console.error('Failed to create session:', error);
    }
    
    expect(response.ok).toBe(true);
    const session = await response.json();
    
    expect(session).toBeDefined();
    expect(session.id).toBeDefined();
    expect(session.agentId).toBe('test-agent');
    expect(session.developerId).toBe('test-developer');
    expect(session.messageCount).toBe(0);
  });

  it('should persist messages to session when using WebSocket', async () => {
    // First create a session
    const createResponse = await fetch(`http://localhost:${port}/api/sessions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        agentId: 'test-agent',
        developerId: 'test-developer',
      }),
    });
    
    expect(createResponse.ok).toBe(true);
    const session = await createResponse.json();
    const sessionId = session.id;
    
    // Connect to WebSocket with sessionId
    const ws = new WebSocket(`ws://localhost:${port}/ws/chat/test-agent?sessionId=${sessionId}`);
    
    // Set up message listener before waiting for connection to avoid race condition
    let readyEventReceived: any = null;
    ws.on('message', (data) => {
      const event = JSON.parse(data.toString());
      if (event.type === 'status' && event.data?.status === 'ready') {
        readyEventReceived = event;
      }
      if (event.type === 'error') {
        console.error('WebSocket error event:', event);
      }
    });
    
    // Wait for connection and ready event
    await new Promise<void>((resolve, reject) => {
      const timeout = setTimeout(() => {
        if (!readyEventReceived) {
          reject(new Error('Ready event timeout'));
        }
      }, 5000);
      
      ws.on('open', () => {
        // Give a small delay for the ready event to arrive
        setTimeout(() => {
          clearTimeout(timeout);
          if (readyEventReceived) {
            resolve();
          } else {
            reject(new Error('Ready event not received after connection'));
          }
        }, 100);
      });
      
      ws.on('error', (err) => {
        clearTimeout(timeout);
        reject(err);
      });
    });
    
    expect(readyEventReceived).toBeDefined();
    expect(readyEventReceived.type).toBe('status');
    
    // Note: Sending a message would trigger the chat command which requires
    // a full LLM setup. For this test, we'll just verify the session was created
    // and the WebSocket connection works with sessionId parameter.
    
    // Close WebSocket
    ws.close();
    
    // Verify session still exists
    const sessionResponse = await fetch(`http://localhost:${port}/api/sessions/${sessionId}`);
    expect(sessionResponse.ok).toBe(true);
    const updatedSession = await sessionResponse.json();
    expect(updatedSession.id).toBe(sessionId);
  }, 15000);

  it('should load messages from a session', async () => {
    // Create a session
    const createResponse = await fetch(`http://localhost:${port}/api/sessions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        agentId: 'test-agent',
        developerId: 'test-developer',
      }),
    });
    
    expect(createResponse.ok).toBe(true);
    const session = await createResponse.json();
    const sessionId = session.id;
    
    // Load messages (should be empty initially)
    const messagesResponse = await fetch(`http://localhost:${port}/api/sessions/${sessionId}/messages`);
    expect(messagesResponse.ok).toBe(true);
    
    const messages = await messagesResponse.json();
    expect(Array.isArray(messages)).toBe(true);
    expect(messages.length).toBe(0);
  });

  it('should list sessions for an agent', async () => {
    // Create multiple sessions
    await fetch(`http://localhost:${port}/api/sessions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        agentId: 'test-agent',
        developerId: 'test-developer',
      }),
    });
    
    await fetch(`http://localhost:${port}/api/sessions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        agentId: 'test-agent',
        developerId: 'test-developer',
      }),
    });
    
    // List sessions
    const listResponse = await fetch(`http://localhost:${port}/api/sessions?agentId=test-agent`);
    expect(listResponse.ok).toBe(true);
    
    const sessions = await listResponse.json();
    expect(Array.isArray(sessions)).toBe(true);
    expect(sessions.length).toBeGreaterThanOrEqual(2);
    
    // Verify all sessions are for the correct agent
    sessions.forEach((s: any) => {
      expect(s.agentId).toBe('test-agent');
      expect(s.developerId).toBe('test-developer');
    });
  });

  it('should get the latest session for an agent', async () => {
    // Create a session
    const createResponse = await fetch(`http://localhost:${port}/api/sessions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        agentId: 'test-agent',
        developerId: 'test-developer',
      }),
    });
    
    expect(createResponse.ok).toBe(true);
    const newSession = await createResponse.json();
    
    // Get latest session
    const latestResponse = await fetch(`http://localhost:${port}/api/sessions/test-agent/latest`);
    expect(latestResponse.ok).toBe(true);
    
    const latestSession = await latestResponse.json();
    expect(latestSession.id).toBe(newSession.id);
  });

  it('should create handoff sessions', async () => {
    // Create initial session
    const createResponse = await fetch(`http://localhost:${port}/api/sessions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        agentId: 'test-agent',
        developerId: 'test-developer',
      }),
    });
    
    expect(createResponse.ok).toBe(true);
    const session = await createResponse.json();
    
    // Create handoff session
    const handoffResponse = await fetch(`http://localhost:${port}/api/sessions/handoff`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        toAgentId: 'test-agent',
        developerId: 'test-developer',
        previousSessionId: session.id,
        transferArtifacts: true,
        transferAllowedFiles: true,
      }),
    });
    
    expect(handoffResponse.ok).toBe(true);
    const handoffSession = await handoffResponse.json();
    
    expect(handoffSession.id).toBeDefined();
    expect(handoffSession.previousSessionId).toBe(session.id);
    expect(handoffSession.developerId).toBe('test-developer');
  });
});

import { Router } from 'express';
import type { AiTeamClient } from '@ai-team/api-client';
import express from 'express';
import {
  AgentManager,
  AgentSchema,
  ContextManager,
  LlmService,
  getFileTree,
  loadTeamConfig,
  parseMarkdownSections,
  replaceOrAppendMarkdownSection,
  type FileTreeNode,
} from '@ai-team/core';
import { generateIntroduction } from '@ai-team/service';

/**
 * @openapi
 * components:
 *   schemas:
 *     Agent:
 *       type: object
 *       properties:
 *         id:
 *           type: string
 *         name:
 *           type: string
 *         role:
 *           type: string
 *         providerId:
 *           type: string
 *         modelId:
 *           type: string
 */

export function createAgentsRouter(client: AiTeamClient, agentManager: AgentManager): Router {
  const router = express.Router();

  /**
   * @openapi
   * /api/agents:
   *   get:
   *     tags: [Agents]
   *     summary: List all agents
   *     description: Retrieve a list of all team members/agents
   *     responses:
   *       200:
   *         description: List of agents
   *         content:
   *           application/json:
   *             schema:
   *               type: array
   *               items:
   *                 $ref: '#/components/schemas/Agent'
   */
  router.get('/', async (req: any, res: any, next: any) => {
    try {
      const agents = await client.listEmployees({});
      res.json(agents);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/agents/search:
   *   get:
   *     tags: [Agents]
   *     summary: Get a specific agent
   *     description: Retrieve details of a specific team member/agent by ID
   *     parameters:
   *       - name: id
   *         in: path
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *     responses:
   *       200:
   *         description: Agent details
   *         content:
   *           application/json:
   *             schema:
   *               $ref: '#/components/schemas/Agent'
   *       404:
   *         description: Agent not found
   */
  router.get('/:id', async (req: any, res: any, next: any) => {
    try {
      const agents = await client.resolveEmployees(req.params.id);
      if (agents.length === 0) {
        return res.status(404).json({
          error: 'Agent not found',
          details: `Agent with ID ${req.params.id} does not exist`,
        });
      }
      res.json(agents[0]);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/agents/search:
   *   get:
   *     tags: [Agents]
   *     summary: Search agents
   *     description: Search for agents with fuzzy matching and filtering
   *     parameters:
   *       - name: q
   *         in: query
   *         schema:
   *           type: string
   *         description: Search query (name, role, specializations, features, etc.)
   *       - name: role
   *         in: query
   *         schema:
   *           type: string
   *         description: Filter by role (can be repeated)
   *       - name: type
   *         in: query
   *         schema:
   *           type: string
   *         description: Filter by role type (executive, team-lead, etc.)
   *       - name: status
   *         in: query
   *         schema:
   *           type: string
   *         description: Filter by status (available, busy, etc.)
   *       - name: feature
   *         in: query
   *         schema:
   *           type: string
   *         description: Filter by feature (can be repeated)
   *       - name: specialization
   *         in: query
   *         schema:
   *           type: string
   *         description: Filter by specialization (can be repeated)
   *       - name: tool
   *         in: query
   *         schema:
   *           type: string
   *         description: Filter by tool (can be repeated)
   *       - name: reportsTo
   *         in: query
   *         schema:
   *           type: string
   *         description: Filter by manager ID
   *       - name: contextLevel
   *         in: query
   *         schema:
   *           type: string
   *         description: Filter by context level (task, module, feature, repository, organization)
   *     responses:
   *       200:
   *         description: Search results with scores
   *         content:
   *           application/json:
   *             schema:
   *               type: object
   *               properties:
   *                 results:
   *                   type: array
   *                   items:
   *                     type: object
   *                     properties:
   *                       agent:
   *                         $ref: '#/components/schemas/Agent'
   *                       score:
   *                         type: number
   *                       matches:
   *                         type: array
   *                         items:
   *                           type: string
   *                 totalCount:
   *                   type: number
   */
  router.get('/search', async (req: any, res: any, next: any) => {
    try {
      // Parse query parameters (support arrays)
      const parseArrayParam = (param: any): string[] | undefined => {
        if (!param) return undefined;
        return Array.isArray(param) ? param : [param];
      };

      const searchRequest: any = {
        query: req.query.q,
        role: parseArrayParam(req.query.role),
        type: parseArrayParam(req.query.type),
        status: parseArrayParam(req.query.status),
        feature: parseArrayParam(req.query.feature),
        specialization: parseArrayParam(req.query.specialization),
        tool: parseArrayParam(req.query.tool),
        reportsTo: req.query.reportsTo,
        contextLevel: parseArrayParam(req.query.contextLevel),
      };

      // Remove undefined values
      Object.keys(searchRequest).forEach(key => {
        if (searchRequest[key] === undefined) {
          delete searchRequest[key];
        }
      });

      const response = await client.searchAgents(searchRequest);
      res.json(response);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/agents/{id}:
   *   get:
   *     tags: [Agents]
   *     summary: Get a specific agent
   *     description: Retrieve details of a specific team member/agent by ID
   *     parameters:
   *       - name: id
   *         in: path
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *     responses:
   *       200:
   *         description: Agent details
   *         content:
   *           application/json:
   *             schema:
   *               $ref: '#/components/schemas/Agent'
   *       404:
   *         description: Agent not found
   */
  router.get('/:id', async (req: any, res: any, next: any) => {
    try {
      const agents = await client.resolveEmployees(req.params.id);
      if (agents.length === 0) {
        return res.status(404).json({
          error: 'Agent not found',
          details: `Agent with ID ${req.params.id} does not exist`,
        });
      }
      res.json(agents[0]);
    } catch (error) {
      next(error);
    }
  });

  // ==========================================================================
  // Frontmatter & Markdown Section Endpoints
  // ==========================================================================

  /** Helper: resolve agent by fuzzy query (id / role / name), return 404 if not found */
  async function resolveAgentOrFail(query: string, res: any): Promise<ReturnType<AgentManager['getAgent']> | null> {
    const matches = agentManager.resolveAgent(query);
    if (matches.length === 0) {
      res.status(404).json({ error: 'Agent not found', details: `No agent matching "${query}"` });
      return null;
    }
    return matches[0];
  }

  /**
   * @openapi
   * /api/agents/{id}/frontmatter:
   *   get:
   *     tags: [Agents]
   *     summary: Get agent frontmatter as JSON
   *     description: Returns the full agent object (frontmatter fields + computed fields) as JSON
   *     parameters:
   *       - name: id
   *         in: path
   *         required: true
   *         schema:
   *           type: string
   *     responses:
   *       200:
   *         description: Agent frontmatter as JSON
   *       404:
   *         description: Agent not found
   */
  router.get('/:id/frontmatter', async (req: any, res: any, next: any) => {
    try {
      const agent = await resolveAgentOrFail(req.params.id, res);
      if (!agent) return;
      res.json(agent);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/agents/{id}/frontmatter:
   *   patch:
   *     tags: [Agents]
   *     summary: Update agent frontmatter fields
   *     description: Partially update agent frontmatter (YAML) fields. Accepts any subset of AgentConfig fields.
   *     parameters:
   *       - name: id
   *         in: path
   *         required: true
   *         schema:
   *           type: string
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *     responses:
   *       200:
   *         description: Updated agent
   *       400:
   *         description: Invalid request body
   *       404:
   *         description: Agent not found
   */
  router.patch('/:id/frontmatter', async (req: any, res: any, next: any) => {
    try {
      const existing = await resolveAgentOrFail(req.params.id, res);
      if (!existing) return;

      // Validate body as partial AgentSchema
      const parsed = AgentSchema.partial().safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          error: 'Invalid frontmatter',
          details: parsed.error.issues,
        });
      }

      const updated = await agentManager.updateAgent(existing.id, parsed.data);
      res.json(updated);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/agents/{id}/sections:
   *   get:
   *     tags: [Agents]
   *     summary: Get agent markdown body parsed into sections
   *     description: |
   *       Returns the agent's markdown body split into ordered sections by ## headings.
   *       Each section has a `heading` (empty string for preamble before first ##) and `content`.
   *     parameters:
   *       - name: id
   *         in: path
   *         required: true
   *         schema:
   *           type: string
   *     responses:
   *       200:
   *         description: Ordered array of markdown sections
   *         content:
   *           application/json:
   *             schema:
   *               type: array
   *               items:
   *                 type: object
   *                 properties:
   *                   heading:
   *                     type: string
   *                   content:
   *                     type: string
   *       404:
   *         description: Agent not found
   */
  router.get('/:id/sections', async (req: any, res: any, next: any) => {
    try {
      const agent = await resolveAgentOrFail(req.params.id, res);
      if (!agent) return;
      const sections = parseMarkdownSections(agent.markdown || '');
      res.json(sections);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/agents/{id}/sections/{heading}:
   *   patch:
   *     tags: [Agents]
   *     summary: Update or create a markdown section by heading title
   *     description: |
   *       Replaces the content of a specific ## section identified by heading title.
   *       If the heading does not exist, a new section is appended at the end of the document.
   *     parameters:
   *       - name: id
   *         in: path
   *         required: true
   *         schema:
   *           type: string
   *       - name: heading
   *         in: path
   *         required: true
   *         schema:
   *           type: string
   *         description: The heading title (without the ## prefix)
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required: [content]
   *             properties:
   *               content:
   *                 type: string
   *                 description: New section body content
   *     responses:
   *       200:
   *         description: Updated sections array
   *       400:
   *         description: Invalid request body
   *       404:
   *         description: Agent not found
   */
  const SectionUpdateSchema = { safeParse: (body: any) => {
    if (body && typeof body.content === 'string') return { success: true as const, data: { content: body.content as string } };
    return { success: false as const, error: { issues: [{ message: 'content must be a string' }] } };
  }};

  router.patch('/:id/sections/:heading', async (req: any, res: any, next: any) => {
    try {
      const agent = await resolveAgentOrFail(req.params.id, res);
      if (!agent) return;

      const parsed = SectionUpdateSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          error: 'Invalid request body',
          details: 'Body must contain { "content": "..." }',
        });
      }

      const heading = decodeURIComponent(req.params.heading);
      const newMarkdown = replaceOrAppendMarkdownSection(
        agent.markdown || '',
        heading,
        parsed.data.content,
      );

      const updated = await agentManager.updateAgent(agent.id, { markdown: newMarkdown });
      const sections = parseMarkdownSections(updated.markdown || '');
      res.json(sections);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/agents/{id}/markdown:
   *   get:
   *     tags: [Agents]
   *     summary: Get the raw markdown body of an agent
   *     description: Returns the full markdown body (without YAML frontmatter) as plain text
   *     parameters:
   *       - name: id
   *         in: path
   *         required: true
   *         schema:
   *           type: string
   *     responses:
   *       200:
   *         description: Raw markdown body
   *         content:
   *           text/plain:
   *             schema:
   *               type: string
   *       404:
   *         description: Agent not found
   */
  router.get('/:id/markdown', async (req: any, res: any, next: any) => {
    try {
      const agent = await resolveAgentOrFail(req.params.id, res);
      if (!agent) return;
      res.type('text/plain').send(agent.markdown || '');
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/agents/{id}/markdown:
   *   put:
   *     tags: [Agents]
   *     summary: Replace the entire markdown body of an agent
   *     description: |
   *       Replaces the full markdown body with the provided content.
   *       Use this when you want to write the raw markdown yourself instead of using section-based updates.
   *     parameters:
   *       - name: id
   *         in: path
   *         required: true
   *         schema:
   *           type: string
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required: [markdown]
   *             properties:
   *               markdown:
   *                 type: string
   *                 description: Full markdown body content
   *     responses:
   *       200:
   *         description: Updated agent
   *       400:
   *         description: Invalid request body
   *       404:
   *         description: Agent not found
   */
  const MarkdownUpdateSchema = { safeParse: (body: any) => {
    if (body && typeof body.markdown === 'string') return { success: true as const, data: { markdown: body.markdown as string } };
    return { success: false as const, error: { issues: [{ message: 'markdown must be a string' }] } };
  }};

  router.put('/:id/markdown', async (req: any, res: any, next: any) => {
    try {
      const agent = await resolveAgentOrFail(req.params.id, res);
      if (!agent) return;

      const parsed = MarkdownUpdateSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          error: 'Invalid request body',
          details: 'Body must contain { "markdown": "..." }',
        });
      }

      const updated = await agentManager.updateAgent(agent.id, { markdown: parsed.data.markdown });
      res.json(updated);
    } catch (error) {
      next(error);
    }
  });

  // ==========================================================================
  // Agent file-tree endpoint (annotated with read / write permissions)
  // ==========================================================================

  /**
   * @openapi
   * /api/agents/{id}/files:
   *   get:
   *     tags: [Agents]
   *     summary: Get the workspace file list annotated with the agent's read/write permissions
   *     description: |
   *       Returns every file in the workspace that the agent can either read or write,
   *       together with boolean `readable` and `writable` flags per file.
   *     parameters:
   *       - name: id
   *         in: path
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID, name or role (fuzzy-matched)
   *       - name: depth
   *         in: query
   *         schema:
   *           type: integer
   *           default: 6
   *         description: Max directory depth
   *       - name: all
   *         in: query
   *         schema:
   *           type: boolean
   *           default: false
   *         description: Include files with no read or write access
   *     responses:
   *       200:
   *         description: Annotated file list
   *         content:
   *           application/json:
   *             schema:
   *               type: object
   *               properties:
   *                 agent:
   *                   type: string
   *                 readPatterns:
   *                   type: array
   *                   items:
   *                     type: string
   *                 writePatterns:
   *                   type: array
   *                   items:
   *                     type: string
   *                 files:
   *                   type: array
   *                   items:
   *                     type: object
   *                     properties:
   *                       path:
   *                         type: string
   *                       readable:
   *                         type: boolean
   *                       writable:
   *                         type: boolean
   *       404:
   *         description: Agent not found
   */
  router.get('/:id/files', async (req: any, res: any, next: any) => {
    try {
      const agent = await resolveAgentOrFail(req.params.id, res);
      if (!agent) return;

      const maxDepth = req.query.depth ? Number.parseInt(req.query.depth, 10) : 6;
      const includeAll = req.query.all === 'true' || req.query.all === '1';

      // Build file tree respecting global allowPaths
      const config = await loadTeamConfig(agentManager.workspaceRoot);
      const allowPaths = config?.fileTree?.allowPaths ?? [];
      const tree = await getFileTree(agentManager.workspaceRoot, { maxDepth, allowPaths });

      // Flatten to relative paths
      const allFiles = flattenTree(tree);

      // Annotate with permissions
      const ctx = ContextManager.fromConfig(agentManager.workspaceRoot, config?.fileTree);
      const annotated = ctx.getAnnotatedFiles(agent, allFiles);

      const files = includeAll
        ? annotated
        : annotated.filter(f => f.readable || f.writable);

      res.json({
        agent: agent.id,
        readPatterns: agent.permissions?.read ?? [],
        writePatterns: agent.permissions?.write ?? [],
        files,
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/agents/{id}/introduction:
   *   get:
   *     tags: [Agents]
   *     summary: Generate an agent introduction
   *     description: Ask the agent to introduce themselves via LLM. Not persisted.
   *     parameters:
   *       - name: id
   *         in: path
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *       - name: developerName
   *         in: query
   *         schema:
   *           type: string
   *         description: Optional developer name to personalise the greeting
   *     responses:
   *       200:
   *         description: Introduction generated successfully
   *         content:
   *           application/json:
   *             schema:
   *               type: object
   *               properties:
   *                 content:
   *                   type: string
   *                 agentId:
   *                   type: string
   *                 agentName:
   *                   type: string
   *                 timestamp:
   *                   type: string
   *       404:
   *         description: Agent not found
   *       503:
   *         description: LLM unavailable
   */
  router.get('/:id/introduction', async (req: any, res: any, next: any) => {
    try {
      const agents = agentManager.resolveAgent(req.params.id);
      if (!agents || agents.length === 0) {
        return res.status(404).json({ error: 'Agent not found', details: `No agent matching '${req.params.id}'` });
      }
      const agent = agents[0];
      const developerName = typeof req.query.developerName === 'string' ? req.query.developerName : undefined;
      const llm = new LlmService(agentManager.workspaceRoot);
      const content = await generateIntroduction(llm, agentManager, agent, undefined, developerName);
      res.json({
        content,
        agentId: agent.id,
        agentName: agent.name,
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      next(error);
    }
  });

  return router;
}

/** Iteratively flatten a FileTreeNode into workspace-relative file paths */
function flattenTree(root: FileTreeNode): string[] {
  const files: string[] = [];
  const stack: FileTreeNode[] = [root];
  while (stack.length > 0) {
    const node = stack.pop()!;
    if (!node.isDirectory && node.relativePath !== '') {
      files.push(node.relativePath);
    }
    if (node.children) {
      for (let i = node.children.length - 1; i >= 0; i--) {
        stack.push(node.children[i]);
      }
    }
  }
  return files;
}

import { Router } from 'express';
import type { AiTeamClient } from '@ai-team/api-client';
import express from 'express';
import { ChatContextManager, type AgentManager } from '@ai-team/core';
import { type SessionManager, resolveAgentForOperation } from '@ai-team/service';

export function createChatRouter(client: AiTeamClient, workspaceRoot: string, agentManager?: AgentManager, sessionManager?: SessionManager): Router {
  const router = express.Router();
  const contextManager = new ChatContextManager(workspaceRoot);

  /**
   * Helper to resolve agent query to exact agent ID
   */
  const resolveAgentId = (agentQuery: string): string => {
    if (!agentManager) {
      return agentQuery; // Fallback to exact match if no AgentManager
    }
    const resolved = resolveAgentForOperation(agentManager, agentQuery, 'access chat');
    return resolved.id;
  };

  /**
   * @openapi
   * /api/chat/summaries:
   *   get:
   *     tags: [Chat]
   *     summary: Get all chat summaries
   *     description: Returns summaries of all chat sessions across all agents
   *     responses:
   *       200:
   *         description: Array of chat summaries
   *         content:
   *           application/json:
   *             schema:
   *               type: array
   *               items:
   *                 type: object
   */
  router.get('/summaries', async (req: any, res: any, next: any) => {
    try {
      const summaries = await contextManager.loadSummaries();
      res.json(summaries);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/chat/{agentId}:
   *   get:
   *     tags: [Chat]
   *     summary: Load chat history for an agent
   *     description: Returns all messages from the chat log for the specified agent
   *     parameters:
   *       - in: path
   *         name: agentId
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID (exact match or fuzzy query if AgentManager available)
   *       - in: query
   *         name: includeArchived
   *         schema:
   *           type: boolean
   *           default: false
   *         description: Include archived messages in response
   *     responses:
   *       200:
   *         description: Array of chat messages
   *         content:
   *           application/json:
   *             schema:
   *               type: array
   *               items:
   *                 type: object
   */
  router.get('/:agentId', async (req: any, res: any, next: any) => {
    try {
      const agentQuery = req.params.agentId;
      const agentId = resolveAgentId(agentQuery); // Resolve to exact ID
      const includeArchived = req.query.includeArchived === 'true';
      if (!sessionManager) {
        return res.json([]);
      }

      const session = await sessionManager.getLatestSession(agentId);
      if (!session) {
        return res.json([]);
      }

      const messages = await sessionManager.getSessionMessages(session.id);

      // Filter archived messages unless requested
      const filteredMessages = includeArchived
        ? messages
        : messages.filter((msg: any) => !msg.archived);

      res.json(filteredMessages);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/chat/{agentId}:
   *   post:
   *     tags: [Chat]
   *     summary: Send message to agent
   *     description: Send a message to an agent (non-streaming fallback). For real-time experience, use WebSocket.
   *     parameters:
   *       - in: path
   *         name: agentId
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - content
   *             properties:
   *               content:
   *                 type: string
   *                 description: Message content
   *     responses:
   *       200:
   *         description: Chat response
   *       400:
   *         description: Invalid request
   */
  router.post('/:agentId', async (req: any, res: any, next: any) => {
    try {
      const agentQuery = req.params.agentId;
      const agentId = resolveAgentId(agentQuery); // Resolve to exact ID
      const { content, pendingIntroduction } = req.body;

      if (!content || typeof content !== 'string') {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'Message content is required',
        });
      }

      // Collect streamed tokens to build the full agent reply
      const stream = client.stream({
        command: 'chat',
        payload: {
          employeeId: agentId,
          options: {
            message: content,
            oneShot: true,
            ...(pendingIntroduction ? { pendingIntroduction } : {}),
          },
        },
      });

      let agentReply = '';
      let handoffEvent: any = null;
      for await (const event of stream) {
        if (event.kind === 'token') {
          agentReply += (event as any).text;
        } else if (event.kind === 'handoff') {
          handoffEvent = event;
        } else if (event.kind === 'error') {
          return res.status(500).json({ error: (event as any).message });
        }
      }

      const responseBody: Record<string, any> = { content: agentReply.trim() };
      if (handoffEvent) {
        responseBody.handoff = {
          fromAgentId: handoffEvent.fromAgentId,
          fromAgentName: handoffEvent.fromAgentName,
          toAgentId: handoffEvent.toAgentId,
          toAgentName: handoffEvent.toAgentName,
          handoffNote: handoffEvent.handoffNote,
        };
      }

      res.json(responseBody);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/chat/{agentId}/messages/{index}:
   *   put:
   *     tags: [Chat]
   *     summary: Edit a message
   *     description: Edit the content of a specific message in the chat history
   *     parameters:
   *       - in: path
   *         name: agentId
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *       - in: path
   *         name: index
   *         required: true
   *         schema:
   *           type: integer
   *         description: Message index
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - content
   *             properties:
   *               content:
   *                 type: string
   *                 description: New message content
   *     responses:
   *       200:
   *         description: Success
   *       400:
   *         description: Invalid request
   */
  router.put('/:agentId/messages/:index', async (req: any, res: any, next: any) => {
    try {
      const agentQuery = req.params.agentId;
      const agentId = resolveAgentId(agentQuery); // Resolve to exact ID
      const { index } = req.params;
      const { content } = req.body;

      if (!content || typeof content !== 'string') {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'Message content is required',
        });
      }

      const messageIndex = parseInt(index, 10);
      await contextManager.editMessage(agentId, messageIndex, content);

      res.json({ success: true });
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/chat/{agentId}/messages/{index}:
   *   delete:
   *     tags: [Chat]
   *     summary: Delete a message
   *     description: Delete a specific message from the chat history
   *     parameters:
   *       - in: path
   *         name: agentId
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *       - in: path
   *         name: index
   *         required: true
   *         schema:
   *           type: integer
   *         description: Message index
   *     responses:
   *       200:
   *         description: Success
   */
  router.delete('/:agentId/messages/:index', async (req: any, res: any, next: any) => {
    try {
      const agentQuery = req.params.agentId;
      const agentId = resolveAgentId(agentQuery); // Resolve to exact ID
      const { index } = req.params;
      const messageIndex = parseInt(index, 10);

      console.log(`[DELETE] Deleting message ${messageIndex} for agent ${agentId}`);
      await contextManager.deleteMessage(agentId, messageIndex);
      console.log(`[DELETE] Successfully deleted message ${messageIndex}`);

      res.json({ success: true });
    } catch (error) {
      console.error(`[DELETE] Error deleting message:`, error);
      next(error);
    }
  });

  /**
   * @openapi
   * /api/chat/{agentId}/messages/{index}/archive:
   *   patch:
   *     tags: [Chat]
   *     summary: Archive a message
   *     description: Mark a message as archived (hidden by default)
   *     parameters:
   *       - in: path
   *         name: agentId
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *       - in: path
   *         name: index
   *         required: true
   *         schema:
   *           type: integer
   *         description: Message index
   *     responses:
   *       200:
   *         description: Success
   */
  router.patch('/:agentId/messages/:index/archive', async (req: any, res: any, next: any) => {
    try {
      const agentQuery = req.params.agentId;
      const agentId = resolveAgentId(agentQuery); // Resolve to exact ID
      const { index } = req.params;
      const messageIndex = parseInt(index, 10);

      await contextManager.archiveMessage(agentId, messageIndex);

      res.json({ success: true });
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/chat/{agentId}/messages/{index}/unarchive:
   *   patch:
   *     tags: [Chat]
   *     summary: Unarchive a message
   *     description: Restore an archived message
   *     parameters:
   *       - in: path
   *         name: agentId
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *       - in: path
   *         name: index
   *         required: true
   *         schema:
   *           type: integer
   *         description: Message index
   *     responses:
   *       200:
   *         description: Success
   */
  router.patch('/:agentId/messages/:index/unarchive', async (req: any, res: any, next: any) => {
    try {
      const agentQuery = req.params.agentId;
      const agentId = resolveAgentId(agentQuery); // Resolve to exact ID
      const { index } = req.params;
      const messageIndex = parseInt(index, 10);

      await contextManager.unarchiveMessage(agentId, messageIndex);

      res.json({ success: true });
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/chat/{agentId}/stats:
   *   get:
   *     tags: [Chat]
   *     summary: Get message statistics
   *     description: Returns statistics about messages (total, archived, by role, etc.)
   *     parameters:
   *       - in: path
   *         name: agentId
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *     responses:
   *       200:
   *         description: Message statistics
   */
  router.get('/:agentId/stats', async (req: any, res: any, next: any) => {
    try {
      const agentQuery = req.params.agentId;
      const agentId = resolveAgentId(agentQuery); // Resolve to exact ID
      const stats = await contextManager.getMessageStats(agentId);

      res.json(stats);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/chat/{agentId}/summary:
   *   post:
   *     tags: [Chat]
   *     summary: Create a summary from selected messages
   *     description: Create a summary artifact from specific messages in chat history
   *     parameters:
   *       - in: path
   *         name: agentId
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - messageIndices
   *               - title
   *             properties:
   *               messageIndices:
   *                 type: array
   *                 items:
   *                   type: integer
   *                 description: Array of message indices to include
   *               title:
   *                 type: string
   *                 description: Summary title
   *               tags:
   *                 type: array
   *                 items:
   *                   type: string
   *                 description: Optional tags
   *     responses:
   *       200:
   *         description: Created summary
   *       400:
   *         description: Invalid request
   */
  router.post('/:agentId/summary', async (req: any, res: any, next: any) => {
    try {
      const agentQuery = req.params.agentId;
      const agentId = resolveAgentId(agentQuery); // Resolve to exact ID
      const { messageIndices, title, tags } = req.body;

      if (!Array.isArray(messageIndices) || !title) {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'messageIndices (array) and title (string) are required',
        });
      }

      const summary = await contextManager.createSummary(agentId, messageIndices, title, tags);

      res.json(summary);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/chat/{agentId}/messages/{index}/annotate:
   *   post:
   *     tags: [Chat]
   *     summary: Add annotation to a message
   *     description: Add metadata annotation to a specific message
   *     parameters:
   *       - in: path
   *         name: agentId
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *       - in: path
   *         name: index
   *         required: true
   *         schema:
   *           type: integer
   *         description: Message index
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - type
   *               - content
   *             properties:
   *               type:
   *                 type: string
   *                 description: Annotation type
   *               content:
   *                 type: string
   *                 description: Annotation content
   *               tags:
   *                 type: array
   *                 items:
   *                   type: string
   *                 description: Optional tags
   *     responses:
   *       200:
   *         description: Success
   *       400:
   *         description: Invalid request
   */
  router.post('/:agentId/messages/:index/annotate', async (req: any, res: any, next: any) => {
    try {
      const agentQuery = req.params.agentId;
      const agentId = resolveAgentId(agentQuery); // Resolve to exact ID
      const { index } = req.params;
      const { type, content, tags } = req.body;

      if (!type || !content) {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'type and content are required',
        });
      }

      const messageIndex = parseInt(index, 10);
      const annotation = {
        type,
        content,
        timestamp: new Date().toISOString(),
        tags,
      };

      await contextManager.addAnnotation(agentId, messageIndex, annotation);

      res.json({ success: true });
    } catch (error) {
      next(error);
    }
  });

  return router;
}

import { Router } from 'express';
import type { AiTeamClient } from '@ai-team/api-client';
import { getGitUserName, getGitUserEmail, developerNameToId } from '@ai-team/service/dist/utils/git.js';

export function createDeveloperRouter(client: AiTeamClient, workspaceRoot: string): Router {
  const router = Router();

  /**
   * @openapi
   * /api/developer/me:
   *   get:
   *     tags: [Developer]
   *     summary: Get current developer profile
   *     description: Returns information about the current developer from git config
   *     responses:
   *       200:
   *         description: Developer profile
   *         content:
   *           application/json:
   *             schema:
   *               type: object
   *               properties:
   *                 id:
   *                   type: string
   *                   example: clemens-meier
   *                 name:
   *                   type: string
   *                   example: Clemens Meier
   *                 email:
   *                   type: string
   *                   example: clemens.meier@example.com
   */
  router.get('/me', async (req: any, res: any, next: any) => {
    try {
      // Get developer info from git config
      const name = getGitUserName() || 'Developer';
      const email = getGitUserEmail();
      const id = developerNameToId(name);

      res.json({
        id,
        name,
        email: email || undefined,
      });
    } catch (error) {
      next(error);
    }
  });

  return router;
}

import { Router } from 'express';
import { SessionManager, createSqliteStorage } from '@ai-team/service';
import type { AgentManager } from '@ai-team/core';
import express from 'express';

export function createSessionsRouter(workspaceRoot: string, agentManager?: AgentManager, sharedSessionManager?: SessionManager): Router {
  const router = express.Router();
  const sessionManager = sharedSessionManager
    ?? new SessionManager(workspaceRoot, createSqliteStorage(workspaceRoot), agentManager);

  if (!sharedSessionManager) {
    // Only initialize if we had to create our own instance
    sessionManager.initialize().catch((error) => {
      console.error('Failed to initialize session manager:', error);
    });
  }

  /**
   * @openapi
   * /api/sessions/{agentId}/latest:
   *   get:
   *     tags: [Sessions]
   *     summary: Get latest session for an agent
   *     description: Returns the most recent chat session for the specified agent
   *     parameters:
   *       - in: path
   *         name: agentId
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *       - in: query
   *         name: includeMessages
   *         schema:
   *           type: boolean
   *           default: false
   *         description: Include messages in the response
   *     responses:
   *       200:
   *         description: Latest session data
   *       404:
   *         description: No session found for agent
   */
  router.get('/:agentId/latest', async (req: any, res: any, next: any) => {
    try {
      const { agentId } = req.params;
      const includeMessages = req.query.includeMessages === 'true';
      const session = await sessionManager.getLatestSession(agentId);
      
      if (!session) {
        return res.status(404).json({
          error: 'No session found',
          details: `No sessions exist for agent ${agentId}`,
        });
      }

      if (includeMessages) {
        const messages = await sessionManager.getSessionMessages(session.id);
        res.json({ ...session, messages });
      } else {
        res.json(session);
      }
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions/recent:
   *   get:
   *     tags: [Sessions]
   *     summary: Get recent sessions across all agents
   *     description: Returns recent chat sessions sorted by last activity, useful for dashboard
   *     parameters:
   *       - in: query
   *         name: limit
   *         schema:
   *           type: integer
   *           default: 10
   *         description: Maximum number of sessions to return
   *     responses:
   *       200:
   *         description: Array of recent sessions
   */
  router.get('/recent', async (req: any, res: any, next: any) => {
    try {
      const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
      const sessions = await sessionManager.listRecentSessions(limit);

      res.json(sessions);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions:
   *   get:
   *     tags: [Sessions]
   *     summary: List sessions for an agent
   *     description: Returns all chat sessions for the specified agent
   *     parameters:
   *       - in: query
   *         name: agentId
   *         required: true
   *         schema:
   *           type: string
   *         description: Agent ID
   *       - in: query
   *         name: limit
   *         schema:
   *           type: integer
   *         description: Maximum number of sessions to return
   *     responses:
   *       200:
   *         description: Array of sessions
   *       400:
   *         description: Missing agentId parameter
   */
  router.get('/', async (req: any, res: any, next: any) => {
    try {
      const { agentId, limit } = req.query;

      if (!agentId) {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'agentId query parameter is required',
        });
      }

      const limitNum = limit ? parseInt(limit, 10) : undefined;
      const sessions = await sessionManager.listSessions(agentId, limitNum);

      res.json(sessions);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions/{sessionId}:
   *   get:
   *     tags: [Sessions]
   *     summary: Get session by ID
   *     description: Returns detailed information about a specific session
   *     parameters:
   *       - in: path
   *         name: sessionId
   *         required: true
   *         schema:
   *           type: string
   *         description: Session ID (UUID)
   *       - in: query
   *         name: includeMessages
   *         schema:
   *           type: boolean
   *           default: false
   *         description: Include messages in the response
   *     responses:
   *       200:
   *         description: Session data
   *       404:
   *         description: Session not found
   */
  router.get('/:sessionId', async (req: any, res: any, next: any) => {
    try {
      const { sessionId } = req.params;
      const includeMessages = req.query.includeMessages === 'true';
      const session = await sessionManager.getSession(sessionId);

      if (!session) {
        return res.status(404).json({
          error: 'Session not found',
          details: `Session ${sessionId} does not exist`,
        });
      }

      if (includeMessages) {
        const messages = await sessionManager.getSessionMessages(sessionId);
        res.json({ ...session, messages });
      } else {
        res.json(session);
      }
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions/{sessionId}/messages:
   *   get:
   *     tags: [Sessions]
   *     summary: Get messages for a session
   *     description: Returns all messages in  a specific session
   *     parameters:
   *       - in: path
   *         name: sessionId
   *         required: true
   *         schema:
   *           type: string
   *         description: Session ID (UUID)
   *     responses:
   *       200:
   *         description: Array of messages
   */
  router.get('/:sessionId/messages', async (req: any, res: any, next: any) => {
    try {
      const { sessionId } = req.params;
      const messages = await sessionManager.getSessionMessages(sessionId);
      res.json(messages);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions/{sessionId}/thread:
   *   get:
   *     tags: [Sessions]
   *     summary: Get the full session chain for a handoff thread
   *     description: |
   *       Walks the previousSessionId chain from the given session back to the root.
   *       Returns all sessions in the thread ordered root → leaf, each with their
   *       messages. Messages belonging to the same handoff event share a handoffId,
   *       enabling cross-session message linking in the UI.
   *     parameters:
   *       - in: path
   *         name: sessionId
   *         required: true
   *         schema:
   *           type: string
   *         description: Any session ID in the thread (root or any descendant)
   *     responses:
   *       200:
   *         description: Full thread with all sessions and messages
   *       404:
   *         description: Session not found
   */
  router.get('/:sessionId/thread', async (req: any, res: any, next: any) => {
    try {
      const { sessionId } = req.params;

      const rootCheck = await sessionManager.getSession(sessionId);
      if (!rootCheck) {
        return res.status(404).json({
          error: 'Session not found',
          details: `Session ${sessionId} does not exist`,
        });
      }

      const chain = await sessionManager.getSessionChain(sessionId);

      const sessions = await Promise.all(
        chain.map(async (session) => {
          const messages = await sessionManager.getSessionMessages(session.id);
          const ids = session.agentIds ?? (session.agentId ? [session.agentId] : []);
          const agentNames = ids.map((id) => {
            try { return agentManager?.getAgent(id)?.name ?? id; } catch { return id; }
          });
          return {
            sessionId: session.id,
            agentIds: ids,
            agentNames,
            developerId: session.developerId ?? null,
            title: session.title ?? null,
            startedAt: session.startedAt,
            lastActivityAt: session.lastActivityAt,
            previousSessionId: session.previousSessionId ?? null,
            mergedFromSessionIds: session.mergedFromSessionIds ?? null,
            messageCount: messages.length,
            messages,
          };
        }),
      );

      // Build a cross-session handoff edge index from messages that carry handoffId + session links.
      // Each unique handoffId represents one handoff event with a FROM and TO side.
      const handoffMap = new Map<string, { handoffId: string; fromSessionId: string | null; toSessionId: string | null; fromAgentIds: string[]; toAgentIds: string[] }>();
      for (const s of sessions) {
        for (const m of s.messages) {
          if (!m.handoffId) continue;
          const existing = handoffMap.get(m.handoffId);
          if (!existing) {
            handoffMap.set(m.handoffId, {
              handoffId: m.handoffId,
              fromSessionId: m.handoffFromSessionId ?? null,
              toSessionId: m.handoffToSessionId ?? null,
              fromAgentIds: [],
              toAgentIds: [],
            });
          }
        }
        // Populate agent IDs from session membership
        for (const [, edge] of handoffMap) {
          if (edge.fromSessionId === s.sessionId) edge.fromAgentIds = s.agentIds;
          if (edge.toSessionId === s.sessionId) edge.toAgentIds = s.agentIds;
        }
      }
      const handoffs = Array.from(handoffMap.values());

      res.json({
        rootSessionId: sessions[0]?.sessionId ?? sessionId,
        currentSessionId: sessionId,
        depth: sessions.length,
        handoffs,
        sessions,
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions:
   *   post:
   *     tags: [Sessions]
   *     summary: Create a new session
   *     description: Create a new chat session for an agent
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - agentId
   *               - developerId
   *             properties:
   *               agentId:
   *                 type: string
   *                 description: Agent ID
   *               developerId:
   *                 type: string
   *                 description: Developer/user ID
   *     responses:
   *       200:
   *         description: Created session
   *       400:
   *         description: Missing required fields
   */
  router.post('/', async (req: any, res: any, next: any) => {
    try {
      const { agentId, developerId } = req.body;

      if (!agentId || !developerId) {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'Both agentId and developerId are required',
        });
      }

      const session = await sessionManager.createSession(agentId, developerId);
      res.json(session);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions/{sessionId}/split:
   *   post:
   *     tags: [Sessions]
   *     summary: Split a session at a message index
   *     description: Split a session into two sessions at a specific message
   *     parameters:
   *       - in: path
   *         name: sessionId
   *         required: true
   *         schema:
   *           type: string
   *         description: Session ID
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - atIndex
   *               - developerId
   *             properties:
   *               atIndex:
   *                 type: integer
   *                 description: Message index to split at
   *               developerId:
   *                 type: string
   *                 description: Developer/user ID
   *     responses:
   *       200:
   *         description: New session created from split
   *       400:
   *         description: Invalid request
   */
  router.post('/:sessionId/split', async (req: any, res: any, next: any) => {
    try {
      const { sessionId } = req.params;
      const { atIndex, developerId } = req.body;

      if (typeof atIndex !== 'number' || !developerId) {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'atIndex (number) and developerId are required',
        });
      }

      const newSession = await sessionManager.splitSession(sessionId, atIndex, developerId);
      res.json(newSession);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions/{sessionId}/summarize:
   *   post:
   *     tags: [Sessions]
   *     summary: Create an artifact/brief from messages
   *     description: Create a summary artifact from a range of messages in a session
   *     parameters:
   *       - in: path
   *         name: sessionId
   *         required: true
   *         schema:
   *           type: string
   *         description: Session ID
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - fromIndex
   *               - toIndex
   *               - title
   *               - summary
   *               - developerId
   *             properties:
   *               fromIndex:
   *                 type: integer
   *                 description: Starting message index
   *               toIndex:
   *                 type: integer
   *                 description: Ending message index
   *               title:
   *                 type: string
   *                 description: Artifact title
   *               summary:
   *                 type: string
   *                 description: Summary content
   *               developerId:
   *                 type: string
   *                 description: Developer/user ID
   *     responses:
   *       200:
   *         description: Created artifact
   *       400:
   *         description: Invalid request
   */
  router.post('/:sessionId/summarize', async (req: any, res: any, next: any) => {
    try {
      const { sessionId } = req.params;
      const { fromIndex, toIndex, title, summary, developerId } = req.body;

      if (
        typeof fromIndex !== 'number' ||
        typeof toIndex !== 'number' ||
        !title ||
        !summary ||
        !developerId
      ) {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'fromIndex, toIndex, title, summary, and developerId are required',
        });
      }

      const artifact = await sessionManager.createArtifact(
        sessionId,
        fromIndex,
        toIndex,
        summary,
        title,
        developerId
      );
      
      res.json(artifact);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions/handoff:
   *   post:
   *     tags: [Sessions]
   *     summary: Create a new session from a handoff
   *     description: Create a new session when handing off work to another agent
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - toAgentId
   *               - developerId
   *               - previousSessionId
   *             properties:
   *               toAgentId:
   *                 type: string
   *                 description: Target agent ID
   *               developerId:
   *                 type: string
   *                 description: Developer/user ID
   *               previousSessionId:
   *                 type: string
   *                 description: Previous session ID
   *               transferArtifacts:
   *                 type: boolean
   *                 default: true
   *                 description: Transfer artifacts to new session
   *               transferAllowedFiles:
   *                 type: boolean
   *                 default: true
   *                 description: Transfer allowed files to new session
   *     responses:
   *       200:
   *         description: Created handoff session
   *       400:
   *         description: Invalid request
   */
  router.post('/handoff', async (req: any, res: any, next: any) => {
    try {
      const { toAgentId, developerId, previousSessionId, transferArtifacts, transferAllowedFiles } = req.body;

      if (!toAgentId || !developerId || !previousSessionId) {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'toAgentId, developerId, and previousSessionId are required',
        });
      }

      const session = await sessionManager.createHandoffSession(
        toAgentId,
        developerId,
        previousSessionId,
        transferArtifacts !== false, // default true
        transferAllowedFiles !== false // default true
      );
      res.json(session);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions/{sessionId}:
   *   patch:
   *     tags: [Sessions]
   *     summary: Update session metadata
   *     description: Update session artifacts and other metadata
   *     parameters:
   *       - in: path
   *         name: sessionId
   *         required: true
   *         schema:
   *           type: string
   *         description: Session ID
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - artifacts
   *             properties:
   *               artifacts:
   *                 type: array
   *                 items:
   *                   type: object
   *                 description: Updated artifacts array
   *     responses:
   *       200:
   *         description: Updated session
   *       400:
   *         description: Invalid request
   *       404:
   *         description: Session not found
   */
  router.patch('/:sessionId', async (req: any, res: any, next: any) => {
    try {
      const { sessionId } = req.params;
      const { artifacts } = req.body;

      if (!Array.isArray(artifacts)) {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'artifacts array is required',
        });
      }

      const session = await sessionManager.getSession(sessionId);
      if (!session) {
        return res.status(404).json({ error: 'Session not found' });
      }

      session.artifacts = artifacts;
      await sessionManager.saveSession(session);

      res.json(session);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions/{sessionId}:
   *   delete:
   *     tags: [Sessions]
   *     summary: Delete a session
   *     description: Permanently delete a session and all its messages
   *     parameters:
   *       - in: path
   *         name: sessionId
   *         required: true
   *         schema:
   *           type: string
   *         description: Session ID
   *     responses:
   *       204:
   *         description: Session deleted successfully
   *       404:
   *         description: Session not found
   */
  router.delete('/:sessionId', async (req: any, res: any, next: any) => {
    try {
      const { sessionId } = req.params;

      const session = await sessionManager.getSession(sessionId);
      if (!session) {
        return res.status(404).json({
          error: 'Session not found',
          details: `Session ${sessionId} does not exist`,
        });
      }

      await sessionManager.deleteSession(sessionId);
      res.status(204).send();
    } catch (error) {
      next(error);
    }
  });

  return router;
}

export function createArtifactsRouter(workspaceRoot: string, sharedSessionManager?: SessionManager): Router {
  const router = express.Router();
  const sessionManager = sharedSessionManager
    ?? new SessionManager(workspaceRoot, createSqliteStorage(workspaceRoot));

  if (!sharedSessionManager) {
    sessionManager.initialize().catch((error) => {
      console.error('Failed to initialize session manager:', error);
    });
  }

  /**
   * @openapi
   * /api/artifacts:
   *   get:
   *     tags: [Sessions]
   *     summary: List all artifacts
   *     description: Returns all session artifacts
   *     responses:
   *       200:
   *         description: Array of artifacts
   */
  router.get('/', async (req: any, res: any, next: any) => {
    try {
      const artifacts = await sessionManager.listArtifacts();
      res.json(artifacts);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/artifacts/{artifactId}:
   *   get:
   *     tags: [Sessions]
   *     summary: Get artifact by ID
   *     description: Returns detailed information about a specific artifact
   *     parameters:
   *       - in: path
   *         name: artifactId
   *         required: true
   *         schema:
   *           type: string
   *         description: Artifact ID
   *     responses:
   *       200:
   *         description: Artifact data
   *       404:
   *         description: Artifact not found
   */
  router.get('/:artifactId', async (req: any, res: any, next: any) => {
    try {
      const { artifactId } = req.params;
      const artifact = await sessionManager.getArtifact(artifactId);

      if (!artifact) {
        return res.status(404).json({
          error: 'Artifact not found',
          details: `Artifact ${artifactId} does not exist`,
        });
      }

      res.json(artifact);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions/merge:
   *   post:
   *     tags: [Sessions]
   *     summary: Merge two sessions
   *     description: Merge two sessions together, keeping messages from both
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - olderSessionId
   *               - newerSessionId
   *             properties:
   *               olderSessionId:
   *                 type: string
   *                 description: ID of the older session (target)
   *               newerSessionId:
   *                 type: string
   *                 description: ID of the newer session (to be merged)
   *     responses:
   *       200:
   *         description: Merged session
   *       400:
   *         description: Invalid request
   */
  router.post('/merge', async (req: any, res: any, next: any) => {
    try {
      const { olderSessionId, newerSessionId } = req.body;

      if (!olderSessionId || !newerSessionId) {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'Both olderSessionId and newerSessionId are required',
        });
      }

      if (olderSessionId === newerSessionId) {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'Cannot merge a session with itself',
        });
      }

      const mergedSession = await sessionManager.mergeSessionsIntoOlder(olderSessionId, newerSessionId);
      res.json(mergedSession);
    } catch (error) {
      next(error);
    }
  });

  /**
   * @openapi
   * /api/sessions/{sessionId}/agents:
   *   post:
   *     tags: [Sessions]
   *     summary: Add agent to session (multi-agent mode)
   *     description: Add another agent to a collaborative session
   *     parameters:
   *       - in: path
   *         name: sessionId
   *         required: true
   *         schema:
   *           type: string
   *         description: Session ID
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - agentId
   *             properties:
   *               agentId:
   *                 type: string
   *                 description: Agent ID to add
   *     responses:
   *       200:
   *         description: Updated session
   *       400:
   *         description: Invalid request
   */
  router.post('/:sessionId/agents', async (req: any, res: any, next: any) => {
    try {
      const { sessionId } = req.params;
      const { agentId } = req.body;

      if (!agentId) {
        return res.status(400).json({
          error: 'Invalid request',
          details: 'agentId is required',
        });
      }

      const updatedSession = await sessionManager.addAgentToSession(sessionId, agentId);
      res.json(updatedSession);
    } catch (error) {
      next(error);
    }
  });

  return router;
}

import { Router } from 'express';
import type { AiTeamClient } from '@ai-team/api-client';
import express from 'express';

export function createTeamRouter(client: AiTeamClient): Router {
  const router = express.Router();

  /**
   * @openapi
   * /api/team/graph:
   *   get:
   *     tags: [Team]
   *     summary: Get team hierarchy graph
   *     description: Returns the team structure as a graph with nodes (agents) and edges (relationships)
   *     parameters:
   *       - in: query
   *         name: mode
   *         schema:
   *           type: string
   *           enum: [hierarchy, collaboration, full]
   *           default: hierarchy
   *         description: Graph mode - hierarchy (org structure), collaboration (work relationships), or full (both)
   *     responses:
   *       200:
   *         description: Team graph data
   *         content:
   *           application/json:
   *             schema:
   *               type: object
   *               properties:
   *                 nodes:
   *                   type: array
   *                   items:
   *                     type: object
   *                 edges:
   *                   type: array
   *                   items:
   *                     type: object
   */
  router.get('/graph', async (req: any, res: any, next: any) => {
    try {
      const mode = (req.query.mode as string) || 'hierarchy';
      const graphData = await client.getTeamGraph(mode as any);
      res.json(graphData);
    } catch (error) {
      next(error);
    }
  });

  return router;
}

import express from 'express';
import cors from 'cors';
import { WebSocketServer } from 'ws';
import { createServer } from 'http';
import { join, resolve, dirname } from 'path';
import { existsSync } from 'fs';
import { fileURLToPath } from 'url';
import swaggerUi from 'swagger-ui-express';
import { swaggerSpec } from './swagger-auto.js';
import { generateAsyncApiSpec } from './asyncapi.js';
import { createLocalAiTeamClient } from '@ai-team/api-client';
import { AgentManager } from '@ai-team/core';
import { SessionManager, createSqliteStorage, findWorkspaceRoot, getSystemInfo } from '@ai-team/service';
import { createAgentsRouter } from './routes/agents.js';
import { createTeamRouter } from './routes/team.js';
import { createChatRouter } from './routes/chat.js';
import { createSessionsRouter, createArtifactsRouter } from './routes/sessions.js';
import { createTaskRoutes } from './routes/tasks.js';
import { createDeveloperRouter } from './routes/developer.js';
import { createFileTreeRouter } from './routes/file-tree.js';
import { createIdeRouter } from './routes/ide.js';
import { errorHandler, notFoundHandler } from './middleware/error-handler.js';
import { setupChatWebSocket } from './ws/chat-handler.js';

// ES module equivalent of __dirname
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

export interface ServerOptions {
  port?: number;
  workspaceRoot?: string;
  serveStaticFiles?: boolean;
}

export async function startServer(options: ServerOptions = {}): Promise<any> {
  const port = options.port ?? parseInt(process.env.PORT || '3002', 10);
  const workspaceRoot = options.workspaceRoot || process.env.AI_TEAM_WORKSPACE || findWorkspaceRoot();
  const serveStaticFiles = options.serveStaticFiles ?? process.env.NODE_ENV === 'production';

  console.log(`Starting AI Team API Server...`);
  console.log(`Workspace: ${workspaceRoot}`);
  console.log(`Port: ${port}`);

  // Verify workspace has .ai-team directory
  const aiTeamDir = join(workspaceRoot, '.ai-team');
  if (!existsSync(aiTeamDir)) {
    console.warn(`Warning: .ai-team directory not found at ${aiTeamDir}`);
    console.warn(`Make sure to run 'ait init' in your workspace first.`);
  }

  // Create API client
  const client = createLocalAiTeamClient(workspaceRoot);

  // Create AgentManager for fuzzy agent resolution
  const agentManager = new AgentManager(workspaceRoot);
  try {
    await agentManager.loadAllAgents();
  } catch (error) {
    console.warn('Failed to load agents:', error);
  }

  // Create SessionManager for WebSocket message persistence
  const storage = createSqliteStorage(workspaceRoot);
  const sessionManager = new SessionManager(workspaceRoot, storage, agentManager);
  await sessionManager.initialize();

  // Create Express app
  const app = express();

  // Middleware
  app.use(cors());
  app.use(express.json());

  // API Routes
  app.use('/api/agents', createAgentsRouter(client, agentManager));
  app.use('/api/team', createTeamRouter(client));
  app.use('/api/chat', createChatRouter(client, workspaceRoot, agentManager, sessionManager));
  app.use('/api/sessions', createSessionsRouter(workspaceRoot, agentManager, sessionManager));
  app.use('/api/artifacts', createArtifactsRouter(workspaceRoot, sessionManager));
  app.use('/api/tasks', createTaskRoutes(workspaceRoot, agentManager));
  app.use('/api/developer', createDeveloperRouter(client, workspaceRoot));
  app.use('/api/files', createFileTreeRouter(workspaceRoot));
  app.use('/api/ide', createIdeRouter(workspaceRoot));

  // System info endpoint
  /**
   * @openapi
   * /api/info:
   *   get:
   *     tags: [System]
   *     summary: Get system information
   *     description: Returns information about the API server and workspace
   *     responses:
   *       200:
   *         description: System information
   *         content:
   *           application/json:
   *             schema:
   *               type: object
   *               properties:
   *                 apiUrl:
   *                   type: string
   *                   description: API base URL
   *                 workspace:
   *                   type: string
   *                   description: Workspace root path
   *                 branch:
   *                   type: string
   *                   description: Current git branch
   *                 package:
   *                   type: object
   *                   properties:
   *                     name:
   *                       type: string
   *                     version:
   *                       type: string
   *                     description:
   *                       type: string
   */
  app.get('/api/info', (req, res) => {
    try {
      const apiUrl = `${req.protocol}://${req.get('host')}`;
      const systemInfo = getSystemInfo(workspaceRoot);

      res.json({
        apiUrl,
        ...systemInfo
      });
    } catch (error) {
      console.error('Error getting system info:', error);
      res.status(500).json({ 
        error: 'Failed to get system info',
        message: error instanceof Error ? error.message : String(error)
      });
    }
  });

  // Health check
  /**
   * @openapi
   * /api/health:
   *   get:
   *     tags: [Health]
   *     summary: Health check endpoint
   *     description: Returns the health status of the API server
   *     responses:
   *       200:
   *         description: Server is healthy
   *         content:
   *           application/json:
   *             schema:
   *               type: object
   *               properties:
   *                 status:
   *                   type: string
   *                   example: ok
   *                 workspace:
   *                   type: string
   *                   description: Workspace root path
   */
  app.get('/api/health', (req, res) => {
    res.json({ status: 'ok', workspace: workspaceRoot });
  });

  // Swagger API documentation
  app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerSpec, {
    customCss: '.swagger-ui .topbar { display: none }',
    customSiteTitle: 'AI Team API Documentation',
  }));

  // Swagger JSON spec endpoint
  app.get('/api-docs.json', (req, res) => {
    res.setHeader('Content-Type', 'application/json');
    res.send(swaggerSpec);
  });

  // AsyncAPI WebSocket documentation
  const asyncApiSpec = generateAsyncApiSpec();
  
  app.get('/asyncapi.json', (req, res) => {
    res.setHeader('Content-Type', 'application/json');
    res.json(asyncApiSpec);
  });

  app.get('/asyncapi', (req, res) => {
    res.send(`
<!DOCTYPE html>
<html>
<head>
  <title>AI Team WebSocket API Documentation</title>
  <link rel="stylesheet" href="https://unpkg.com/@asyncapi/react-component@1.4.10/styles/default.min.css">
  <style>
    body { margin: 0; padding: 0; }
    #asyncapi { height: 100vh; overflow: auto; }
  </style>
</head>
<body>
  <div id="asyncapi"></div>
  <script src="https://unpkg.com/@asyncapi/react-component@1.4.10/browser/standalone/index.js"></script>
  <script>
    AsyncApiStandalone.render({
      schema: {
        url: '/asyncapi.json'
      },
      config: {
        show: {
          sidebar: true
        }
      }
    }, document.getElementById('asyncapi'));
  </script>
</body>
</html>
    `);
  });

  // Serve avatars directory as static files
  const avatarsPath = join(workspaceRoot, '.ai-team', 'avatars');
  if (existsSync(avatarsPath)) {
    app.use('/avatars', express.static(avatarsPath));
    console.log(`Serving avatars from: ${avatarsPath}`);
  }

  // Serve static files from web build (production mode)
  if (serveStaticFiles) {
    const webDistPath = resolve(join(__dirname, '..', '..', 'web', 'dist'));
    if (existsSync(webDistPath)) {
      console.log(`Serving static files from: ${webDistPath}`);
      app.use(express.static(webDistPath));
      
      // SPA fallback - serve index.html for all non-API routes
      app.get('*', (req, res, next) => {
        if (req.path.startsWith('/api') || req.path.startsWith('/ws')) {
          return next();
        }
        res.sendFile(join(webDistPath, 'index.html'));
      });
    } else {
      console.warn(`Web dist directory not found at ${webDistPath}`);
      console.warn(`Run 'pnpm --filter @ai-team/web build' to build the web UI.`);
    }
  }

  // Error handlers (must be last)
  app.use(notFoundHandler);
  app.use(errorHandler);

  // Create HTTP server
  const httpServer = createServer(app);

  // Setup WebSocket server (without path restriction to allow /ws/chat/:agentId)
  const wss = new WebSocketServer({ 
    server: httpServer,
    noServer: false,
  });

  wss.on('connection', (ws, req) => {
    // Check if this is a chat WebSocket connection
    if (!req.url?.startsWith('/ws/chat/')) {
      ws.send(JSON.stringify({ type: 'error', data: { error: 'Invalid WebSocket path' } }));
      ws.close();
      return;
    }

    // Extract agent ID from URL path: /ws/chat/:agentId?sessionId=xxx
    const url = new URL(req.url, `http://${req.headers.host}`);
    const pathParts = url.pathname.split('/').filter(Boolean);
    const agentId = pathParts && pathParts.length >= 3 ? pathParts[2] : '';
    const sessionId = url.searchParams.get('sessionId');

    if (!agentId) {
      ws.send(JSON.stringify({ type: 'error', data: { error: 'Agent ID is required' } }));
      ws.close();
      return;
    }

    console.log(`WebSocket connected: agent=${agentId}, session=${sessionId || 'none'}`);
    setupChatWebSocket(ws, agentId, client, sessionManager, sessionId, agentManager, workspaceRoot);
  });

  // Start server
  await new Promise<void>((resolve) => {
    httpServer.listen(port, () => {
      const addr = httpServer.address() as { port: number } | null;
      const actualPort = addr?.port ?? port;
      console.log(`✓ Server listening on http://localhost:${actualPort}`);
      console.log(`✓ API available at http://localhost:${actualPort}/api`);
      console.log(`✓ API Documentation available at http://localhost:${actualPort}/api-docs`);
      console.log(`✓ WebSocket Documentation available at http://localhost:${actualPort}/asyncapi`);
      console.log(`✓ WebSocket available at ws://localhost:${actualPort}/ws/chat/:agentId`);
      resolve();
    });
  });

  // Graceful shutdown
  const shutdown = async () => {
    console.log('\nShutting down server...');
    wss.close();
    await storage.close();
    httpServer.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  };

  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);

  return { app, httpServer, wss, storage };
}

// Start server if this file is run directly
if (import.meta.url === `file://${process.argv[1]}`) {
  startServer().catch((error) => {
    console.error('Failed to start server:', error);
    process.exit(1);
  });
}

import type { WebSocket } from 'ws';
import type { AiTeamClient } from '@ai-team/api-client';
import type { AgentManager } from '@ai-team/core';
import type { QuestionInputRequest, QuestionConfirmRequest, QuestionSelectRequest, QuestionPasswordRequest, QuestionChecklistRequest } from '@ai-team/service';
import { resolveAgentForOperation, SessionManager } from '@ai-team/service';
import { createIdeAdapter, type IdeAdapter } from '@ai-team/ide-interface';

/**
 * Messages sent from client to server over WebSocket.
 * 
 * @example Send a chat message
 * ```json
 * {
 *   "type": "message",
 *   "content": "What tasks are assigned to me?",
 *   "options": {}
 * }
 * ```
 * 
 * @example Cancel an ongoing operation
 * ```json
 * {
 *   "type": "cancel"
 * }
 * ```
 * 
 * @example Answer an agent question
 * ```json
 * {
 *   "type": "answer",
 *   "answer": {
 *     "questionId": "q1",
 *     "value": "my-branch-name"
 *   }
 * }
 * ```
 */
export interface ChatWebSocketMessage {
  /** Message type: 'message' = chat message, 'cancel' = abort operation, 'answer' = respond to question */
  type: 'message' | 'cancel' | 'answer';
  /** Chat message content (required for 'message' type) */
  content?: string;
  /** Additional options for the chat interaction (optional for 'message' type) */
  options?: any;
  /** Answer to a question (required for 'answer' type) */
  answer?: {
    /** Question ID from the QuestionEvent */
    questionId: string;
    /** Answer value (string for input/select/password, boolean for confirm, string[] for checklist) */
    value: string | boolean | string[];
  };
}

/**
 * Events sent from server to client over WebSocket.
 * 
 * @example Streaming token
 * ```json
 * {
 *   "type": "token",
 *   "data": { "token": "Hello" }
 * }
 * ```
 * 
 * @example Status update
 * ```json
 * {
 *   "type": "status",
 *   "data": { "status": "ready" }
 * }
 * ```
 * 
 * @example Agent question
 * ```json
 * {
 *   "type": "question",
 *   "data": {
 *     "questionId": "q1",
 *     "kind": "input",
 *     "message": "What branch name?"
 *   }
 * }
 * ```
 * 
 * @example Error
 * ```json
 * {
 *   "type": "error",
 *   "data": { "error": "Agent not found" }
 * }
 * ```
 * 
 * @example Completion
 * ```json
 * {
 *   "type": "done"
 * }
 * ```
 */
export interface ChatWebSocketEvent {
  /** Event type: 'token' = streaming text, 'status' = status update, 'tool' = tool execution, 'question' = agent question, 'error' = error occurred, 'done' = response complete */
  type: 'token' | 'status' | 'tool' | 'question' | 'error' | 'done';
  /** Event payload (structure varies by event type) */
  data?: any;
}

export function setupChatWebSocket(
  ws: WebSocket,
  agentQuery: string,
  client: AiTeamClient,
  sessionManager: SessionManager,
  sessionId: string | null,
  agentManager?: AgentManager,
  workspaceRoot?: string,
): void {
  // Resolve agent query to exact ID
  let agentId = agentQuery;
  if (agentManager) {
    try {
      const resolved = resolveAgentForOperation(agentManager, agentQuery, 'WebSocket chat');
      agentId = resolved.id;
    } catch (error) {
      // Send error and close connection
      ws.send(JSON.stringify({
        type: 'error',
        data: { error: error instanceof Error ? error.message : 'Failed to resolve agent' },
      }));
      ws.close();
      return;
    }
  }

  // Connect to VS Code plugin if it is running for this workspace (fire-and-forget init)
  let ideAdapter: IdeAdapter | null = null;
  if (workspaceRoot) {
    createIdeAdapter(workspaceRoot, 'web').then(adapter => {
      ideAdapter = adapter;
    }).catch(() => { /* no IDE connected — silent */ });
  }

  let currentAbortController: AbortController | null = null;
  let questionCounter = 0;
  const pendingQuestions = new Map<string, {
    resolve: (value: any) => void;
    reject: (error: Error) => void;
  }>();

  // Helper to wait for answer from client
  const askQuestion = async (questionId: string, questionData: any): Promise<any> => {
    return new Promise((resolve, reject) => {
      pendingQuestions.set(questionId, { resolve, reject });
      
      // Send question to client
      ws.send(JSON.stringify({
        type: 'question',
        data: {
          questionId,
          ...questionData,
        },
      }));

        // No timeout: questions can remain pending until answered or connection closes.
    });
  };

  ws.on('message', async (data: Buffer) => {
    try {
      const message: ChatWebSocketMessage = JSON.parse(data.toString());

      if (message.type === 'answer') {
        // Handle answer to a pending question
        if (message.answer) {
          const { questionId, value } = message.answer;
          const pending = pendingQuestions.get(questionId);
          if (pending) {
            pendingQuestions.delete(questionId);
            pending.resolve(value);
          }
        }
        return;
      }

      if (message.type === 'cancel') {
        // Cancel current operation
        if (currentAbortController) {
          currentAbortController.abort();
          currentAbortController = null;
        }
        // Cancel all pending questions
        pendingQuestions.forEach(({ reject }) => reject(new Error('Cancelled')));
        pendingQuestions.clear();
        ws.send(JSON.stringify({ type: 'status', data: { status: 'cancelled' } }));
        return;
      }

      if (message.type === 'message') {
        if (!message.content) {
          ws.send(JSON.stringify({ type: 'error', data: { error: 'Message content is required' } }));
          return;
        }

        // Cancel any existing operation
        if (currentAbortController) {
          currentAbortController.abort();
        }

        // Cancel any pending questions
        pendingQuestions.forEach(({ reject }) => reject(new Error('New message started')));
        pendingQuestions.clear();

        // Create new abort controller for this operation
        currentAbortController = new AbortController();

        try {
          // Message persistence is handled by the service layer (chatCommand/sendMessage)
          // — no need to save user or assistant messages here.

          // Stream chat response with question handlers
          const stream = client.stream(
            {
              command: 'chat',
              payload: {
                employeeId: agentId,
                options: {
                  message: message.content,
                  sessionId: sessionId ?? undefined,
                  ...message.options,
                },
              },
            },
            {
              signal: currentAbortController.signal,
              questionInput: async (request: QuestionInputRequest) => {
                const questionId = `q${++questionCounter}`;
                return askQuestion(questionId, { kind: 'input', ...request });
              },
              questionConfirm: async (request: QuestionConfirmRequest) => {
                const questionId = `q${++questionCounter}`;
                return askQuestion(questionId, { kind: 'confirm', ...request });
              },
              questionSelect: async (request: QuestionSelectRequest) => {
                const questionId = `q${++questionCounter}`;
                return askQuestion(questionId, { kind: 'select', ...request });
              },
              questionPassword: async (request: QuestionPasswordRequest) => {
                const questionId = `q${++questionCounter}`;
                return askQuestion(questionId, { kind: 'password', ...request });
              },
              questionChecklist: async (request: QuestionChecklistRequest) => {
                const questionId = `q${++questionCounter}`;
                return askQuestion(questionId, { kind: 'checklist', ...request });
              },
            }
          );

          for await (const event of stream) {
            // Check if cancelled
            if (currentAbortController.signal.aborted) {
              break;
            }

            // Forward code-edit proposals to VS Code plugin
            if ((event.kind as string) === 'code_edit_proposal' && ideAdapter) {
              const e = event as any;
              ideAdapter.notifyCodeEditProposal({
                proposalId: e.proposalId ?? '',
                agentName: e.agentName ?? agentId,
                description: e.description ?? '',
                files: (e.files ?? []).map((f: any) => ({
                  filePath: f.filePath,
                  oldContent: f.oldContent ?? '',
                  newContent: f.newContent ?? '',
                  additions: f.additions ?? 0,
                  deletions: f.deletions ?? 0,
                })),
              }).catch(() => { /* best-effort */ });
            }

            // Send event to client
            const wsEvent: ChatWebSocketEvent = {
              type: event.kind as any,
              data: event,
            };
            ws.send(JSON.stringify(wsEvent));
          }

          // Send done event
          if (!currentAbortController.signal.aborted) {
            ws.send(JSON.stringify({ type: 'done' }));
          }
        } catch (error: any) {
          // Check if it was an abort
          if (error.name === 'AbortError' || currentAbortController?.signal.aborted) {
            ws.send(JSON.stringify({ type: 'status', data: { status: 'cancelled' } }));
          } else {
            ws.send(JSON.stringify({ type: 'error', data: { error: error.message } }));
          }
          // Always send done event to signal completion, even after errors
          ws.send(JSON.stringify({ type: 'done' }));
        } finally {
          currentAbortController = null;
        }
      }
    } catch (error: any) {
      ws.send(JSON.stringify({ type: 'error', data: { error: error.message } }));
    }
  });

  ws.on('close', () => {
    // Clean up on disconnect
    if (currentAbortController) {
      currentAbortController.abort();
      currentAbortController = null;
    }
    // Reject all pending questions
    pendingQuestions.forEach(({ reject }) => reject(new Error('Connection closed')));
    pendingQuestions.clear();
    ideAdapter?.dispose();
  });

  ws.on('error', (error) => {
    console.error('WebSocket error:', error);
    if (currentAbortController) {
      currentAbortController.abort();
      currentAbortController = null;
    }
    // Reject all pending questions
    pendingQuestions.forEach(({ reject }) => reject(new Error('Connection error')));
    pendingQuestions.clear();
  });

  // Send ready event
  ws.send(JSON.stringify({ type: 'status', data: { status: 'ready' } }));
}

import type { AiTeamClient, ChatOptions } from '@ai-team/api-client';
import type {
  MediatorContext,
  QuestionChecklistRequest,
  QuestionConfirmRequest,
  QuestionInputRequest,
  QuestionPasswordRequest,
  QuestionSelectRequest,
} from '@ai-team/api-client';
import { createIdeAdapter } from '@ai-team/ide-interface';
import { findWorkspaceRoot } from '@ai-team/service';
import chalk from 'chalk';
import { createInterface } from 'node:readline/promises';
import { stdin as input, stdout as output } from 'node:process';
import { isFrontendFileLogEnabled, writeFrontendDebugLog } from './debug-log.js';

function setupAbortController(writeStderrLine: (text: string) => void) {
  const controller = new AbortController();
  let abortRequested = false;
  let forceExitTimer: NodeJS.Timeout | undefined;

  const requestAbort = (signalName: 'SIGINT' | 'SIGTERM') => {
    if (abortRequested) {
      process.exit(130);
      return;
    }

    abortRequested = true;
    writeStderrLine(chalk.yellow(`Received ${signalName}, aborting...`));
    controller.abort(new Error(`Aborted by ${signalName}`));
    forceExitTimer = setTimeout(() => {
      writeStderrLine(chalk.yellow('Abort timed out, forcing exit.'));
      process.exit(130);
    }, 1500);
    forceExitTimer.unref();
  };

  const onSigint = () => requestAbort('SIGINT');
  const onSigterm = () => requestAbort('SIGTERM');
  process.on('SIGINT', onSigint);
  process.on('SIGTERM', onSigterm);

  return {
    signal: controller.signal,
    wasAborted: () => abortRequested,
    dispose: () => {
      if (forceExitTimer) {
        clearTimeout(forceExitTimer);
        forceExitTimer = undefined;
      }
      process.off('SIGINT', onSigint);
      process.off('SIGTERM', onSigterm);
    },
  };
}

function isAbortLikeError(error: unknown): boolean {
  const message = error instanceof Error ? error.message : String(error);
  return /aborted|abort/i.test(message);
}

async function askLine(message: string, signal?: AbortSignal): Promise<string> {
  const rl = createInterface({ input, output });
  try {
    return (await rl.question(`${message} `, { signal })).trim();
  } finally {
    rl.close();
  }
}

function createChatQuestionResponders(signal: AbortSignal): Pick<
  MediatorContext,
  'questionInput' | 'questionConfirm' | 'questionSelect' | 'questionPassword' | 'questionChecklist'
> {
  return {
    questionInput: async (request: QuestionInputRequest) => {
      while (true) {
        const value = await askLine(request.message, signal);
        if (!request.validate) {
          return value;
        }

        const validation = await request.validate(value);
        if (validation === true || validation === undefined) {
          return value;
        }

        if (typeof validation === 'string' && validation.trim().length > 0) {
          process.stderr.write(`${validation}\n`);
        }
      }
    },
    questionConfirm: async (request: QuestionConfirmRequest) => {
      const defaultValue = request.default ?? false;
      const suffix = defaultValue ? '[Y/n]' : '[y/N]';

      while (true) {
        const raw = (await askLine(`${request.message} ${suffix}`, signal)).toLowerCase();
        if (!raw) {
          return defaultValue;
        }
        if (raw === 'y' || raw === 'yes') {
          return true;
        }
        if (raw === 'n' || raw === 'no') {
          return false;
        }
        process.stderr.write('Please answer yes or no.\n');
      }
    },
    questionSelect: async (request: QuestionSelectRequest) => {
      process.stdout.write(`${request.message}\n`);
      request.choices.forEach((choice, index) => {
        process.stdout.write(`  ${index + 1}) ${choice.name}\n`);
      });

      while (true) {
        const answer = await askLine('Select a number:', signal);
        const selectedIndex = Number.parseInt(answer, 10) - 1;
        if (Number.isInteger(selectedIndex) && selectedIndex >= 0 && selectedIndex < request.choices.length) {
          return request.choices[selectedIndex]!.value;
        }
        process.stderr.write('Invalid selection.\n');
      }
    },
    questionPassword: async (request: QuestionPasswordRequest) => {
      return askLine(request.message, signal);
    },
    questionChecklist: async (request: QuestionChecklistRequest) => {
      process.stdout.write(`${request.message}\n`);
      request.choices.forEach((choice, index) => {
        process.stdout.write(`  ${index + 1}) ${choice.name}\n`);
      });

      while (true) {
        const answer = await askLine('Select numbers separated by comma (or empty for none):', signal);
        if (!answer) {
          return [];
        }

        const indices = answer
          .split(',')
          .map(part => Number.parseInt(part.trim(), 10) - 1)
          .filter(index => Number.isInteger(index));

        const inRange = indices.every(index => index >= 0 && index < request.choices.length);
        if (!inRange) {
          process.stderr.write('Invalid checklist selection.\n');
          continue;
        }

        const values = [...new Set(indices)].map(index => request.choices[index]!.value);
        return values;
      }
    },
  };
}

function handleOneShotEvent(
  event: Awaited<ReturnType<AiTeamClient['stream']>> extends AsyncIterable<infer TEvent> ? TEvent : never,
  writeStderrLine: (text: string) => void,
): void {
  if (event.kind === 'status' && event.message) {
    writeStderrLine(chalk.dim(`[backend:mediator:${event.command}] ${event.message}`));
    return;
  }

  if (event.kind === 'question') {
    writeStderrLine(chalk.yellow(`[frontend:question:${event.questionType || 'input'}] ${event.message}`));
    return;
  }

  if (event.kind === 'tool') {
    const phase = event.toolPhase || 'event';
    const suffix = event.message ? ' — ' + event.message : '';
    writeStderrLine(chalk.cyan(`[backend:tool:${phase}] ${event.toolName}${suffix}`));
    return;
  }

  if (event.kind === 'error') {
    throw new Error(event.message);
  }
}

function isEssentialInteractiveInfo(message: string): boolean {
  const normalized = message.trim();
  if (!normalized) {
    return false;
  }

  return /^(loading |validating |initializing |connecting to |connected to |chat with |switched to |type "\/help"|type "exit"|\(\d+ previous messages loaded\)|goodbye!|session: |new session started: )/i.test(normalized);
}

async function handleCodeEditProposal(
  event: any,
  writeStderrLine: (text: string) => void,
  isOneShot: boolean,
  workspaceRoot: string,
): Promise<void> {
  const { proposalId, description, filesChanged, additions, deletions, warnings } = event;

  // Display proposal summary
  writeStderrLine('');
  writeStderrLine(chalk.bold.cyan('📝 Code Edit Proposal'));
  writeStderrLine(chalk.gray('─'.repeat(60)));
  writeStderrLine(`${chalk.bold('ID:')} ${proposalId}`);
  writeStderrLine(`${chalk.bold('Description:')} ${description}`);
  writeStderrLine(`${chalk.bold('Files:')} ${filesChanged}`);
  writeStderrLine(`${chalk.bold('Changes:')} ${chalk.green(`+${additions}`)} ${chalk.red(`-${deletions}`)}`);
  
  if (warnings && warnings.length > 0) {
    writeStderrLine('');
    writeStderrLine(chalk.yellow('⚠️  Warnings:'));
    warnings.forEach((warning: string) => {
      writeStderrLine(chalk.yellow(`   • ${warning}`));
    });
  }
  
  writeStderrLine(chalk.gray('─'.repeat(60)));

  // Notify VS Code plugin (best-effort, non-blocking)
  createIdeAdapter(workspaceRoot, 'cli').then(adapter => {
    if (adapter.isConnected()) {
      return adapter.notifyCodeEditProposal({
        proposalId: event.proposalId ?? '',
        agentName: event.agentName ?? '',
        description: event.description ?? '',
        files: (event.files ?? []).map((f: any) => ({
          filePath: f.filePath,
          oldContent: f.oldContent ?? '',
          newContent: f.newContent ?? '',
          additions: f.additions ?? 0,
          deletions: f.deletions ?? 0,
        })),
      }).then(() => adapter.dispose());
    }
    adapter.dispose();
  }).catch(() => { /* VS Code not running — silent */ });

  // In one-shot mode, just log and continue
  if (isOneShot) {
    writeStderrLine(chalk.dim('Run with --interactive to review and apply proposals'));
    return;
  }

  // Interactive mode: ask for approval
  const rl = createInterface({ input, output: process.stderr });
  
  try {
    const answer = await rl.question(
      chalk.yellow('Review this proposal? [y/n/view] (y): ')
    );
    
    const choice = (answer || 'y').toLowerCase().trim();
    
    if (choice === 'view' || choice === 'v') {
      writeStderrLine(chalk.dim('Detailed diff view requires VS Code extension or web UI'));
      writeStderrLine(chalk.dim(`Proposal ID: ${proposalId}`));
    } else if (choice === 'y' || choice === 'yes') {
      writeStderrLine(chalk.green('✅ Proposal accepted for review'));
      writeStderrLine(chalk.dim('Use the VS Code extension or web UI to apply changes'));
    } else {
      writeStderrLine(chalk.red('❌ Proposal review skipped'));
    }
  } finally {
    rl.close();
  }
  
  writeStderrLine('');
}

export async function chatCommand(client: AiTeamClient, agentId: string | undefined, options: ChatOptions, mediatorLog: boolean = false) {
  const mediatorLoggerEnabled = mediatorLog || process.env.AI_TEAM_MEDIATOR_LOG === '1';
  const frontendFileLogEnabled = isFrontendFileLogEnabled();
  const workspaceRoot = findWorkspaceRoot();
  const writeStderrLine = (text: string) => {
    process.stderr.write(`${text}\n`);
  };
  const streamOut = options.oneShot ? process.stdout : process.stderr;
  const abortControl = setupAbortController(writeStderrLine);

  try {
    for await (const event of client.stream({
      command: 'chat',
      payload: {
        employeeId: agentId,
        options,
      },
    }, {
      ...createChatQuestionResponders(abortControl.signal),
      signal: abortControl.signal,
      logger: mediatorLoggerEnabled || frontendFileLogEnabled
        ? (entry) => {
            if (frontendFileLogEnabled) {
              writeFrontendDebugLog({ command: 'chat', channel: entry.channel, event: entry.event });
            }
            try {
              if (mediatorLoggerEnabled) {
                writeStderrLine(`${chalk.gray('[frontend:mediator-log]')} ${JSON.stringify(entry)}`);
              }
            } catch {
              if (mediatorLoggerEnabled) {
                writeStderrLine(`${chalk.gray('[frontend:mediator-log]')} ${String(entry)}`);
              }
            }
          }
        : undefined,
    })) {
      if (event.kind === 'token') {
        streamOut.write(event.text);
        continue;
      }

      if (event.kind === 'aborted') {
        writeStderrLine(chalk.yellow('Chat aborted.'));
        process.exitCode = 130;
        return;
      }

      if (event.kind === 'status' && event.message) {
        if (options.oneShot || mediatorLoggerEnabled) {
          writeStderrLine(chalk.dim(`[backend:mediator:${event.command}] ${event.message}`));
        }
        continue;
      }

      if (event.kind === 'tool') {
        const phase = event.toolPhase || 'event';
        const suffix = event.message ? chalk.gray(` — ${event.message}`) : '';
        writeStderrLine(`${chalk.cyan(`[backend:tool:${phase}]`)} ${chalk.white(event.toolName)}${suffix}`);
        continue;
      }

      // Handle code edit proposals
      if ('kind' in event && (event as any).kind === 'code_edit_proposal') {
        await handleCodeEditProposal(event as any, writeStderrLine, options.oneShot || false, workspaceRoot);
        continue;
      }

      // Handle agent handoff — print a single clean transition line
      if ('kind' in event && (event as any).kind === 'handoff') {
        const e = event as any;
        const from = e.fromAgentName || e.fromAgentId;
        const to = e.toAgentName || e.toAgentId;
        const note = e.handoffNote ? `: ${e.handoffNote}` : '';
        writeStderrLine('');
        writeStderrLine(chalk.bold(`${from}`) + chalk.dim(' → ') + chalk.bold(`${to}`) + chalk.dim(note));
        writeStderrLine('');
        continue;
      }

      if (event.kind === 'question') {
        if (frontendFileLogEnabled) {
          writeFrontendDebugLog({ command: 'chat', event });
        }
        if (options.oneShot || mediatorLoggerEnabled) {
          writeStderrLine(chalk.yellow(`[frontend:question:${event.questionType || 'input'}] ${event.message}`));
        }
        continue;
      }

      if (event.kind === 'log') {
        const line = `${event.message}\n`;
        if (event.level === 'error') {
          process.stderr.write(chalk.red(line));
        } else if (event.level === 'warn') {
          process.stderr.write(chalk.yellow(line));
        } else {
          if (mediatorLoggerEnabled || options.oneShot || isEssentialInteractiveInfo(event.message)) {
            streamOut.write(chalk.dim(line));
          }
        }
        continue;
      }

      if (event.kind === 'error') {
        if (abortControl.wasAborted() || isAbortLikeError(event.message)) {
          writeStderrLine(chalk.yellow('Chat aborted.'));
          process.exitCode = 130;
          return;
        }
        throw new Error(event.message);
      }

      if (options.oneShot) {
        handleOneShotEvent(event, writeStderrLine);
      }
    }
  } catch (error) {
    if (abortControl.wasAborted() || isAbortLikeError(error)) {
      writeStderrLine(chalk.yellow('Chat aborted.'));
      process.exitCode = 130;
      return;
    }
    throw error;
  } finally {
    abortControl.dispose();
  }
}

/**
 * Graph command - visualize team structure
 */

import chalk from 'chalk';
import type { AiTeamClient } from '@ai-team/api-client';
import { ViewMode } from '@ai-team/core';

interface GraphOptions {
  mode?: string;
  output?: string;
}

export async function graphCommand(client: AiTeamClient, options: GraphOptions) {
  try {
    const mode = (options.mode || 'hierarchy') as ViewMode;
    const graphData = await client.getTeamGraph(mode);

    if (options.output) {
      // Export to file
      const fs = await import('fs/promises');
      if (options.output.endsWith('.json')) {
        await fs.writeFile(options.output, JSON.stringify(graphData, null, 2));
        console.log(chalk.green(`✓ Exported graph to ${options.output}`));
      } else {
        console.log(chalk.yellow('Only JSON export is currently supported'));
        console.log(chalk.dim('Use --output graph.json'));
      }
      return;
    }

    // Print ASCII representation
    console.log(chalk.bold(`\nTeam Graph (${mode} view)\n`));
    console.log(chalk.dim(`Nodes: ${graphData.nodes.length}`));
    console.log(chalk.dim(`Edges: ${graphData.edges.length}\n`));

    // Simple hierarchical text view
    if (mode === 'hierarchy') {
      printHierarchy(graphData);
    } else {
      console.log(chalk.yellow('ASCII visualization only available for hierarchy mode'));
      console.log(chalk.dim('Use --output graph.json for full data'));
      console.log(chalk.dim('Or use the web dashboard for interactive visualization'));
    }
  } catch (error) {
    console.error(chalk.red('Error generating graph:'), error);
    process.exit(1);
  }
}

function printHierarchy(graphData: any) {
  const { nodes, edges } = graphData;
  
  // Find roots (no incoming reports-to edges)
  const hasManager = new Set(
    edges
      .filter((e: any) => e.type === 'reports-to')
      .map((e: any) => e.source)
  );
  
  const roots = nodes.filter((n: any) => !hasManager.has(n.id));
  
  const printed = new Set<string>();
  
  function printNode(nodeId: string, indent: number = 0) {
    if (printed.has(nodeId)) return;
    printed.add(nodeId);
    
    const node = nodes.find((n: any) => n.id === nodeId);
    if (!node) return;
    
    const prefix = '  '.repeat(indent);
    const status = node.data.status ? getStatusIcon(node.data.status) : '○';
    
    console.log(`${prefix}${status} ${chalk.cyan(node.data.label)} ${chalk.dim(`(${node.data.role})`)}`);
    
    // Find direct reports
    const reports = edges
      .filter((e: any) => e.type === 'reports-to' && e.target === nodeId)
      .map((e: any) => e.source);
    
    for (const reportId of reports) {
      printNode(reportId, indent + 1);
    }
  }
  
  // Print hierarchy starting from roots
  for (const root of roots) {
    printNode(root.id);
  }
  
  // Print agents with broken parent references
  const brokenEdges = edges.filter((e: any) => e.type === 'reports-to-unresolved');
  
  if (brokenEdges.length > 0) {
    console.log();
    console.log(chalk.yellow('⚠ Unresolved reporting relationships:'));
    
    for (const edge of brokenEdges) {
      const node = nodes.find((n: any) => n.id === edge.source);
      if (node) {
        const icon = chalk.red('✗');
        console.log(`  ${icon} ${chalk.cyan(node.data.label)} ${chalk.dim(`(${node.data.role})`)} → ${chalk.red(`[${edge.target}]`)}`);
        if (edge.error) {
          console.log(`    ${chalk.dim(edge.error)}`);
        }
      }
    }
  }
}

function getStatusIcon(status: string): string {
  switch (status) {
    case 'available':
      return chalk.green('●');
    case 'busy':
      return chalk.yellow('●');
    case 'in-meeting':
      return chalk.blue('●');
    case 'offline':
      return chalk.gray('●');
    default:
      return chalk.gray('○');
  }
}

/**
 * Org command - quick organization overview (hierarchy)
 */

import chalk from 'chalk';
import type { AiTeamClient } from '@ai-team/api-client';

interface OrgOptions {
  mermaid?: boolean;
  output?: string;
}

export async function orgCommand(client: AiTeamClient, options: OrgOptions) {
  try {
    const graphData = await client.getOrganizationGraph();

    if (!graphData.nodes.length) {
      console.log(chalk.yellow('\n⚠ No agents found in this workspace.'));
      console.log(chalk.dim('  Run "ait init" to set up your AI team,'));
      console.log(chalk.dim('  or use "ait hire" / "ait create" to add agents.'));
      return;
    }

    if (options.mermaid) {
      const mermaid = buildMermaid(graphData);

      if (options.output) {
        const fs = await import('fs/promises');
        await fs.writeFile(options.output, mermaid, 'utf-8');
        console.log(chalk.green(`✓ Exported Mermaid org chart to ${options.output}`));
      } else {
        console.log(mermaid);
      }
      return;
    }

    if (options.output) {
      const fs = await import('fs/promises');
      if (options.output.endsWith('.json')) {
        await fs.writeFile(options.output, JSON.stringify(graphData, null, 2));
        console.log(chalk.green(`✓ Exported org graph to ${options.output}`));
      } else {
        console.log(chalk.yellow('Only JSON export is currently supported for --output'));
        console.log(chalk.dim('Use --mermaid to export a Mermaid diagram instead.'));
      }
      return;
    }

    console.log(chalk.bold('\nOrganization (hierarchy view)\n'));
    console.log(chalk.dim(`Nodes: ${graphData.nodes.length}`));
    console.log(chalk.dim(`Edges: ${graphData.edges.length}\n`));

    printHierarchy(graphData);
  } catch (error) {
    console.error(chalk.red('Error generating organization view:'), error);
    process.exit(1);
  }
}

function printHierarchy(graphData: any) {
  const { nodes, edges } = graphData;

  const hasManager = new Set(
    edges
      .filter((e: any) => e.type === 'reports-to')
      .map((e: any) => e.source)
  );

  const roots = nodes.filter((n: any) => !hasManager.has(n.id));

  const printed = new Set<string>();

  function printNode(nodeId: string, indent: number = 0) {
    if (printed.has(nodeId)) return;
    printed.add(nodeId);

    const node = nodes.find((n: any) => n.id === nodeId);
    if (!node) return;

    const prefix = '  '.repeat(indent);
    const status = node.data.status ? getStatusIcon(node.data.status) : '○';

    console.log(`${prefix}${status} ${chalk.cyan(node.data.label)} ${chalk.dim(`(${node.data.role})`)}`);

    const reports = edges
      .filter((e: any) => e.type === 'reports-to' && e.target === nodeId)
      .map((e: any) => e.source);

    for (const reportId of reports) {
      printNode(reportId, indent + 1);
    }
  }

  for (const root of roots) {
    printNode(root.id);
  }
}

function getStatusIcon(status: string): string {
  switch (status) {
    case 'available':
      return chalk.green('●');
    case 'busy':
      return chalk.yellow('●');
    case 'in-meeting':
      return chalk.blue('●');
    case 'offline':
      return chalk.gray('●');
    default:
      return chalk.gray('○');
  }
}

function buildMermaid(graphData: any): string {
  const { nodes, edges } = graphData;

  const lines: string[] = ['graph TD'];

  for (const node of nodes) {
    const id = node.id;
    const label = `${node.data.label} (${node.data.role})`;
    const safeLabel = label.replace(/"/g, '\\"');
    lines.push(`  ${id}["${safeLabel}"]`);
  }

  for (const edge of edges) {
    if (edge.type !== 'reports-to') continue;
    const reportId = edge.source;
    const managerId = edge.target;
    lines.push(`  ${managerId} --> ${reportId}`);
  }

  return lines.join('\n');
}

/**
 * Search command - search for agents with fuzzy matching
 */

import chalk from 'chalk';
import type { AiTeamClient } from '@ai-team/api-client';

interface SearchOptions {
  role?: string | string[];
  type?: string | string[];
  status?: string | string[];
  feature?: string | string[];
  specialization?: string | string[];
  tool?: string | string[];
  reportsTo?: string;
  contextLevel?: string | string[];
  json?: boolean;
}

export async function searchCommand(
  client: AiTeamClient,
  query: string | undefined,
  options: SearchOptions
) {
  try {
    const request = {
      query,
      role: options.role,
      type: options.type as any,
      status: options.status as any,
      feature: options.feature,
      specialization: options.specialization,
      tool: options.tool,
      reportsTo: options.reportsTo,
      contextLevel: options.contextLevel as any,
    };

    const response = await client.searchAgents(request);

    if (options.json) {
      console.log(JSON.stringify(response, null, 2));
      return;
    }

    // Pretty print compact results
    if (response.results.length === 0) {
      console.log(chalk.yellow('No agents found.'));
      if (query) {
        console.log(chalk.dim(`Try a different search term or run 'ait list' to see all agents.`));
      }
      return;
    }

    const hasFilters = !!(options.role || options.type || options.status || options.feature || 
                          options.specialization || options.tool || options.reportsTo || options.contextLevel);
    
    if (query && hasFilters) {
      console.log(chalk.bold(`\nFound ${response.totalCount} agents matching "${query}" with filters:\n`));
    } else if (query) {
      console.log(chalk.bold(`\nFound ${response.totalCount} agents matching "${query}":\n`));
    } else {
      console.log(chalk.bold(`\nFound ${response.totalCount} agents:\n`));
    }

    for (const result of response.results) {
      const agent = result.agent;
      const status = getStatusIcon(agent.status);
      
      // Build compact one-line output
      const badges: string[] = [];
      
      // Add specializations as badges (max 3)
      if (agent.specializations && agent.specializations.length > 0) {
        const specs = agent.specializations.slice(0, 3);
        specs.forEach(s => badges.push(chalk.blue(`[${s}]`)));
        if (agent.specializations.length > 3) {
          badges.push(chalk.dim(`+${agent.specializations.length - 3}`));
        }
      }
      
      // Build match preview
      const matchPreview = result.matches.length > 0 
        ? chalk.dim(`matched: ${result.matches.join(', ')}`)
        : '';
      
      // Score indicator for debugging (optional)
      const scoreIndicator = result.score >= 90 ? chalk.green('★★★') : 
                            result.score >= 70 ? chalk.green('★★') :
                            result.score >= 50 ? chalk.yellow('★') : '';
      
      const badgesStr = badges.length > 0 ? ' ' + badges.join(' ') : '';
      const matchStr = matchPreview ? ' - ' + matchPreview : '';
      
      console.log(`${status} ${chalk.cyan(agent.name)} ${chalk.dim(`(${agent.role})`)}${badgesStr}${matchStr} ${scoreIndicator}`);
    }
    
    console.log('');
  } catch (error) {
    console.error(chalk.red('Error searching agents:'), error);
    process.exit(1);
  }
}

function getStatusIcon(status?: string): string {
  switch (status) {
    case 'available':
      return chalk.green('●');
    case 'busy':
      return chalk.yellow('●');
    case 'in-meeting':
      return chalk.blue('●');
    case 'offline':
      return chalk.gray('●');
    default:
      return chalk.gray('○');
  }
}

/**
 * Chat context manager - handles message annotations, summaries, and context curation
 */

import fs from 'fs/promises';
import path from 'path';
import matter from 'gray-matter';
import {
  ChatMessage,
  AnnotatedChatMessage,
  MessageAnnotation,
  ChatSummary,
  ArtifactReference,
  MessageStats,
} from '../types/index.js';

export class ChatContextManager {
  private workspaceRoot: string;

  constructor(workspaceRoot: string) {
    this.workspaceRoot = workspaceRoot;
  }

  /**
   * Get chat file path for an agent
   */
  private getChatFilePath(agentId: string): string {
    return path.join(
      this.workspaceRoot,
      '.ai-team',
      'private',
      'chats',
      `${agentId}.jsonl`
    );
  }

  /**
   * Get summaries directory path
   */
  private getSummariesDir(): string {
    return path.join(this.workspaceRoot, '.ai-team', 'artifacts', 'summaries');
  }

  /**
   * Archive a message (mark as not sent to LLM)
   */
  async archiveMessage(agentId: string, messageIndex: number): Promise<void> {
    await this.updateMessageField(agentId, messageIndex, 'archived', true);
  }

  /**
   * Unarchive a message
   */
  async unarchiveMessage(agentId: string, messageIndex: number): Promise<void> {
    await this.updateMessageField(agentId, messageIndex, 'archived', false);
  }

  /**
   * Update a specific field in a message
   */
  private async updateMessageField(
    agentId: string,
    messageIndex: number,
    field: string,
    value: any
  ): Promise<void> {
    const messages = await this.loadAllMessages(agentId);

    if (messageIndex < 0 || messageIndex >= messages.length) {
      throw new Error(`Message index ${messageIndex} out of bounds`);
    }

    messages[messageIndex] = {
      ...messages[messageIndex],
      [field]: value,
    };

    await this.saveMessages(agentId, messages);
  }

  /**
   * Load all messages (including archived) for an agent
   */
  async loadAllMessages(agentId: string): Promise<ChatMessage[]> {
    const filePath = this.getChatFilePath(agentId);

    try {
      const content = await fs.readFile(filePath, 'utf-8');
      const lines = content.trim().split('\n').filter((line) => line);
      return lines.map((line) => JSON.parse(line));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
        return [];
      }
      throw error;
    }
  }

  /**
   * Load active (non-archived) messages for an agent
   */
  async loadActiveMessages(agentId: string): Promise<ChatMessage[]> {
    const allMessages = await this.loadAllMessages(agentId);
    return allMessages.filter((msg) => !msg.archived);
  }

  /**
   * Save messages to JSONL file
   */
  private async saveMessages(agentId: string, messages: ChatMessage[]): Promise<void> {
    const filePath = this.getChatFilePath(agentId);
    await fs.mkdir(path.dirname(filePath), { recursive: true });

    const content = messages.map((msg) => JSON.stringify(msg)).join('\n') + '\n';
    await fs.writeFile(filePath, content, 'utf-8');
  }

  /**
   * Edit a message's content
   */
  async editMessage(agentId: string, messageIndex: number, newContent: string): Promise<void> {
    await this.updateMessageField(agentId, messageIndex, 'content', newContent);
  }

  /**
   * Delete a message
   */
  async deleteMessage(agentId: string, messageIndex: number): Promise<void> {
    const messages = await this.loadAllMessages(agentId);

    if (messageIndex < 0 || messageIndex >= messages.length) {
      throw new Error(`Message index ${messageIndex} out of bounds`);
    }

    messages.splice(messageIndex, 1);
    await this.saveMessages(agentId, messages);
  }

  /**
   * Add annotation to a message
   */
  async addAnnotation(
    agentId: string,
    messageIndex: number,
    annotation: MessageAnnotation
  ): Promise<void> {
    const messages = await this.loadAllMessages(agentId);

    if (messageIndex < 0 || messageIndex >= messages.length) {
      throw new Error(`Message index ${messageIndex} out of bounds`);
    }

    const message = messages[messageIndex] as AnnotatedChatMessage;
    message.annotations = message.annotations || [];
    message.annotations.push(annotation);

    await this.saveMessages(agentId, messages);
  }

  /**
   * Create a summary from selected messages
   */
  async createSummary(
    agentId: string,
    messageIndices: number[],
    title: string,
    tags?: string[]
  ): Promise<ChatSummary> {
    const messages = await this.loadAllMessages(agentId);
    const selectedMessages = messageIndices
      .filter((idx) => idx >= 0 && idx < messages.length)
      .map((idx) => messages[idx]);

    if (selectedMessages.length === 0) {
      throw new Error('No valid messages selected for summary');
    }

    // Generate summary content from selected messages
    const content = this.generateSummaryContent(selectedMessages);

    const summary: ChatSummary = {
      id: `summary-${Date.now()}`,
      title,
      content,
      sourceMessages: {
        agentId,
        messageIndices,
      },
      timestamp: new Date().toISOString(),
      tags,
    };

    // Save summary as markdown with frontmatter
    await this.saveSummary(summary);

    return summary;
  }

  /**
   * Generate summary content from messages
   */
  private generateSummaryContent(messages: ChatMessage[]): string {
    return messages
      .map((msg, idx) => {
        const speaker = msg.from === 'human' ? 'User' : msg.from;
        return `**${speaker}:** ${msg.content}`;
      })
      .join('\n\n');
  }

  /**
   * Save summary as markdown with frontmatter
   */
  private async saveSummary(summary: ChatSummary): Promise<void> {
    const summariesDir = this.getSummariesDir();
    await fs.mkdir(summariesDir, { recursive: true });

    const fileName = `${summary.id}.md`;
    const filePath = path.join(summariesDir, fileName);

    const frontmatter = {
      id: summary.id,
      title: summary.title,
      timestamp: summary.timestamp,
      sourceMessages: summary.sourceMessages,
      tags: summary.tags || [],
    };

    const fileContent = matter.stringify(summary.content, frontmatter);
    await fs.writeFile(filePath, fileContent, 'utf-8');
  }

  /**
   * Load all summaries
   */
  async loadSummaries(): Promise<ChatSummary[]> {
    const summariesDir = this.getSummariesDir();

    try {
      const files = await fs.readdir(summariesDir);
      const summaries: ChatSummary[] = [];

      for (const file of files) {
        if (file.endsWith('.md')) {
          const filePath = path.join(summariesDir, file);
          const content = await fs.readFile(filePath, 'utf-8');
          const parsed = matter(content);

          summaries.push({
            id: parsed.data.id,
            title: parsed.data.title,
            content: parsed.content,
            sourceMessages: parsed.data.sourceMessages,
            timestamp: parsed.data.timestamp,
            tags: parsed.data.tags,
          });
        }
      }

      return summaries;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
        return [];
      }
      throw error;
    }
  }

  /**
   * Get message statistics
   */
  async getMessageStats(agentId: string): Promise<MessageStats> {
    const messages = await this.loadAllMessages(agentId);
    const archived = messages.filter((msg) => msg.archived).length;

    return {
      total: messages.length,
      archived,
      active: messages.length - archived,
      byAgent: {
        [agentId]: messages.length,
      },
    };
  }

  /**
   * List available artifacts (summaries, documents, etc.)
   */
  async listArtifacts(): Promise<ArtifactReference[]> {
    const summaries = await this.loadSummaries();

    return summaries.map((summary) => ({
      type: 'summary' as const,
      path: path.join(this.getSummariesDir(), `${summary.id}.md`),
      title: summary.title,
      tags: summary.tags,
    }));
  }
}

import { parse } from '@typescript-eslint/typescript-estree';
import { AST_NODE_TYPES, TSESTree } from '@typescript-eslint/typescript-estree';
import { readFile } from 'fs/promises';

/**
 * Complexity metrics for a function or method
 */
export interface ComplexityMetrics {
  cyclomaticComplexity: number;
  linesOfCode: number;
  parameters: number;
  returnStatements: number;
  nestedDepth: number;
}

/**
 * Information about a TypeScript function
 */
export interface FunctionInfo {
  name: string;
  startLine: number;
  endLine: number;
  isAsync: boolean;
  isExported: boolean;
  parameters: string[];
  returnType?: string;
  complexity: ComplexityMetrics;
}

/**
 * Information about a TypeScript class
 */
export interface ClassInfo {
  name: string;
  startLine: number;
  endLine: number;
  isExported: boolean;
  isAbstract: boolean;
  extends?: string;
  implements: string[];
  methods: FunctionInfo[];
  properties: string[];
}

/**
 * Import information
 */
export interface ImportInfo {
  source: string;
  imports: string[];
  isTypeOnly: boolean;
  line: number;
}

/**
 * TypeScript-specific analyzer using @typescript-eslint/typescript-estree
 * Provides richer analysis than generic tree-sitter for TS code
 */
export class TypeScriptAnalyzer {
  /**
   * Parse a TypeScript file and return the AST
   */
  async parseFile(filePath: string): Promise<TSESTree.Program> {
    const sourceCode = await readFile(filePath, 'utf-8');

    return parse(sourceCode, {
      loc: true,
      range: true,
      comment: true,
      filePath,
    });
  }

  /**
   * Get all functions in a file
   */
  async getFunctions(filePath: string): Promise<FunctionInfo[]> {
    const ast = await this.parseFile(filePath);
    const functions: FunctionInfo[] = [];

    this.visitNode(ast, (node) => {
      if (
        node.type === AST_NODE_TYPES.FunctionDeclaration ||
        node.type === AST_NODE_TYPES.ArrowFunctionExpression ||
        node.type === AST_NODE_TYPES.FunctionExpression
      ) {
        const funcInfo = this.extractFunctionInfo(node);
        if (funcInfo) {
          functions.push(funcInfo);
        }
      }
    });

    return functions;
  }

  /**
   * Get all classes in a file
   */
  async getClasses(filePath: string): Promise<ClassInfo[]> {
    const ast = await this.parseFile(filePath);
    const classes: ClassInfo[] = [];

    this.visitNode(ast, (node) => {
      if (node.type === AST_NODE_TYPES.ClassDeclaration) {
        const classInfo = this.extractClassInfo(node);
        if (classInfo) {
          classes.push(classInfo);
        }
      }
    });

    return classes;
  }

  /**
   * Get all imports in a file
   */
  async getImports(filePath: string): Promise<ImportInfo[]> {
    const ast = await this.parseFile(filePath);
    const imports: ImportInfo[] = [];

    this.visitNode(ast, (node) => {
      if (node.type === AST_NODE_TYPES.ImportDeclaration) {
        imports.push(this.extractImportInfo(node));
      }
    });

    return imports;
  }

  /**
   * Calculate complexity metrics for a function
   */
  calculateComplexity(filePath: string, functionName: string): Promise<ComplexityMetrics | null> {
    return this.getFunctions(filePath).then((functions) => {
      const func = functions.find((f) => f.name === functionName);
      return func ? func.complexity : null;
    });
  }

  /**
   * Find unused imports in a file
   */
  async findUnusedImports(filePath: string): Promise<ImportInfo[]> {
    await this.parseFile(filePath);
    const sourceCode = await readFile(filePath, 'utf-8');

    const imports = await this.getImports(filePath);
    const unusedImports: ImportInfo[] = [];

    for (const importInfo of imports) {
      const hasUnusedIdentifiers = importInfo.imports.some((importedName) => {
        // Simple check: see if the imported name appears anywhere in the code
        // (excluding the import statement itself)
        const regex = new RegExp(`\\b${importedName}\\b`, 'g');
        const matches = sourceCode.match(regex) || [];
        // If it appears only once (the import itself), it's unused
        return matches.length <= 1;
      });

      if (hasUnusedIdentifiers) {
        unusedImports.push(importInfo);
      }
    }

    return unusedImports;
  }

  /**
   * Extract function information from an AST node
   */
  private extractFunctionInfo(
    node:
      | TSESTree.FunctionDeclaration
      | TSESTree.ArrowFunctionExpression
      | TSESTree.FunctionExpression
      | TSESTree.TSEmptyBodyFunctionExpression
  ): FunctionInfo | null {
    // Get function name
    let name = 'anonymous';
    if (node.type === AST_NODE_TYPES.FunctionDeclaration && node.id) {
      name = node.id.name;
    }

    // Get location
    const startLine = node.loc?.start.line || 0;
    const endLine = node.loc?.end.line || 0;

    // Get parameters
    const parameters = node.params.map((param) => {
      if (param.type === AST_NODE_TYPES.Identifier) {
        return param.name;
      }
      return 'complex_param';
    });

    // Calculate complexity
    const complexity = this.calculateNodeComplexity(node);

    return {
      name,
      startLine,
      endLine,
      isAsync: node.async || false,
      isExported: false, // Would need parent context to determine
      parameters,
      complexity,
    };
  }

  /**
   * Extract class information from an AST node
   */
  private extractClassInfo(node: TSESTree.ClassDeclaration): ClassInfo | null {
    if (!node.id) {
      return null;
    }

    const methods: FunctionInfo[] = [];
    const properties: string[] = [];

    for (const member of node.body.body) {
      if (member.type === AST_NODE_TYPES.MethodDefinition) {
        if (member.key.type === AST_NODE_TYPES.Identifier && member.value) {
          const funcInfo = this.extractFunctionInfo(member.value);
          if (funcInfo) {
            funcInfo.name = member.key.name;
            methods.push(funcInfo);
          }
        }
      } else if (member.type === AST_NODE_TYPES.PropertyDefinition) {
        if (member.key.type === AST_NODE_TYPES.Identifier) {
          properties.push(member.key.name);
        }
      }
    }

    return {
      name: node.id.name,
      startLine: node.loc?.start.line || 0,
      endLine: node.loc?.end.line || 0,
      isExported: false, // Would need parent context
      isAbstract: node.abstract || false,
      extends: node.superClass?.type === AST_NODE_TYPES.Identifier ? node.superClass.name : undefined,
      implements: [],
      methods,
      properties,
    };
  }

  /**
   * Extract import information from an AST node
   */
  private extractImportInfo(node: TSESTree.ImportDeclaration): ImportInfo {
    const imports: string[] = [];

    for (const specifier of node.specifiers) {
      if (specifier.type === AST_NODE_TYPES.ImportSpecifier) {
        const imported = specifier.imported;
        imports.push(imported.type === AST_NODE_TYPES.Identifier ? imported.name : imported.value);
      } else if (specifier.type === AST_NODE_TYPES.ImportDefaultSpecifier) {
        imports.push(specifier.local.name);
      } else if (specifier.type === AST_NODE_TYPES.ImportNamespaceSpecifier) {
        imports.push(specifier.local.name);
      }
    }

    return {
      source: node.source.value,
      imports,
      isTypeOnly: node.importKind === 'type',
      line: node.loc?.start.line || 0,
    };
  }

  /**
   * Calculate cyclomatic complexity and other metrics for a node
   */
  private calculateNodeComplexity(node: TSESTree.Node): ComplexityMetrics {
    let complexity = 1; // Base complexity
    let returnStatements = 0;
    let nestedDepth = 0;

    this.visitNode(node, (n, depth = 0) => {
      if (depth > nestedDepth) {
        nestedDepth = depth;
      }

      // Increment complexity for decision points
      if (
        n.type === AST_NODE_TYPES.IfStatement ||
        n.type === AST_NODE_TYPES.ConditionalExpression ||
        n.type === AST_NODE_TYPES.ForStatement ||
        n.type === AST_NODE_TYPES.ForInStatement ||
        n.type === AST_NODE_TYPES.ForOfStatement ||
        n.type === AST_NODE_TYPES.WhileStatement ||
        n.type === AST_NODE_TYPES.DoWhileStatement ||
        n.type === AST_NODE_TYPES.CatchClause
      ) {
        complexity++;
      }

      // Count logical operators (&&, ||)
      if (n.type === AST_NODE_TYPES.LogicalExpression) {
        complexity++;
      }

      // Count case clauses in switch statements
      if (n.type === AST_NODE_TYPES.SwitchCase && n.test !== null) {
        complexity++;
      }

      // Count return statements
      if (n.type === AST_NODE_TYPES.ReturnStatement) {
        returnStatements++;
      }
    });

    const linesOfCode = node.loc ? node.loc.end.line - node.loc.start.line + 1 : 0;

    return {
      cyclomaticComplexity: complexity,
      linesOfCode,
      parameters:
        'params' in node && Array.isArray(node.params) ? (node.params as any[]).length : 0,
      returnStatements,
      nestedDepth,
    };
  }

  /**
   * Visit all nodes in the AST
   */
  private visitNode(node: TSESTree.Node, callback: (node: TSESTree.Node, depth?: number) => void, depth = 0): void {
    callback(node, depth);

    // Recursively visit children
    for (const key in node) {
      const value = (node as any)[key];

      if (value && typeof value === 'object') {
        if (Array.isArray(value)) {
          for (const item of value) {
            if (item && typeof item === 'object' && item.type) {
              this.visitNode(item, callback, depth + 1);
            }
          }
        } else if (value.type) {
          this.visitNode(value, callback, depth + 1);
        }
      }
    }
  }
}

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { CodeEditManager } from './code-edit-manager.js';
