  let testFile: string;

  beforeEach(async () => {
    manager = new CodeEditManager();
    testDir = join(tmpdir(), `edit-manager-test-${Date.now()}`);
    await mkdir(testDir, { recursive: true });
    testFile = join(testDir, 'test.ts');
