import { createTwoFilesPatch } from 'diff';
import parseDiff from 'parse-diff';

/**
 * A single hunk in a diff (continuous block of changes)
 */
export interface DiffHunk {
  oldStart: number;
  oldLines: number;
  newStart: number;
  newLines: number;
  lines: string[];
}

/**
 * Structured diff information
 */
export interface StructuredDiff {
  filePath: string;
  hunks: DiffHunk[];
  additions: number;
  deletions: number;
  /** The raw unified diff string */
  unifiedDiff: string;
}

/**
 * Options for diff generation
 */
export interface DiffOptions {
  /** Number of context lines around changes */
  context?: number;
  /** Old file label */
  oldLabel?: string;
  /** New file label */
  newLabel?: string;
}

/**
 * Builds unified diffs between old and new versions of code
 */
export class DiffBuilder {
  /**
   * Create a unified diff between two versions of a file
   */
  createDiff(
    filePath: string,
    oldContent: string,
    newContent: string,
    options: DiffOptions = {}
  ): StructuredDiff {
    const { context = 3, oldLabel, newLabel } = options;

    const oldFileName = oldLabel || `${filePath} (before)`;
    const newFileName = newLabel || `${filePath} (after)`;

    // Generate unified diff
    const unifiedDiff = createTwoFilesPatch(
      oldFileName,
      newFileName,
      oldContent,
      newContent,
      undefined,
      undefined,
      { context }
    );

    // Parse the diff to get structured information
    const parsedDiffs = parseDiff(unifiedDiff);
    const parsedFile = parsedDiffs[0];

    if (!parsedFile) {
      // No changes
      return {
        filePath,
        hunks: [],
        additions: 0,
        deletions: 0,
        unifiedDiff: '',
      };
    }

    // Convert parsed hunks to our format
    const hunks: DiffHunk[] = parsedFile.chunks.map((chunk: any) => ({
      oldStart: chunk.oldStart,
      oldLines: chunk.oldLines,
      newStart: chunk.newStart,
      newLines: chunk.newLines,
      lines: chunk.changes.map((change: any) => {
        if (change.type === 'add') {
          return `+${change.content}`;
        } else if (change.type === 'del') {
          return `-${change.content}`;
        } else {
          return ` ${change.content}`;
        }
      }),
    }));

    return {
      filePath,
      hunks,
      additions: parsedFile.additions || 0,
      deletions: parsedFile.deletions || 0,
      unifiedDiff,
    };
  }

  /**
   * Create diffs for multiple files
   */
  createMultiFileDiff(
    files: Array<{ filePath: string; oldContent: string; newContent: string }>,
    options: DiffOptions = {}
  ): StructuredDiff[] {
    return files.map((file) =>
      this.createDiff(file.filePath, file.oldContent, file.newContent, options)
    );
  }

  /**
   * Apply a diff to content (patch)
   */
  applyDiff(originalContent: string, unifiedDiff: string): string | null {
    try {
      // Parse the diff
      const parsedDiffs = parseDiff(unifiedDiff);
      if (parsedDiffs.length === 0) {
        return originalContent;
      }

      const parsedFile = parsedDiffs[0];
      const lines = originalContent.split('\n');
      let offset = 0;

      for (const chunk of parsedFile.chunks) {
        const startLine = chunk.oldStart - 1 + offset;
        const deleteCount = chunk.oldLines;
        const additions: string[] = [];

        for (const change of chunk.changes) {
          if (change.type === 'add') {
            additions.push(change.content);
          } else if (change.type === 'del') {
            // Will be removed
          } else {
            // Normal line (context)
            additions.push(change.content);
          }
        }

        // Remove old lines and insert new ones
        lines.splice(startLine, deleteCount, ...additions);
        offset += additions.length - deleteCount;
      }

      return lines.join('\n');
    } catch (error) {
      console.error('Failed to apply diff:', error);
      return null;
    }
  }

  /**
   * Format a diff for terminal display with ANSI colors
   */
  formatForTerminal(diff: StructuredDiff): string {
    const RESET = '\x1b[0m';
    const RED = '\x1b[31m';
    const GREEN = '\x1b[32m';
    const CYAN = '\x1b[36m';
    const BOLD = '\x1b[1m';

    let output = `${BOLD}${CYAN}diff --git a/${diff.filePath} b/${diff.filePath}${RESET}\n`;
    output += `${BOLD}--- a/${diff.filePath}${RESET}\n`;
    output += `${BOLD}+++ b/${diff.filePath}${RESET}\n`;

    for (const hunk of diff.hunks) {
      output += `${CYAN}@@ -${hunk.oldStart},${hunk.oldLines} +${hunk.newStart},${hunk.newLines} @@${RESET}\n`;

      for (const line of hunk.lines) {
        if (line.startsWith('+')) {
          output += `${GREEN}${line}${RESET}\n`;
        } else if (line.startsWith('-')) {
          output += `${RED}${line}${RESET}\n`;
        } else {
          output += `${line}\n`;
        }
      }
    }

    output += `\n${BOLD}Summary: ${GREEN}+${diff.additions}${RESET} ${BOLD}additions, ${RED}-${diff.deletions}${RESET} ${BOLD}deletions${RESET}\n`;

    return output;
  }

  /**
   * Get a summary of changes
   */
  getSummary(diffs: StructuredDiff[]): {
    filesChanged: number;
    totalAdditions: number;
    totalDeletions: number;
    files: string[];
  } {
    return {
      filesChanged: diffs.length,
      totalAdditions: diffs.reduce((sum, d) => sum + d.additions, 0),
      totalDeletions: diffs.reduce((sum, d) => sum + d.deletions, 0),
      files: diffs.map((d) => d.filePath),
    };
  }

  /**
   * Check if a diff has any changes
   */
  hasChanges(diff: StructuredDiff): boolean {
    return diff.hunks.length > 0;
  }

  /**
   * Filter out diffs with no changes
   */
  filterEmptyDiffs(diffs: StructuredDiff[]): StructuredDiff[] {
    return diffs.filter((d) => this.hasChanges(d));
  }
}

import path from 'path';
import { describe, expect, it } from 'vitest';
import { ContextManager } from './index.js';
import { ContextLevel, PermissionError } from '../types/index.js';

describe('ContextManager', () => {
  const workspaceRoot = path.resolve('/workspace');
  const contextManager = new ContextManager(workspaceRoot);

  it('matches read and write permissions using workspace-relative paths', () => {
    const agent = {
      id: 'maya',
      permissions: {
        read: ['src/**/*', 'docs/**/*'],
        write: ['src/feature-a/**/*'],
      },
    } as any;

    const readablePath = path.join(workspaceRoot, 'src', 'feature-a', 'service.ts');
    const writablePath = path.join(workspaceRoot, 'src', 'feature-a', 'handler.ts');
    const blockedPath = path.join(workspaceRoot, 'tests', 'service.test.ts');

    expect(contextManager.canRead(agent, readablePath)).toBe(true);
    expect(contextManager.canWrite(agent, writablePath)).toBe(true);
    expect(contextManager.canRead(agent, blockedPath)).toBe(false);
    expect(contextManager.canWrite(agent, blockedPath)).toBe(false);
  });

  it('throws PermissionError when read/write assertions fail', () => {
    const agent = {
      id: 'jordan',
      permissions: {
        read: ['docs/**/*'],
        write: ['docs/**/*'],
      },
    } as any;

    const sourceFile = path.join(workspaceRoot, 'src', 'index.ts');

    expect(() => contextManager.assertCanRead(agent, sourceFile)).toThrow(PermissionError);
    expect(() => contextManager.assertCanWrite(agent, sourceFile)).toThrow(PermissionError);
  });

  it('generates organization-level defaults with strategic access and agent management', () => {
    const permissions = contextManager.generateDefaultPermissions(ContextLevel.ORGANIZATION);

    expect(permissions.read).toEqual(['README.md', 'docs/**/*', '.ai-team/**/*']);
    expect(permissions.write).toEqual(['.ai-team/meetings/**/*', '**/agent.md', '**/*.agent.md']);
    expect(permissions.manage_agents).toBe(true);
  });
});

/**
 * LLM client - unified interface for GitHub Copilot and OpenAI-compatible providers
 *
 * GitHub Copilot path:
 *   - Gets a GitHub token via `gh auth token` (needs `copilot` scope)
 *   - Calls Copilot API (https://api.individual.githubcopilot.com)
 *   - Supports all Copilot models: Claude, GPT, Gemini, Grok, etc.
 *
 * OpenAI-compatible path:
 *   - Uses the configured baseUrl and API key
 *
 * Usage:
 *   const llm = new LlmService(workspaceRoot);
 *   await llm.initialize();
 *   const reply = await llm.chat(agent, [{ role: 'user', content: 'Hello' }]);
 */

import { execSync } from 'child_process';
import { randomUUID } from 'crypto';
import fs from 'fs/promises';
import OpenAI from 'openai';
import type { ChatCompletionChunk, ChatCompletionMessageParam } from 'openai/resources/chat/completions.js';
import path from 'path';
import type { LlmConfig, Agent, Skill, ChatMessage, TeamConfig, LlmGenerationParams } from '../types/index.js';
import { loadTeamConfig, loadEnvFile } from '../storage/index.js';

export type { ChatCompletionMessageParam };

const GITHUB_COPILOT_API_URL = 'https://api.individual.githubcopilot.com';
const GITHUB_COPILOT_MODELS_URL = 'https://api.individual.githubcopilot.com/models';
const DEFAULT_COPILOT_MODEL = 'gpt-4o';
const GITHUB_TOKEN_TIMEOUT_MS = 15_000;
const MODEL_FETCH_TIMEOUT_MS = 15_000;
const TEST_CONNECTION_TIMEOUT_MS = 20_000;
const CHAT_REQUEST_TIMEOUT_MS = 30_000;
const STREAM_CHUNK_TIMEOUT_MS = 30_000;

// ============================================================================
// LlmService — high-level abstraction for any configured provider
// ============================================================================

export interface LlmChatOptions {
  /** Override the model for this call */
  model?: string;
  /** Max tokens in the response */
  maxTokens?: number;
  /** Temperature (0-2) */
  temperature?: number;
  /** Top-p nucleus sampling (0-1) */
  topP?: number;
  /** Presence penalty (-2 to 2) */
  presencePenalty?: number;
  /** Frequency penalty (-2 to 2) */
  frequencyPenalty?: number;
  /** Stop sequences */
  stop?: string[];
  /** Whether to stream the response */
  stream?: boolean;
}

export interface LlmToolDefinition {
  name: string;
  description: string;
  parameters?: Record<string, unknown>;
}

export interface LlmToolCall {
  toolCallId: string;
  toolName: string;
  args: unknown;
}

export interface LlmToolResult {
  toolCallId: string;
  toolName: string;
  result: unknown;
  isError?: boolean;
}

export interface LlmToolChatResult {
  text: string;
  toolResults: LlmToolResult[];
}

/**
 * High-level LLM service that reads workspace config and exposes a
 * provider-agnostic chat interface.
 *
 * ```ts
 * const llm = new LlmService(workspaceRoot);
 * await llm.initialize();
 * const reply = await llm.chat(agent, [{ role: 'user', content: 'hi' }]);
 * ```
 */
export class LlmService {
  private workspaceRoot: string;
  private client!: OpenAI;
  private config!: LlmConfig;
  private providerRef?: string;
  private model!: string;
  private initialized = false;
  private logDir: string;
  private logDirReady = false;

  constructor(workspaceRoot: string) {
    this.workspaceRoot = workspaceRoot;
    this.logDir = path.join(this.workspaceRoot, '.ai-team', 'logs', 'llm');
  }

  /**
   * Load workspace config + env and create the OpenAI client.
   * Must be called once before `chat()` / `streamChat()`.
   * @throws If no LLM config is found
   */
  async initialize(): Promise<void> {
    await this.initializeForChat();
  }

  async initializeForChat(
    agent?: Pick<Agent, 'llm'>,
    skill?: Pick<Skill, 'llm'>,
    runtimeOverrides?: LlmChatOptions,
  ): Promise<LlmChatOptions> {
    const teamConfig = await loadTeamConfig(this.workspaceRoot);
    if (!teamConfig) {
      throw new Error(
        'No LLM configuration found. Run "ait init" to configure a provider.'
      );
    }

    const resolved = resolveEffectiveLlmSettings(teamConfig, agent, skill, runtimeOverrides);
    this.config = resolved.config;
    this.providerRef = resolved.providerRef;
    this.model = getDefaultModel(this.config);

    const env = await loadEnvFile(this.workspaceRoot);
    const apiKeyName = resolved.apiKeyEnvVar || 'AI_TEAM_LLM_API_KEY';
    const apiKey = env[apiKeyName] || env['AI_TEAM_LLM_API_KEY'] || env['LLM_API_KEY'] || env['OPENAI_API_KEY'];

    this.client = createLlmClient(this.config, apiKey);
    this.initialized = true;

    return resolved.options;
  }

  /** The resolved model name (e.g. "claude-sonnet-4.6") */
  get modelName(): string {
    this.assertReady();
    return this.model;
  }

  /** The provider name (e.g. "github-copilot") */
  get provider(): string {
    this.assertReady();
    return this.config.provider;
  }

  /** Provider registry key, if resolved from TeamConfig providers dictionary */
  get providerName(): string | undefined {
    this.assertReady();
    return this.providerRef;
  }

  /** The underlying OpenAI client, for advanced use */
  get openai(): OpenAI {
    this.assertReady();
    return this.client;
  }

  // --------------------------------------------------------------------------
  // Chat
  // --------------------------------------------------------------------------

  /**
   * Send a chat completion request and return the full response text.
   *
   * @param agent - The agent whose persona is used as system prompt
   * @param messages - Conversation messages (user / assistant turns)
   * @param options - Optional overrides (model, maxTokens, temperature)
   * @param skill - Optional skill with role instructions
   * @param teamRoster - Optional list of all agents (injected into system prompt)
   * @returns The assistant's reply text
   */
  async chat(
    agent: Agent,
    messages: ChatCompletionMessageParam[],
    options?: LlmChatOptions,
    skill?: Skill,
    teamRoster?: Agent[],
  ): Promise<string> {
    this.assertReady();

    const systemPrompt = buildSystemPrompt(agent, skill, teamRoster);
    const allMessages: ChatCompletionMessageParam[] = [
      { role: 'system', content: systemPrompt },
      ...messages,
    ];
    const start = Date.now();
    const logBase = this.buildLogBase('chat', agent, allMessages, options, skill, teamRoster);

    try {
      const response = await withTimeout(
        createChatCompletion(this.client, this.config, {
          model: options?.model ?? this.model,
          messages: allMessages,
          max_tokens: options?.maxTokens,
          temperature: options?.temperature,
          top_p: options?.topP,
          presence_penalty: options?.presencePenalty,
          frequency_penalty: options?.frequencyPenalty,
          stop: options?.stop,
        }),
        CHAT_REQUEST_TIMEOUT_MS,
        `LLM request timed out after ${CHAT_REQUEST_TIMEOUT_MS / 1000}s.`,
      );

      const text = extractChatCompletionText(response);
      if (!text) {
        throw new Error('LLM returned an empty response');
      }

      await this.writeLlmLog({
        ...logBase,
        durationMs: Date.now() - start,
        response: {
          text,
          raw: safeJsonClone(response),
        },
      });

      return text;
    } catch (error) {
      await this.writeLlmLog({
        ...logBase,
        durationMs: Date.now() - start,
        error: serializeError(error),
      });
      throw error;
    }
  }

  /**
   * Send a streaming chat completion request.
   *
   * @param agent - The agent whose persona is used as system prompt
   * @param messages - Conversation messages
   * @param options - Optional overrides
   * @param skill - Optional skill with role instructions
   * @param teamRoster - Optional list of all agents (injected into system prompt)
   * @returns An async iterable of content chunks
   */
  async streamChat(
    agent: Agent,
    messages: ChatCompletionMessageParam[],
    options?: LlmChatOptions,
    skill?: Skill,
    teamRoster?: Agent[],
  ) {
    this.assertReady();

    const systemPrompt = buildSystemPrompt(agent, skill, teamRoster);
    const allMessages: ChatCompletionMessageParam[] = [
      { role: 'system', content: systemPrompt },
      ...messages,
    ];
    const start = Date.now();
    const logBase = this.buildLogBase('stream', agent, allMessages, options, skill, teamRoster);

    try {
      const stream = await withTimeout(
        createChatCompletion(this.client, this.config, {
          model: options?.model ?? this.model,
          messages: allMessages,
          max_tokens: options?.maxTokens,
          temperature: options?.temperature,
          top_p: options?.topP,
          presence_penalty: options?.presencePenalty,
          frequency_penalty: options?.frequencyPenalty,
          stop: options?.stop,
          stream: true,
        }),
        CHAT_REQUEST_TIMEOUT_MS,
        `LLM stream setup timed out after ${CHAT_REQUEST_TIMEOUT_MS / 1000}s.`,
      ) as AsyncIterable<ChatCompletionChunk>;

      return this.wrapStreamWithLogging(stream, logBase, start, STREAM_CHUNK_TIMEOUT_MS);
    } catch (error) {
      await this.writeLlmLog({
        ...logBase,
        durationMs: Date.now() - start,
        error: serializeError(error),
      });
      throw error;
    }
  }

  async chatWithTools(
    agent: Agent,
    messages: ChatCompletionMessageParam[],
    tools: LlmToolDefinition[],
    executeTool: (toolCall: LlmToolCall) => Promise<LlmToolResult>,
    options?: LlmChatOptions,
    skill?: Skill,
    teamRoster?: Agent[],
    maxToolRounds: number = 8,
    onToken?: (token: string) => void,
  ): Promise<LlmToolChatResult> {
    this.assertReady();

    const systemPrompt = buildSystemPrompt(agent, skill, teamRoster);
    const allMessages: ChatCompletionMessageParam[] = [
      { role: 'system', content: systemPrompt },
      ...messages,
    ];

    const logBase = this.buildLogBase('chat', agent, allMessages, options, skill, teamRoster);
    const start = Date.now();
    const collectedResults: LlmToolResult[] = [];

    try {
      for (let round = 0; round < maxToolRounds; round++) {
        const stream = await withTimeout(
          createChatCompletion(this.client, this.config, {
            model: options?.model ?? this.model,
            messages: allMessages,
            max_tokens: options?.maxTokens,
            temperature: options?.temperature,
            top_p: options?.topP,
            presence_penalty: options?.presencePenalty,
            frequency_penalty: options?.frequencyPenalty,
            stop: options?.stop,
            tools: tools.map(tool => ({
              type: 'function' as const,
              function: {
                name: tool.name,
                description: tool.description,
                parameters: tool.parameters ?? {
                  type: 'object',
                  additionalProperties: true,
                },
              },
            })),
            stream: true,
          }),
          CHAT_REQUEST_TIMEOUT_MS,
          `LLM request timed out after ${CHAT_REQUEST_TIMEOUT_MS / 1000}s.`,
        ) as AsyncIterable<ChatCompletionChunk>;

        const toolCallMap = new Map<number, { id?: string; name: string; args: string }>();
        let assistantText = '';

        const iterator = stream[Symbol.asyncIterator]();
        while (true) {
          const nextChunk = await withTimeout(
            iterator.next(),
            STREAM_CHUNK_TIMEOUT_MS,
            `LLM tool stream timed out after ${STREAM_CHUNK_TIMEOUT_MS / 1000}s without receiving output.`,
          );

          if (nextChunk.done) {
            break;
          }

          const chunk = nextChunk.value;
          const delta = chunk.choices?.[0]?.delta;
          const deltaText = extractDeltaText(delta?.content) || extractDeltaText((delta as { reasoning_content?: unknown } | undefined)?.reasoning_content);
          if (deltaText) {
            assistantText += deltaText;
            onToken?.(deltaText);
          }

          const deltaToolCalls = (delta as { tool_calls?: Array<{
            index?: number;
            id?: string;
            function?: { name?: string; arguments?: string };
          }> } | undefined)?.tool_calls;

          if (!deltaToolCalls || deltaToolCalls.length === 0) {
            continue;
          }

          for (const toolCallDelta of deltaToolCalls) {
            const index = toolCallDelta.index ?? 0;
            const current = toolCallMap.get(index) || { name: '', args: '' };
            if (toolCallDelta.id) {
              current.id = toolCallDelta.id;
            }
            if (toolCallDelta.function?.name) {
              current.name += toolCallDelta.function.name;
            }
            if (toolCallDelta.function?.arguments) {
              current.args += toolCallDelta.function.arguments;
            }
            toolCallMap.set(index, current);
          }
        }

        const toolCalls = [...toolCallMap.entries()]
          .sort((a, b) => a[0] - b[0])
          .map(([, value]) => ({
            id: value.id || randomUUID(),
            type: 'function' as const,
            function: {
              name: value.name,
              arguments: value.args || '{}',
            },
          }))
          .filter(toolCall => toolCall.function.name.trim().length > 0);

        if (toolCalls.length === 0) {
          const text = assistantText.trim();
          if (!text) {
            throw new Error('LLM returned an empty response');
          }

          await this.writeLlmLog({
            ...logBase,
            durationMs: Date.now() - start,
            response: {
              text,
              raw: {
                toolResults: safeJsonClone(collectedResults),
              },
            },
          });

          return {
            text,
            toolResults: collectedResults,
          };
        }

        allMessages.push({
          role: 'assistant',
          content: assistantText.length > 0 ? assistantText : null,
          tool_calls: toolCalls,
        } as ChatCompletionMessageParam);

        for (const toolCall of toolCalls) {
          if (toolCall.type !== 'function') {
            continue;
          }

          const toolName = toolCall.function.name;
          const rawArgs = toolCall.function.arguments ?? '{}';
          let args: unknown = {};

          try {
            args = rawArgs.trim().length > 0 ? JSON.parse(rawArgs) : {};
          } catch {
            args = {};
          }

          const toolResult = await executeTool({
            toolCallId: toolCall.id,
            toolName,
            args,
          });

          collectedResults.push(toolResult);

          const payload = toolResult.isError
            ? { error: toolResult.result }
            : { result: toolResult.result };

          allMessages.push({
            role: 'tool',
            tool_call_id: toolCall.id,
            content: JSON.stringify(payload),
          } as ChatCompletionMessageParam);
        }
      }

      throw new Error(`Tool loop exceeded maximum rounds (${maxToolRounds})`);
    } catch (error) {
      await this.writeLlmLog({
        ...logBase,
        durationMs: Date.now() - start,
        response: {
          raw: {
            toolResults: safeJsonClone(collectedResults),
          },
        },
        error: serializeError(error),
      });
      throw error;
    }
  }

  // --------------------------------------------------------------------------
  // Helpers
  // --------------------------------------------------------------------------

  /**
   * Convert stored ChatMessage history into OpenAI message format.
   *
   * @param history - Chat messages from JSONL history
   * @param agentId - The agent ID (messages from this agent become "assistant")
   * @returns OpenAI-compatible message array
   */
  static historyToMessages(
    history: ChatMessage[],
    agentId: string,
  ): ChatCompletionMessageParam[] {
    return history.map((msg) => ({
      role: msg.from === 'human' ? 'user' as const : 'assistant' as const,
      content: msg.content,
    }));
  }

  /**
   * Low-level chat completion without an agent persona.
   * Useful during onboarding / init when no agents exist yet.
   *
   * @param systemPrompt - Custom system prompt
   * @param messages - Conversation messages
   * @param options - Optional overrides
   * @returns The assistant's reply text
   */
  async rawChat(
    systemPrompt: string,
    messages: ChatCompletionMessageParam[],
    options?: LlmChatOptions,
  ): Promise<string> {
    this.assertReady();

    const allMessages: ChatCompletionMessageParam[] = [
      { role: 'system', content: systemPrompt },
      ...messages,
    ];

    const start = Date.now();
    const logBase = this.buildRawLogBase('raw-chat', allMessages, options);

    try {
      const response = await withTimeout(
        createChatCompletion(this.client, this.config, {
          model: options?.model ?? this.model,
          messages: allMessages,
          max_tokens: options?.maxTokens,
          temperature: options?.temperature,
          top_p: options?.topP,
          presence_penalty: options?.presencePenalty,
          frequency_penalty: options?.frequencyPenalty,
          stop: options?.stop,
        }),
        CHAT_REQUEST_TIMEOUT_MS,
        `LLM request timed out after ${CHAT_REQUEST_TIMEOUT_MS / 1000}s.`,
      );

      const text = extractChatCompletionText(response);
      if (!text) {
        throw new Error('LLM returned an empty response');
      }

      await this.writeLlmLog({
        ...logBase,
        durationMs: Date.now() - start,
        response: {
          text,
          raw: safeJsonClone(response),
        },
      });

      return text;
    } catch (error) {
      await this.writeLlmLog({
        ...logBase,
        durationMs: Date.now() - start,
        error: serializeError(error),
      });
      throw error;
    }
  }

  /**
   * Low-level streaming chat completion without an agent persona.
   */
  async rawStreamChat(
    systemPrompt: string,
    messages: ChatCompletionMessageParam[],
    options?: LlmChatOptions,
  ) {
    this.assertReady();

    const allMessages: ChatCompletionMessageParam[] = [
      { role: 'system', content: systemPrompt },
      ...messages,
    ];

    const start = Date.now();
    const logBase = this.buildRawLogBase('raw-stream', allMessages, options);

    try {
      const stream = await withTimeout(
        createChatCompletion(this.client, this.config, {
          model: options?.model ?? this.model,
          messages: allMessages,
          max_tokens: options?.maxTokens,
          temperature: options?.temperature,
          top_p: options?.topP,
          presence_penalty: options?.presencePenalty,
          frequency_penalty: options?.frequencyPenalty,
          stop: options?.stop,
          stream: true,
        }),
        CHAT_REQUEST_TIMEOUT_MS,
        `LLM stream setup timed out after ${CHAT_REQUEST_TIMEOUT_MS / 1000}s.`,
      ) as AsyncIterable<ChatCompletionChunk>;

      return this.wrapStreamWithLogging(stream, logBase, start, STREAM_CHUNK_TIMEOUT_MS);
    } catch (error) {
