function makeAgent(id: string, name: string, role: string): Agent {
  return {
    id,
    name,
    role,
    filePath: `/agents/${id}.md`,
    skillPath: `/skills/${role}.md`,
    createdAt: new Date().toISOString(),
    agentIds: [id],
    agentId: id,
  } as unknown as Agent;
}

function makeAgentManager(agents: Agent[]): AgentManager {
  return {
    getAllAgents: () => agents,
    resolveAgent: (query: string) => {
      const q = query.toLowerCase().trim();
      return agents.filter(
        a => a.name.toLowerCase() === q || a.id.toLowerCase() === q || a.name.toLowerCase().startsWith(q),
      );
    },
    getAgent: (id: string) => agents.find(a => a.id === id),
  } as unknown as AgentManager;
}

const SARAH = makeAgent('sarah-morgan', 'Sarah Morgan', 'frontend-developer');
const MICHAEL = makeAgent('michael-brown', 'Michael Brown', 'backend-developer');

describe('detectForwardRequestWithFallback', () => {
  const currentAgentId = MICHAEL.id;

  it('phase 1 — resolves an explicit agent name directly', async () => {
    const agentManager = makeAgentManager([SARAH, MICHAEL]);
    const llm = { chat: vi.fn() } as any;

    const result = await detectForwardRequestWithFallback(
      'forward me to Sarah',
      agentManager, currentAgentId, llm, MICHAEL,
    );

    expect(result.resolved).toBe(SARAH);
    expect(result.looksLikeForward).toBe(true);
    expect(llm.chat).not.toHaveBeenCalled();
  });

  it('phase 2 — resolves when the extracted string has trailing filler words', async () => {
    const agentManager = makeAgentManager([SARAH, MICHAEL]);
    const llm = { chat: vi.fn() } as any;

    // extractForwardTargetName returns "sarah i want to discuss this"
    // Phase 1: resolveAgent("sarah i want to discuss this") → []
    // Phase 2: slices until "sarah" → match
    const result = await detectForwardRequestWithFallback(
      'forward me to sarah i want to discuss this',
      agentManager, currentAgentId, llm, MICHAEL,
    );

    expect(result.resolved).toBe(SARAH);
    expect(result.looksLikeForward).toBe(true);
    expect(llm.chat).not.toHaveBeenCalled();
  });

  it('phase 3 pronoun — uses recent history to identify the referent', async () => {
    const agentManager = makeAgentManager([SARAH, MICHAEL]);
    const llm = { chat: vi.fn().mockResolvedValue('Sarah Morgan') } as any;

    const history = [
      { from: MICHAEL.id, to: currentAgentId, isHuman: false, content: 'You should talk to Sarah about the UI.', timestamp: '' },
      { from: currentAgentId, to: MICHAEL.id, isHuman: true, content: 'OK, sounds good.', timestamp: '' },
    ] as any[];

    const result = await detectForwardRequestWithFallback(
      'please forward me to him',
      agentManager, currentAgentId, llm, MICHAEL,
      history,
    );

    expect(result.resolved).toBe(SARAH);
    expect(result.looksLikeForward).toBe(true);
    // LLM must have been called with the history snippet injected
    const promptArg: string = llm.chat.mock.calls[0][1][0].content;
    expect(promptArg).toContain('Recent conversation');
    expect(promptArg).toContain('Sarah Morgan');
  });

  it('phase 3 pronoun — returns looksLikeForward=true but no resolution when LLM says none', async () => {
    const agentManager = makeAgentManager([SARAH, MICHAEL]);
    const llm = { chat: vi.fn().mockResolvedValue('none') } as any;

    const result = await detectForwardRequestWithFallback(
      'forward me to her',
      agentManager, currentAgentId, llm, MICHAEL,
      [],
    );

    expect(result.resolved).toBeUndefined();
    expect(result.looksLikeForward).toBe(true);
  });

  it('non-forward message — returns looksLikeForward=false', async () => {
    const agentManager = makeAgentManager([SARAH, MICHAEL]);
    const llm = { chat: vi.fn() } as any;

    const result = await detectForwardRequestWithFallback(
      'how is the project going?',
      agentManager, currentAgentId, llm, MICHAEL,
    );

    expect(result.resolved).toBeUndefined();
    expect(result.looksLikeForward).toBe(false);
    expect(llm.chat).not.toHaveBeenCalled();
  });

  it('does not resolve the current agent as a forward target', async () => {
    const agentManager = makeAgentManager([SARAH, MICHAEL]);
    const llm = { chat: vi.fn().mockResolvedValue('Michael Brown') } as any;

    // Even if "forward me to michael" is said while already talking to michael,
    // it should not cycle back to the same agent.
    const result = await detectForwardRequestWithFallback(
      'forward me to Michael',
      agentManager, currentAgentId, llm, MICHAEL,
    );

    // Michael is filtered out; no other match from phase 1
    // Phase 2 also filtered → phase 3 LLM returns Michael again → still filtered → undefined
    expect(result.resolved).toBeUndefined();
  });

  // -- new intent patterns ---------------------------------------------------

  const directBriefCases: Array<[string, string]> = [
    ['brief Sarah about this',            'brief <name> about'],
    ['can you brief Sarah about this?',   'can you brief <name> about'],
    ['please brief Sarah on the project', 'please brief <name> on'],
    ['brief Sarah',                       'brief <name> (no trailing context)'],
  ];

  for (const [input, label] of directBriefCases) {
    it(`detects forward from "${label}"`, async () => {
      const agentManager = makeAgentManager([SARAH, MICHAEL]);
      const llm = { chat: vi.fn() } as any;

      const result = await detectForwardRequestWithFallback(
        input, agentManager, currentAgentId, llm, MICHAEL,
      );

      expect(result.resolved).toBe(SARAH);
      expect(result.looksLikeForward).toBe(true);
      expect(llm.chat).not.toHaveBeenCalled();
    });
  }

  it('detects forward from "tell Sarah about the bug"', async () => {
    const agentManager = makeAgentManager([SARAH, MICHAEL]);
    const llm = { chat: vi.fn() } as any;
    const result = await detectForwardRequestWithFallback(
      'tell Sarah about the bug', agentManager, currentAgentId, llm, MICHAEL,
    );
    expect(result.resolved).toBe(SARAH);
    expect(result.looksLikeForward).toBe(true);
  });

  it('detects forward from "let Sarah know about the deadline"', async () => {
    const agentManager = makeAgentManager([SARAH, MICHAEL]);
    const llm = { chat: vi.fn() } as any;
    const result = await detectForwardRequestWithFallback(
      'let Sarah know about the deadline', agentManager, currentAgentId, llm, MICHAEL,
    );
    expect(result.resolved).toBe(SARAH);
    expect(result.looksLikeForward).toBe(true);
  });

  it('detects forward from "loop in Sarah"', async () => {
    const agentManager = makeAgentManager([SARAH, MICHAEL]);
    const llm = { chat: vi.fn() } as any;
    const result = await detectForwardRequestWithFallback(
      'loop in Sarah', agentManager, currentAgentId, llm, MICHAEL,
    );
    expect(result.resolved).toBe(SARAH);
    expect(result.looksLikeForward).toBe(true);
  });

  it('detects forward from "ping Sarah about the release"', async () => {
    const agentManager = makeAgentManager([SARAH, MICHAEL]);
    const llm = { chat: vi.fn() } as any;
    const result = await detectForwardRequestWithFallback(
      'ping Sarah about the release', agentManager, currentAgentId, llm, MICHAEL,
    );
    expect(result.resolved).toBe(SARAH);
    expect(result.looksLikeForward).toBe(true);
  });
});

/**
 * Chat command — entry point for `ait chat`.
 *
 * This file is intentionally thin. Each cross-cutting service concern lives
 * in its own module inside this folder:
 *
 *   hooks.ts            — ChatRuntimeHooks interface (the caller's contract)
 *   async-utils.ts      — withTimeout / withAbortSignal / isAbortError
 *   emit.ts             — emitRuntimeEvent / writeInfo / writeWarn / writeError
 *   questions.ts        — requestInput / requestConfirm / requestSelect / …
 *   forward-detection.ts — natural-language agent-switch detection
 *   agent-selection.ts  — selectDefaultTopAgent / formatUserPrompt
 */

import ora from 'ora';
import {
  AgentManager,
  ChatMessage,
  Agent,
  LlmService,
  loadSkill,
  loadTeamConfig,
} from '@ai-team/core';
import type { ChatOptions } from '../../contracts.js';
import { getGitUserName, developerNameToId } from '../../utils/git.js';
import { ensureUserEnvVars as ensureServiceUserEnvVars } from '../../utils/user-env.js';
import { SessionManager } from '../../session-manager.js';
import { createSqliteStorage } from '../../storage/index.js';
import { ChatOrchestrator } from '../../orchestrator/chat-orchestrator.js';
import { tryIntroduceUser as tryIntroduceUserNew } from '../../orchestrator/introduction.js';
import { createContainer, resolvePlugins, TOKENS } from '../../container/index.js';
import type { OrchestratorContext } from '../../orchestrator/pipeline-context.js';

// ── Service modules ───────────────────────────────────────────────────────────
export type { ChatRuntimeHooks } from './hooks.js';
export {
  emitRuntimeEvent,
  formatConsoleArgs,
  writeInfo,
  writeWarn,
  writeError,
  printSessionResume,
} from './emit.js';
export { withTimeout, withAbortSignal, isAbortError, throwIfAborted } from './async-utils.js';
export { requestInput, requestConfirm, requestSelect, requestPassword, requestChecklist } from './questions.js';
export { selectDefaultTopAgent, formatUserPrompt, resolveDeveloperName } from './agent-selection.js';
export { detectForwardRequestWithFallback, REFERENCE_PRONOUNS } from './forward-detection.js';

// ── Internal service imports (used by chatCommand but not re-exported) ────────
import type { ChatRuntimeHooks } from './hooks.js';
import { emitRuntimeEvent, formatConsoleArgs, writeInfo, writeWarn, writeError, printSessionResume } from './emit.js';
import { withTimeout, withAbortSignal, isAbortError, throwIfAborted } from '../../orchestrator/async-utils.js';
import { requestInput, requestSelect } from './questions.js';
import { selectDefaultTopAgent, formatUserPrompt, resolveDeveloperName } from '../../utils/agent-selection.js';

// ─────────────────────────────────────────────────────────────────────────────

const CHAT_CONNECT_TIMEOUT_MS = 20_000;
const PREFLIGHT_STEP_TIMEOUT_MS = 15_000;

/** Strip the HANDOFF: directive line from agent text before persisting. */
export function stripHandoffDirective(text: string): string {
  let cleaned = text.replaceAll(/^\s*HANDOFF:\s*[^\n]+$/gim, '');
  cleaned = cleaned.replaceAll(/\n{3,}/g, '\n\n').trim();
  return cleaned;
}

export const CHAT_COMMAND_META = {
  description: 'Start a chat session with an agent (defaults to top-level manager if omitted)',
  llmCallable: false,
};

// ── Preflight helper (only used by chatCommand) ───────────────────────────────

async function runPreflightStep<T>(
  hooks: ChatRuntimeHooks | undefined,
  message: string,
  task: () => Promise<T>,
  timeoutMs: number = PREFLIGHT_STEP_TIMEOUT_MS,
): Promise<T> {
  writeInfo(hooks, message);
  return withAbortSignal(
    withTimeout(task(), timeoutMs, `${message} timed out after ${Math.floor(timeoutMs / 1000)}s.`),
    hooks?.signal,
    `${message} aborted by user.`,
  );
}

// ─────────────────────────────────────────────────────────────────────────────

export async function chatCommand(
  workspaceRoot: string,
  agentId: string | undefined,
  options: ChatOptions,
  hooks: ChatRuntimeHooks = {},
) {
  const originalLog = console.log;
  const originalWarn = console.warn;
  const originalError = console.error;

  // Note: process.stdout.write is already patched by the invoke() wrapper in
  // AiTeamService when context.emit is present. Do NOT add a second patch here
  // — that would cause every token and log line to be emitted (and printed)
  // twice in the CLI. console.log/warn/error are safe to override because they
  // go through emitRuntimeEvent → hooks.emit into the same queue, but stdout
  // must only be patched once at the invoke level.
  if (hooks.emit) {
    console.log = (...args: unknown[]) =>
      emitRuntimeEvent(hooks, { kind: 'log', level: 'info', message: formatConsoleArgs(args) });
    console.warn = (...args: unknown[]) =>
      emitRuntimeEvent(hooks, { kind: 'log', level: 'warn', message: formatConsoleArgs(args) });
    console.error = (...args: unknown[]) =>
      emitRuntimeEvent(hooks, { kind: 'log', level: 'error', message: formatConsoleArgs(args) });
  }

  let sessionManager!: SessionManager;
  let currentSessionId!: string;

  try {
    const agentManager = new AgentManager(workspaceRoot);
    // Navigation stack for /back — each entry is the session we came FROM
    const navStack: Array<{ agentId: string; sessionId: string; agentName: string }> = [];

    sessionManager = new SessionManager(workspaceRoot, createSqliteStorage(workspaceRoot), agentManager);
    await sessionManager.initialize();

    const loadHistory = async (currentAgentId: string): Promise<ChatMessage[]> => {
      if (options.sessionId) {
        currentSessionId = options.sessionId;
        return sessionManager.getSessionMessages(options.sessionId);
      }
      if (options.createNewSession) {
        const developerId = developerNameToId(developerName || 'developer');
        const newSession = await sessionManager.createSession(currentAgentId, developerId);
        currentSessionId = newSession.id;
        return [];
      }
      const latestSession = await sessionManager.getLatestSession(currentAgentId);
      if (latestSession) {
        currentSessionId = latestSession.id;
        return sessionManager.getSessionMessages(latestSession.id);
      }
      const developerId = developerNameToId(developerName || 'developer');
      const newSession = await sessionManager.createSession(currentAgentId, developerId);
      currentSessionId = newSession.id;
      return [];
    };

    const teamConfig = await runPreflightStep(
      hooks,
      'Loading team configuration...',
      () => loadTeamConfig(workspaceRoot),
    );
    const registry = teamConfig?.providers || teamConfig?.llmProviders;
    const defaultProviderRef = registry
      ? (Object.entries(registry).find(([, cfg]) => cfg.isDefault)?.[0]
        || teamConfig?.defaultLlmProvider
        || Object.keys(registry)[0])
      : undefined;
    const defaultProviderKind = defaultProviderRef ? registry?.[defaultProviderRef]?.kind : undefined;
    const requiresApiKey = defaultProviderKind
      ? defaultProviderKind === 'openai-compatible'
      : teamConfig?.llm?.provider === 'openai-compatible';
    const env = await runPreflightStep(
      hooks,
      'Validating user environment...',
      () => ensureServiceUserEnvVars(
        workspaceRoot,
        { developerName: true, apiKey: requiresApiKey },
        { quiet: true },
      ),
    );
    const developerName = resolveDeveloperName(env) ?? getGitUserName();

    await runPreflightStep(hooks, 'Initializing agents...', () => agentManager.initialize());

    let resolvedAgent: Agent | undefined;

    if (!agentId || agentId.trim().length === 0) {
      const all = agentManager.getAllAgents();
      resolvedAgent = selectDefaultTopAgent(all);
      if (!resolvedAgent) {
        writeError(hooks, 'No agents found in this workspace.');
        writeInfo(hooks, 'Run ait init to initialize your team.');
        throw new Error('No agents found in this workspace. Run ait init to initialize your team.');
      }
      writeInfo(hooks, `No agent specified; defaulting to ${resolvedAgent.name} (${resolvedAgent.role}).`);
    } else {
      const matches = agentManager.resolveAgent(agentId);
      if (matches.length === 0) {
        writeError(hooks, `Agent not found: "${agentId}"`);
        const all = agentManager.getAllAgents();
        if (all.length > 0) {
          writeInfo(hooks, '');
          writeInfo(hooks, 'Available agents:');
          for (const a of all) writeInfo(hooks, `  - ${a.name} (${a.role}) [id: ${a.id}]`);
        }
        writeInfo(hooks, '');
        writeInfo(hooks, 'Run ait list to see all agents.');
        throw new Error(`Agent not found: "${agentId}"`);
      } else if (matches.length === 1) {
        resolvedAgent = matches[0];
      } else {
        const chosen = await requestSelect(hooks, {
          message: `Multiple agents match "${agentId}". Which one?`,
          choices: matches.map(a => ({ name: `${a.name} — ${a.role} [${a.id}]`, value: a.id })),
        });
        resolvedAgent = agentManager.getAgent(chosen);
      }
    }

    if (!resolvedAgent) {
      writeError(hooks, 'Could not resolve agent.');
      throw new Error('Could not resolve agent.');
    }

    let agent: Agent = resolvedAgent;

    // Initialize LLM service
    const llm = new LlmService(workspaceRoot);
    const useSpinner = !hooks?.emit && Boolean(process.stderr.isTTY);
    const spinner = useSpinner ? ora('Connecting to LLM...').start() : undefined;
    if (!spinner) writeInfo(hooks, 'Connecting to LLM...');

    try {
      await withAbortSignal(
        withTimeout(
          llm.initialize(),
          CHAT_CONNECT_TIMEOUT_MS,
          `LLM initialization timed out after ${CHAT_CONNECT_TIMEOUT_MS / 1000}s.`,
        ),
        hooks?.signal,
        'Chat connection aborted by user.',
      );
      if (spinner) {
        spinner.succeed(`Connected to ${llm.provider} using ${llm.modelName}`);
      } else {
        writeInfo(hooks, `Connected to ${llm.provider} using ${llm.modelName}`);
      }
    } catch (error) {
      if (spinner) spinner.fail('Could not connect to configured LLM');
      writeError(hooks, (error as Error).message);
      writeInfo(hooks, 'Run "ait test-connection" to debug, or "ait init" to configure provider.');
      throw new Error((error as Error).message);
    }

    // Load skill instructions for the agent's role
    let skill;
    try {
      skill = await loadSkill(agent.skillPath);
    } catch {
      // Skill file may not exist — that's fine, agent bio is still used
    }

    writeInfo(hooks, `\nChat with ${agent.name} (${agent.role})`);
    writeInfo(hooks, 'Type "exit" to end the conversation');
    writeInfo(hooks, 'Type "/help" to see available in-chat commands');
    writeInfo(hooks, 'Ask to be forwarded or type "/chat <name>" to switch agents');
    writeInfo(hooks, 'Use "#tool_name {json}" or "/tool tool_name {json}" for direct tool calls');

    // Load chat history
    let history = await loadHistory(agent.id);
    if (history.length > 0) {
      printSessionResume(history, agent.name, developerName, hooks);
    }

    // Agent introduces themselves on first contact
    if (history.length === 0 && !options.pendingIntroduction) {
      await tryIntroduceUserNew(llm, agentManager, agent, history, skill, developerName, sessionManager, currentSessionId, hooks);
    }

    // Persist a web-client-generated introduction (keeps history ordering correct)
    if (options.pendingIntroduction && history.length === 0) {
      const introMsg: ChatMessage = {
        timestamp: new Date().toISOString(),
        from: agent.id,
        content: options.pendingIntroduction,
        importance: 'low',
      };
      if (sessionManager && currentSessionId) {
        await sessionManager.appendMessage(currentSessionId, introMsg);
      }
      history.push(introMsg);
    }

    // ── Build OrchestratorContext + ChatOrchestrator ─────────────────────────
    const _container = createContainer({ workspaceRoot });
    const _ctx: OrchestratorContext = {
      agent,
      workspaceRoot,
      sessionId: currentSessionId,
      hooks,
      toolManager: _container.resolve(TOKENS.ToolManager),
      sessionManager,
      agentManager,
      skillManager: _container.resolve(TOKENS.SkillManager),
      llmService: llm,
      contextManager: _container.resolve(TOKENS.ContextManager),
      history,
    };
    const _plugins = resolvePlugins(_container);
    const _orchestrator = new ChatOrchestrator(_ctx, _plugins);

    // Single message mode
    if (options.message) {
      await withAbortSignal(
        _orchestrator.run({ message: options.message, contextFiles: options.context }),
        hooks.signal,
        'Chat request aborted by user.',
      );
      agent = _ctx.agent;
      currentSessionId = _ctx.sessionId;
      history = _ctx.history;
      if (options.oneShot) return;
    }

    // Interactive chat loop — delegates to ChatOrchestrator
    while (true) {
      throwIfAborted(hooks.signal, 'Chat request aborted by user.');

      const message = await withAbortSignal(
        requestInput(hooks, {
          message: formatUserPrompt(_ctx.agent, developerName),
          validate: (val: string) => val.length > 0 || 'Message cannot be empty',
        }),
        hooks.signal,
        'Chat input aborted by user.',
      );

      if (message.toLowerCase() === 'exit') {
        writeInfo(hooks, 'Goodbye!');
        break;
      }

      // /back — handled here so it has access to the local navStack
      if (message.trim() === '/back') {
        if (navStack.length === 0) {
          writeWarn(hooks, 'No previous agent to return to.');
          writeInfo(hooks, '');
        } else {
          const prev = navStack.pop()!;
          const prevAgent = agentManager.getAgent(prev.agentId);
          if (!prevAgent) {
            writeError(hooks, `Previous agent ${prev.agentId} no longer found.`);
          } else {
            const prevHistory = await sessionManager.getSessionMessages(prev.sessionId);
            (_ctx as any).agent     = prevAgent;
            (_ctx as any).sessionId = prev.sessionId;
            (_ctx as any).history   = prevHistory;
            agent = prevAgent;
            currentSessionId = prev.sessionId;
            history = prevHistory;
            writeInfo(hooks, `\n← Returned to ${prevAgent.name} (${prevAgent.role})\n`);
          }
        }
        continue;
      }

      // Regular turn — delegate to ChatOrchestrator
      const prevAgentId   = _ctx.agent.id;
      const prevSessionId = _ctx.sessionId;
      await withAbortSignal(
        _orchestrator.run({ message, contextFiles: options.context }),
        hooks.signal,
        'Chat request aborted by user.',
      );
      if (_ctx.agent.id !== prevAgentId) {
        navStack.push({ agentId: prevAgentId, sessionId: prevSessionId, agentName: prevAgentId });
        agent = _ctx.agent;
        currentSessionId = _ctx.sessionId;
        history = _ctx.history;
      }
    }
  } catch (error) {
    if (isAbortError(error)) {
      writeInfo(hooks, 'Chat aborted.');
      return;
    }
    writeError(hooks, `Error in chat: ${error instanceof Error ? error.message : String(error)}`);
    throw new Error(error instanceof Error ? error.message : String(error));
  } finally {
    if (sessionManager) {
      try { await sessionManager.close(); } catch {}
    }
    if (hooks.emit) {
      console.log = originalLog;
      console.warn = originalWarn;
      console.error = originalError;
    }
  }
}

import { getFileTree, loadTeamConfig, saveTeamConfig, AgentManager, type Agent, type FileTreeNode, type GetFileTreeOptions, type TeamConfig } from '@ai-team/core';

const DEFAULT_CONFIG: TeamConfig = { version: '1', randomAvatarUrls: [] };

/**
 * Return the workspace file tree, automatically reading allowPaths from
 * .ai-team/config.json and merging them with any caller-supplied allowPaths.
 */
export async function getFileTreeCommand(
  workspaceRoot: string,
  options: Omit<GetFileTreeOptions, 'allowPaths'> = {}
): Promise<FileTreeNode> {
  const config = await loadTeamConfig(workspaceRoot);
  const allowPaths = config?.fileTree?.allowPaths ?? [];
  return getFileTree(workspaceRoot, { ...options, allowPaths });
}

/**
 * Add a path to the global read or write permission list in .ai-team/config.json.
 * When mode is omitted it falls back to the legacy allowPaths list.
 * Returns the updated path list for that mode.
 */
export async function allowPathCommand(
  workspaceRoot: string,
  filePath: string,
  mode?: 'read' | 'write',
): Promise<string[]> {
  const config = await loadTeamConfig(workspaceRoot);
  const key = mode === 'write' ? 'writePaths' : mode === 'read' ? 'readPaths' : 'allowPaths';
  const current: string[] = (config?.fileTree as any)?.[key] ?? [];

  if (current.includes(filePath)) return current;

  const next = [...current, filePath];
  await saveTeamConfig(workspaceRoot, {
    ...DEFAULT_CONFIG,
    ...config,
    fileTree: { allowPaths: [], readPaths: [], writePaths: [], ...config?.fileTree, [key]: next },
  });
  return next;
}

/**
 * Remove a path from the global read or write permission list in .ai-team/config.json.
 * When mode is omitted it falls back to the legacy allowPaths list.
 * Returns the updated path list for that mode.
 */
export async function disallowPathCommand(
  workspaceRoot: string,
  filePath: string,
  mode?: 'read' | 'write',
): Promise<string[]> {
  const config = await loadTeamConfig(workspaceRoot);
  const key = mode === 'write' ? 'writePaths' : mode === 'read' ? 'readPaths' : 'allowPaths';
  const current: string[] = (config?.fileTree as any)?.[key] ?? [];
  const next = current.filter((p) => p !== filePath);

  if (next.length === current.length) return current;

  await saveTeamConfig(workspaceRoot, {
    ...DEFAULT_CONFIG,
    ...config,
    fileTree: { allowPaths: [], readPaths: [], writePaths: [], ...config?.fileTree, [key]: next },
  });
  return next;
}

// ============================================================================
// Per-agent path permissions (stored in .ai-team/agents/<id>.md frontmatter)
// ============================================================================

export interface AgentPathResult {
  agent: Agent;
  /** Updated permission list for the given mode after the operation */
  paths: string[];
}

async function resolveOneAgent(workspaceRoot: string, query: string): Promise<Agent> {
  const manager = new AgentManager(workspaceRoot);
  await manager.initialize();
  const matches = manager.resolveAgent(query);
  if (matches.length === 0) throw new Error(`Agent not found: "${query}"`);
  if (matches.length > 1) {
    throw new Error(`Ambiguous agent "${query}" — matched: ${matches.map((a) => a.id).join(', ')}`);
  }
  return matches[0];
}

/**
 * Add a path to an agent's read or write permission list in their .md frontmatter.
 * Persists via AgentManager.updateAgent which writes the YAML frontmatter back to the .md file.
 */
export async function agentAllowPathCommand(
  workspaceRoot: string,
  agentQuery: string,
  filePath: string,
  mode: 'read' | 'write' = 'read'
): Promise<AgentPathResult> {
  const agent = await resolveOneAgent(workspaceRoot, agentQuery);
  const manager = new AgentManager(workspaceRoot);
  await manager.initialize();

  const currentPerms = agent.permissions ?? { read: [], write: [] };
  const current: string[] = currentPerms[mode] ?? [];

  if (current.includes(filePath)) return { agent, paths: current };

  const next = [...current, filePath];
  const updated = await manager.updateAgent(agent.id, {
    permissions: { ...currentPerms, [mode]: next },
  });
  return { agent: updated, paths: next };
}

/**
 * Remove a path from an agent's read or write permission list in their .md frontmatter.
 * Persists via AgentManager.updateAgent which writes the YAML frontmatter back to the .md file.
 */
export async function agentDisallowPathCommand(
  workspaceRoot: string,
  agentQuery: string,
  filePath: string,
  mode: 'read' | 'write' = 'read'
): Promise<AgentPathResult> {
  const agent = await resolveOneAgent(workspaceRoot, agentQuery);
  const manager = new AgentManager(workspaceRoot);
  await manager.initialize();

  const currentPerms = agent.permissions ?? { read: [], write: [] };
  const current: string[] = currentPerms[mode] ?? [];
  const next = current.filter((p) => p !== filePath);

  if (next.length === current.length) return { agent, paths: current };

  const updated = await manager.updateAgent(agent.id, {
    permissions: { ...currentPerms, [mode]: next },
  });
  return { agent: updated, paths: next };
}

/**
 * ChatOrchestrator — the stateful session controller.
 *
 * One instance per active session. Accepts a single user message, runs
 * through the pipeline, handles handoff / hire / slash commands, and
 * returns when the turn is complete.
 *
 * The orchestrator itself knows nothing about:
 *   - HTTP, WebSockets, CLI readline — those are in the adapter layer.
 *   - Specific tool implementations — those are in core / service tools.
 *   - Storage format — delegated to SessionManager + ChatRuntimeHooks.
 *
 * To extend: register pipeline plugins via OrchestratorPlugins before calling run().
 */

import { emitStatus, emitLog, emitEvent } from './stream-events.js';
import { detectForwardRequestWithFallback } from './forward-detection.js';
import { sendTurn } from './send-turn.js';
import type { OrchestratorContext } from './pipeline-context.js';
import type { ResolvedPlugins } from './pipeline.js';

/** Options for a single run() call. */
export interface RunOptions {
  /** Raw user message (may start with a slash command). */
  message: string;
  /** Files the user has open / selected in the IDE. */
  contextFiles?: string[];
  /**
   * Maximum number of automatic handoff hops allowed before the loop stops
   * and returns control to the caller. Prevents infinite handoff chains.
   * Default: 10.
   */
  maxHops?: number;
}

export class ChatOrchestrator {
  constructor(
    private ctx: OrchestratorContext,
    private plugins: ResolvedPlugins,
  ) {}

  /**
   * Execute one user turn. Returns the final response text.
   *
   * The loop continues across handoffs (agent switches) until:
   *   - The responding agent does NOT request a handoff, OR
   *   - The maximum hop count is reached.
   */
  async run(options: RunOptions): Promise<string> {
    const { message, maxHops = 10 } = options;

    // ── Slash command intercept ─────────────────────────────────────────────
    const slashResult = await this.trySlashCommand(message);
    if (slashResult !== null) return slashResult;

    // ── Natural-language forward detection ──────────────────────────────────
    const nlResult = await this.tryNlForward(message);
    if (nlResult !== null) return nlResult;

    // ── Turn loop (handles handoff chains) ──────────────────────────────────
    let currentMessage = message;
    let hops = 0;
    let lastText = '';

    while (hops < maxHops) {
      const result = await sendTurn(currentMessage, this.plugins, this.ctx);
      lastText = result.text;

      // ── Hire: reload agents, notify surface, continue ─────────────────────
      if (result.hired) {
        await this.ctx.agentManager.loadAllAgents();
        emitLog(
          this.ctx.hooks,
          'info',
          `${this.ctx.agent.name} hired ${result.hired.name} (${result.hired.role}).`,
        );
        // Hiring is a side-effect — the turn is still considered complete.
        break;
      }

      // ── Handoff: switch agent, loop ────────────────────────────────────────
      if (result.handedOff && result.handoffTargetId) {
        const switched = await this.switchAgent(
          result.handoffTargetId,
          result.handoffTargetSessionId,
          result.handoffNote,
        );

        if (!switched) {
          emitLog(
            this.ctx.hooks,
            'warn',
            `Handoff requested to unknown agent "${result.handoffTargetId}" — staying with ${this.ctx.agent.name}.`,
          );
          break;
        }

        emitStatus(
          this.ctx.hooks,
          'handoff',
          `${this.ctx.agent.name} taking over.`,
        );

        // The briefing note from the handing-off agent becomes the next message.
        currentMessage = result.handoffNote ?? `Continued from ${this.ctx.agent.id}.`;
        hops++;
        continue;
      }

      break;
    }

    if (hops >= maxHops) {
      emitLog(this.ctx.hooks, 'warn', `Maximum handoff chain length (${maxHops}) reached.`);
    }

    return lastText;
  }

  // ── Natural-language forward detection ──────────────────────────────────────

  /**
   * Detect if the message is a natural-language request to be forwarded to
   * another agent. Returns an empty string if a forward was handled (or a
   * near-miss warning was emitted), null if the message is not a forward.
   */
  private async tryNlForward(message: string): Promise<string | null> {
    const { resolved, looksLikeForward } = await detectForwardRequestWithFallback(
      message,
      this.ctx.agentManager,
      this.ctx.agent.id,
      this.ctx.llmService,
      this.ctx.agent,
      this.ctx.history,
    );

    if (resolved) {
      const fromAgent = this.ctx.agent;
      await this.switchAgent(resolved.id);
      emitLog(this.ctx.hooks, 'info', `\nSwitching to ${resolved.name} (${resolved.role})...\n`);
      emitEvent(this.ctx.hooks, {
        kind: 'handoff',
        fromAgentId: fromAgent.id,
        fromAgentName: fromAgent.name,
        toAgentId: resolved.id,
        toAgentName: resolved.name,
        toSessionId: this.ctx.sessionId,
        message: `Forwarded from ${fromAgent.name} to ${resolved.name}`,
      });
      return '';
    }

    if (looksLikeForward) {
      emitLog(
        this.ctx.hooks,
        'warn',
        `I couldn't find anyone on your team matching that request. Use /chat <name> to switch directly, or hire them first.`,
      );
      return '';
    }

    return null;
  }

  // ── Slash command handling ──────────────────────────────────────────────────

  /**
   * Returns the response string if a slash command was matched, null otherwise.
   */
  private async trySlashCommand(message: string): Promise<string | null> {
    const trimmed = message.trim();
    if (!trimmed.startsWith('/')) return null;

    const [rawKey, ...rest] = trimmed.slice(1).split(/\s+/);
    const key = rawKey.toLowerCase();
    const rawArgs = rest.join(' ');

    const command = this.plugins.slashCommands.find(
      c => c.key === key || c.aliases?.includes(key),
    );

    if (!command) return null;

    await command.execute(rawArgs, this.ctx);
    return '';   // Slash commands handle their own output via hooks / stdout.
  }

  // ── Agent switching ─────────────────────────────────────────────────────────

  /**
   * Switch the current agent in `ctx`. Returns true if the target agent exists.
   * If `targetSessionId` is provided (pre-resolved by handoff_to_agent tool),
   * no extra session lookup is needed.
   */
  private async switchAgent(
    targetAgentId: string,
    targetSessionId?: string,
    handoffNote?: string,
  ): Promise<boolean> {
    const target = this.ctx.agentManager.getAgent(targetAgentId);
    if (!target) return false;

    // Derive the developer ID from the current session so we don't lose identity.
    const currentSession = await this.ctx.sessionManager.getSession(this.ctx.sessionId);
    const developerId = currentSession?.developerId ?? 'unknown';

    // Resolve (or create) the target session
    const targetSession = targetSessionId
      ? await this.ctx.sessionManager.getSession(targetSessionId)
      : await this.ctx.sessionManager.getOrCreateLatestSession(target.id, developerId);

    if (!targetSession) return false;
    const sessionId = targetSession.id;

    // Load history for the target's session
    const history = await this.ctx.sessionManager.getSessionMessages(sessionId);

    // Prepend briefing note as a synthetic human message so the target agent
    // sees context from the handing-off agent.
    if (handoffNote) {
      const briefing: import('@ai-team/core').ChatMessage = {
        from: this.ctx.agent.id,
        to: targetAgentId,
        content: `[Handoff briefing from ${this.ctx.agent.name}]: ${handoffNote}`,
        timestamp: new Date().toISOString(),
        isHuman: false,
      };
      history.push(briefing);
      await this.ctx.sessionManager.appendMessage(sessionId, briefing);
    }

    // Mutate context in place — all downstream pipeline stages see the new agent.
    (this.ctx as any).agent       = target;
    (this.ctx as any).sessionId   = sessionId;
    (this.ctx as any).history     = history;

    return true;
  }
}

/**
 * NoOpRagProvider — default IRagProvider.
 * Returns null (no retrieval). Swap with an embedding-based implementation
 * without touching the orchestrator.
 *
 * When implemented: MUST scope retrieval to contextManager.getReadablePaths(agent).
 * Returning content from files the agent cannot read is a permission violation.
 */

import type { IRagProvider } from '../pipeline.js';
import type { OrchestratorContext } from '../pipeline-context.js';

export class NoOpRagProvider implements IRagProvider {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  async retrieve(_query: string, _ctx: OrchestratorContext): Promise<null> {
    return null;
  }
}

/**
 * Default slash-command implementations registered via TOKENS.SlashCommands.
 * Each ISlashCommand has access to OrchestratorContext and can mutate ctx fields.
 *
 * /back is intentionally NOT here — it needs the navStack maintained in chat.ts.
 */

import { promisify } from 'util';
import { exec } from 'child_process';
import type { ISlashCommand } from './pipeline.js';
import type { OrchestratorContext } from './pipeline-context.js';
import { emitLog } from './stream-events.js';
import { requestConfirm } from './question-io.js';
import { developerNameToId } from '../utils/git.js';

const execAsync = promisify(exec);

// ── Helpers ───────────────────────────────────────────────────────────────────

function write(ctx: OrchestratorContext, msg: string): void {
  emitLog(ctx.hooks, 'info', msg);
}

// ── Command implementations ────────────────────────────────────────────────────

/**
 * Registry entry shape used by CLI, API client, and web surfaces.
 * Derived from ISlashCommand objects — descriptions stay next to implementations.
 */
export interface ChatCommandRegistryEntry {
  key: string;
  usage: string;
  description: string;
  llmCallable: boolean;
  aliases?: string[];
}

export function buildDefaultSlashCommands(): ISlashCommand[] {
  return [

    // ── Meta ───────────────────────────────────────────────────────────────────
    {
      key: 'help',
      description: 'Show this help',
      execute: async function(_args, ctx) {
        const cmds = buildDefaultSlashCommands();
        const lines = ['\nAvailable commands:\n'];
        for (const c of cmds) {
          const u = c.usage ?? `/${c.key}`;
          lines.push(`  ${u.padEnd(26)} ${c.description}`);
        }
        // Special entries handled outside the orchestrator
        lines.push(`  ${'#<tool> <json>'.padEnd(26)} Run a direct tool call`);
        lines.push(`  ${'exit'.padEnd(26)} End the session`);
        write(ctx, lines.join('\n'));
      },
    },

    {
      key: 'who',
      description: 'Show current agent name and session',
      llmCallable: false,
      execute: async (_args, ctx) => {
        write(ctx, `\nAgent   : ${ctx.agent.name} (${ctx.agent.role}) [${ctx.agent.id}]`);
        write(ctx, `Session : ${ctx.sessionId}\n`);
      },
    },

    {
      key: 'session',
      description: 'Show session ID',
      llmCallable: false,
      execute: async (_args, ctx) => write(ctx, ctx.sessionId),
    },

    // ── Session management ─────────────────────────────────────────────────────
    {
      key: 'new',
      description: 'Start a new session with the current agent',
      llmCallable: false,
      execute: async (_args, ctx) => {
        const developerId = developerNameToId('developer');
        const fresh = await ctx.sessionManager.createSession(ctx.agent.id, developerId);
        (ctx as any).sessionId = fresh.id;
        (ctx as any).history = [];
        write(ctx, `New session started: ${fresh.id}`);
      },
    },

    // ── Team ───────────────────────────────────────────────────────────────────
    {
      key: 'list',
      description: 'List all team members',
      llmCallable: true,
      execute: async (_args, ctx) => {
        const agents = ctx.agentManager.getAllAgents();
        if (agents.length === 0) { write(ctx, 'No agents found.'); return; }
        write(ctx, '\nTeam members:');
        for (const a of agents) {
          const marker = a.id === ctx.agent.id ? '  ← you are here' : '';
          write(ctx, `  ${a.name} (${a.role}) [${a.id}]${marker}`);
        }
        write(ctx, '');
      },
    },

    {
      key: 'chat',
      usage: '/chat <name|role>',
      description: 'Switch to another team member',
      llmCallable: false,
      execute: async (args, ctx) => {
        const query = args.trim();
        if (!query) { write(ctx, 'Usage: /chat <name|role>'); return; }

        const matches = ctx.agentManager.resolveAgent(query);
        if (matches.length === 0) { write(ctx, `No agent found matching: "${query}"`); return; }

        const target = matches.find(a => a.id !== ctx.agent.id) ?? matches[0];
        if (target.id === ctx.agent.id) { write(ctx, `Already talking to ${ctx.agent.name}.`); return; }

        const current = await ctx.sessionManager.getSession(ctx.sessionId);
        const devId   = (current as any)?.developerId ?? developerNameToId('developer');
        const ts      = await ctx.sessionManager.getOrCreateLatestSession(target.id, devId);
        const hist    = await ctx.sessionManager.getSessionMessages(ts.id);

        (ctx as any).agent     = target;
        (ctx as any).sessionId = ts.id;
        (ctx as any).history   = hist;
        write(ctx, `\nSwitched to ${target.name} (${target.role})\n`);
      },
    },

    // ── History ────────────────────────────────────────────────────────────────
    {
      key: 'history',
      usage: '/history [n]',
      description: 'Show recent messages (default: 20)',
      llmCallable: false,
      execute: async (args, ctx) => {
        const limit = parseInt(args.trim(), 10) || 20;
        const msgs  = ctx.history.slice(-limit);
        if (msgs.length === 0) { write(ctx, 'No messages in this session.'); return; }
        write(ctx, `\n─── Last ${msgs.length} messages ─────────────────────────────────`);
        for (const m of msgs) {
          const who = m.isHuman ? 'You' : ctx.agent.name;
          const ts  = m.timestamp ? new Date(m.timestamp).toLocaleTimeString() : '?';
          write(ctx, `[${ts}] ${who}: ${String(m.content).slice(0, 300)}`);
        }
        write(ctx, '──────────────────────────────────────────────────────────\n');
      },
    },

    // ── Agent info ─────────────────────────────────────────────────────────────
    {
      key: 'portfolio',
      aliases: ['bio'],
      description: "Show current agent's bio and tools",
      llmCallable: false,
      execute: async (_args, ctx) => {
        const a = ctx.agent;
        write(ctx, `\n${a.name} (${a.role}).`);
        if ((a as any).bio)   write(ctx, '\n' + (a as any).bio);
        if ((a as any).tools?.length) write(ctx, '\nTools: ' + (a as any).tools.join(', '));
        write(ctx, '');
      },
    },

    {
      key: 'info',
      usage: '/info <employee>',
      description: 'Show team member info',
      llmCallable: true,
      execute: async (args, ctx) => {
        const query = args.trim();
        if (!query) { write(ctx, 'Usage: /info <name|role>'); return; }
        const agents = ctx.agentManager.resolveAgent(query);
        if (agents.length === 0) { write(ctx, `No agent found matching: "${query}"`); return; }
        for (const a of agents) {
          write(ctx, `\n${a.name} (${a.role}) [${a.id}]`);
          if ((a as any).bio)   write(ctx, (a as any).bio);
          if ((a as any).tools?.length) write(ctx, 'Tools: ' + (a as any).tools.join(', '));
        }
        write(ctx, '');
      },
    },

    // ── Delegation commands (call the existing service commands) ───────────────
    {
      key: 'hire',
      description: 'Interactive: hire a new team member',
      llmCallable: true,
      execute: async (_args, ctx) => {
        const { hireCommand } = await import('../commands/hire.js');
        await hireCommand(ctx.workspaceRoot, {});
        await ctx.agentManager.loadAllAgents();
      },
    },

    {
      key: 'fire',
      usage: '/fire <employee>',
      description: 'Interactive: remove a team member',
      llmCallable: true,
      execute: async (args, ctx) => {
        if (!args.trim()) { write(ctx, 'Usage: /fire <name|id>'); return; }
        const { fireCommand } = await import('../commands/fire.js');
        await fireCommand(ctx.workspaceRoot, args.trim(), {});
        await ctx.agentManager.loadAllAgents();
      },
    },

    {
      key: 'create',
      usage: '/create [employee|skill]',
      description: 'Interactive: create an agent or skill',
      llmCallable: true,
      execute: async (args, ctx) => {
        const type = (args.trim() || 'agent').split(/\s+/)[0];
        const { createCommand } = await import('../commands/create.js');
        await createCommand(ctx.workspaceRoot, type, { interactive: true });
        await ctx.agentManager.loadAllAgents();
      },
    },

    {
      key: 'init',
      description: 'Interactive: (re-)initialize workspace',
      llmCallable: false,
      execute: async (_args, ctx) => {
        const { initCommand } = await import('../commands/init.js');
        await initCommand(ctx.workspaceRoot, {});
        await ctx.agentManager.loadAllAgents();
      },
    },

    {
      key: 'hh',
      usage: '/hh refresh',
      description: 'Refresh skill catalog from GitHub',
      llmCallable: true,
      execute: async (args, ctx) => {
        const sub = args.trim().toLowerCase();
        if (sub !== 'refresh') { write(ctx, 'Usage: /hh refresh'); return; }
        const { hhRefreshCommand } = await import('../commands/hh.js');
        await (hhRefreshCommand as (wr: string) => Promise<void>)(ctx.workspaceRoot);
      },
    },

    {
      key: 'test-connection',
      description: 'Test LLM provider connectivity',
      llmCallable: true,
      execute: async (_args, ctx) => {
        const { testConnectionCommand } = await import('../commands/test-connection.js');
        await testConnectionCommand(ctx.workspaceRoot, {});
      },
    },

    // ── Workspace ──────────────────────────────────────────────────────────────
    {
      key: 'overview',
      description: 'Workspace file overview → shared with agent',
      llmCallable: false,
      execute: async (_args, ctx) => {
        const { getWorkspaceOverview } = await import('../utils/workspace.js');
        const overview = await getWorkspaceOverview(ctx.workspaceRoot);
        write(ctx, '\n── Workspace Overview ──────────────────────────────────────\n');
        write(ctx, overview);
        const sysMsg = {
          timestamp: new Date().toISOString(),
          from: 'system' as const,
          content: `Tool Output (overview):\n${overview.slice(0, 4_000)}`,
        };
        await ctx.sessionManager.appendMessage(ctx.sessionId, sysMsg);
        ctx.history.push(sysMsg);
        write(ctx, `\n(Overview shared with ${ctx.agent.name}.)\n`);
      },
    },

    {
      key: 'graph',
      description: 'Team hierarchy diagram',
      llmCallable: true,
      execute: async (_args, ctx) => {
        try {
          const { getTeamGraphCommand } = await import('../commands/graph.js');
          const g = await (getTeamGraphCommand as (wr: string, type: string) => Promise<{ nodes: unknown[]; edges: unknown[] }>)
            (ctx.workspaceRoot, 'hierarchy');
          write(ctx, `\nTeam graph — ${g.nodes.length} nodes, ${g.edges.length} edges\n`);
        } catch (err) {
          write(ctx, `Failed to generate graph: ${err instanceof Error ? err.message : String(err)}`);
        }
      },
    },

    // ── Shell ──────────────────────────────────────────────────────────────────
    {
      key: 'run',
      usage: '/run <command>',
      aliases: ['shell'],
      description: 'Run a shell command → shared with agent',
      llmCallable: false,
      execute: async (args, ctx) => {
        if (!args.trim()) { write(ctx, 'Usage: /run <command>'); return; }

        const ok = await requestConfirm(ctx.hooks, {
          message: `Run: ${args.trim()}?`,
          default: false,
        });
        if (!ok) { write(ctx, 'Aborted.'); return; }

        write(ctx, `\n$ ${args.trim()}`);
        try {
          const { stdout, stderr } = await execAsync(args.trim(), {
            cwd: ctx.workspaceRoot,
            maxBuffer: 4 * 1024 * 1024,
          });
          const out = [stdout.trim(), stderr.trim()].filter(Boolean).join('\n\n') || '(no output)';
          write(ctx, out);

          const sysMsg = {
            timestamp: new Date().toISOString(),
            from: 'system' as const,
            content: `Tool Output (shell: ${args.trim()}):\n${out.slice(0, 4_000)}`,
          };
          await ctx.sessionManager.appendMessage(ctx.sessionId, sysMsg);
          ctx.history.push(sysMsg);
        } catch (err: any) {
          const out = [err.stdout?.trim(), err.stderr?.trim(), err.message].filter(Boolean).join('\n');
          write(ctx, `Command failed:\n${out}`);
        }
      },
    },
  ];
}

// ── Derived registry builders ─────────────────────────────────────────────────
// These let command-registry.ts (and downstream consumers) derive their
// flat registry lists from the single source of truth: the command objects above.

/**
 * Build the flat registry consumed by CLI, API client, and web.
 * Entries for /back and #tool (handled outside the orchestrator) are appended.
 */
export function buildChatCommandRegistry(): ChatCommandRegistryEntry[] {
  const cmds = buildDefaultSlashCommands();
  const entries: ChatCommandRegistryEntry[] = cmds.map(c => ({
    key: c.key,
    usage: c.usage ?? `/${c.key}`,
    description: c.description,
    llmCallable: c.llmCallable ?? false,
    aliases: c.aliases,
  }));
  // /back is handled by the CLI chat loop (needs navStack), not the orchestrator
  entries.push({ key: 'back', usage: '/back', description: 'Return to previous agent in handoff chain', llmCallable: false });
  // #tool is a pseudo-command (# prefix), documented here for completeness
  entries.push({ key: 'tool', usage: '#<tool> <json>', description: 'Run a direct tool call', llmCallable: false });
  return entries;
}

/**
 * Build the alias → canonical-key map from registered command objects.
 */
export function buildChatCommandAliases(): Record<string, string> {
  const result: Record<string, string> = {};
  for (const cmd of buildDefaultSlashCommands()) {
    if (cmd.aliases) {
      for (const alias of cmd.aliases) {
        result[alias] = cmd.key;
      }
    }
  }
  return result;
}

/**
 * tool-dispatch.ts — single execution gate for all LLM tool calls.
 *
 * Responsibilities:
 *   1. Route ask_human / ask_question to question-io (bypass ToolManager).
 *   2. Ask the human for confirmation on write/destructive tools.
 *   3. Execute via ToolManager (permission check + execute).
 *   4. Detect structured results (HandoffRequest, HireResult, …) and surface
 *      them in the return value so the chat loop can act on them.
 *   5. Handle apply_code_edit proposal persistence inline.
 *   6. Emit lifecycle runtime events throughout.
 */

import path from 'path';
import { promises as fs } from 'fs';
import {
  isHandoffRequest,
  isHireResult,
  isFindCapableAgentResult,
  isToolCatalogResult,
  type StructuredToolResult,
} from '@ai-team/core';
import { ProposalStore } from '../storage/proposal-store.js';
import type { OrchestratorContext } from './pipeline-context.js';
import { requestConfirm } from './question-io.js';
import { emitEvent, emitToolEvent } from './stream-events.js';

// ── Public types ──────────────────────────────────────────────────────────────

export interface ToolCallRequest {
  toolCallId: string;
  toolName: string;
  args: unknown;
}

export interface ToolCallResponse {
  toolCallId: string;
  toolName: string;
  /** Serialised string the LLM receives as the tool result. */
  result: unknown;
  isError: boolean;
  /** Set when the tool returned a typed orchestration result. */
  structured?: StructuredToolResult;
}

// ── Interactive question tool detection ───────────────────────────────────────

const QUESTION_TOOL_NAMES = new Set(['ask_human', 'ask_question']);

function isQuestionTool(toolName: string): boolean {
  return QUESTION_TOOL_NAMES.has(toolName);
}

// Tools whose results never need human approval (read-only / info-only).
const SILENT_TOOL_PREFIXES = ['find_', 'list_', 'read_', 'search_', 'get_'];
const SILENT_TOOL_NAMES = new Set([
  'handoff_to_agent',   // orchestration — already requires delegation permission
  'hire_agent',         // requires manage-agents permission (checked by ToolManager)
  'find_capable_agent',
  'list_tools',
  'ask_human',
  'ask_question',
]);

function requiresConfirmation(toolName: string): boolean {
  if (SILENT_TOOL_NAMES.has(toolName)) return false;
  if (SILENT_TOOL_PREFIXES.some(p => toolName.startsWith(p))) return false;
  return true;
}

// ── Main dispatch ─────────────────────────────────────────────────────────────

export async function dispatchToolCall(
  call: ToolCallRequest,
  ctx: OrchestratorContext,
  contextFiles?: string[],
): Promise<ToolCallResponse> {
  const { toolName, toolCallId, args } = call;
  const label = `${toolName}(${formatArgs(args)})`;

  emitEvent(ctx.hooks, { kind: 'tool', toolName, toolPhase: 'request', message: label });

  // ── 1. Interactive question tools ─────────────────────────────────────────

  if (isQuestionTool(toolName)) {
    emitToolEvent(ctx.hooks, toolName, 'start', 'Asking developer question');
    const execution = await executeQuestionTool(toolName, args, ctx);

    await appendToolHistory(ctx, toolName, serialise(execution.ok ? execution.result : execution.error));

    emitToolEvent(
      ctx.hooks,
      toolName,
      execution.ok ? 'result' : 'error',
      execution.ok ? 'Question answered' : (execution.error ?? 'Question tool failed'),
    );

    return {
      toolCallId,
      toolName,
      result: execution.ok ? execution.result : execution.error,
      isError: !execution.ok,
    };
  }

  // ── 2. Human confirmation for write/dangerous tools ───────────────────────

  let approved = true;
  if (requiresConfirmation(toolName)) {
    approved = await requestConfirm(ctx.hooks, {
      message: `Allow ${ctx.agent.name} to run ${label}?`,
      default: false,
    });

    if (!approved) {
      emitToolEvent(ctx.hooks, toolName, 'denied', 'Tool call denied by user');
      const denied = 'Tool call denied by user.';
      await appendToolHistory(ctx, toolName, denied);
      return { toolCallId, toolName, result: denied, isError: false };
    }
  }

  emitToolEvent(ctx.hooks, toolName, 'start', 'Executing');

  // ── 3. Execute via ToolManager ─────────────────────────────────────────────

  const execResult = await ctx.toolManager.execute(
    ctx.agent,
    toolName,
    args,
    { workspaceRoot: ctx.workspaceRoot, currentFiles: contextFiles },
  );

  const outputText = execResult.ok
    ? serialise(execResult.result)
    : (execResult.error ?? 'Tool execution failed');

  await appendToolHistory(ctx, toolName, outputText);

  emitToolEvent(
    ctx.hooks,
    toolName,
    execResult.ok ? 'result' : 'error',
    execResult.ok ? 'Completed' : outputText,
  );

  // ── 4. Detect structured results ──────────────────────────────────────────

  let structured: StructuredToolResult | undefined;
  if (execResult.ok) {
    const r = execResult.result;
    if (isHandoffRequest(r) || isHireResult(r) || isFindCapableAgentResult(r) || isToolCatalogResult(r)) {
      structured = r;
    }
  }

  // ── 5. apply_code_edit proposal persistence ───────────────────────────────

  if (execResult.ok && toolName === 'apply_code_edit') {
    await persistCodeEditProposal(execResult.result, args, ctx).catch(err =>
      console.error('[tool-dispatch] Failed to persist code edit proposal:', err),
    );
  }

  return {
    toolCallId,
    toolName,
    result: execResult.ok ? execResult.result : outputText,
    isError: !execResult.ok,
    structured,
  };
}

// ── History persistence ───────────────────────────────────────────────────────

async function appendToolHistory(
  ctx: OrchestratorContext,
  toolName: string,
  output: string,
): Promise<void> {
  await ctx.sessionManager.appendMessage(ctx.sessionId, {
    from: ctx.agent.id,
    content: `[tool:${toolName}] ${output}`,
    timestamp: new Date().toISOString(),
    isHuman: false,
  });
}

// ── apply_code_edit proposal ──────────────────────────────────────────────────

async function persistCodeEditProposal(
  result: unknown,
  args: unknown,
  ctx: OrchestratorContext,
): Promise<void> {
  const r = result as Record<string, unknown>;
  if (r?.status !== 'pending_approval') return;

  const proposalId = r.proposalId as string;
  const changes = ((args as any)?.changes ?? []) as Array<{
    filePath: string;
    oldContent: string;
    newContent: string;
  }>;

  const resolvedFiles: typeof changes = [];
  for (const change of changes) {
    const absPath = path.isAbsolute(change.filePath)
      ? change.filePath
      : path.join(ctx.workspaceRoot, change.filePath);
    await fs.mkdir(path.dirname(absPath), { recursive: true });
    await fs.writeFile(absPath, change.newContent, 'utf8');
    resolvedFiles.push({ filePath: absPath, oldContent: change.oldContent, newContent: change.newContent });
  }

  const store = new ProposalStore(ctx.workspaceRoot);
  store.save({
    proposalId,
    agentName: ctx.agent.name,
    description: (r.description as string) ?? '',
    createdAt: new Date().toISOString(),
    files: resolvedFiles,
  });

  emitEvent(ctx.hooks, {
    kind: 'code_edit_proposal',
    proposalId,
    agentName: ctx.agent.name,
    description: r.description as string,
    filesChanged: resolvedFiles.length,
    additions: r.additions as number,
    deletions: r.deletions as number,
    warnings: r.warnings as string[],
    files: resolvedFiles,
  });
}

// ── Question tool routing ─────────────────────────────────────────────────────

import { requestInput, requestSelect, requestPassword, requestChecklist } from './question-io.js';

interface QuestionArgs {
  question: string;
  questionType?: 'input' | 'confirm' | 'select' | 'checklist' | 'password';
  context?: string;
  choices?: Array<{ name: string; value: string }>;
  default?: unknown;
  allowEmpty?: boolean;
  mask?: string;
}

function parseQuestionArgs(args: unknown): { ok: true; value: QuestionArgs } | { ok: false; error: string } {
  if (!args || typeof args !== 'object') {
    return { ok: false, error: 'ask_human expects an object payload.' };
  }
  const raw = args as Record<string, unknown>;
  const question = typeof raw.question === 'string' ? raw.question.trim() : '';
  if (!question) return { ok: false, error: 'ask_human requires a non-empty question field.' };

  const type = typeof raw.questionType === 'string' ? raw.questionType : 'input';
  const validTypes = ['input', 'confirm', 'select', 'checklist', 'password'] as const;
  if (!validTypes.includes(type as typeof validTypes[number])) {
    return { ok: false, error: `Unsupported questionType '${type}'.` };
  }

  const choices = Array.isArray(raw.choices)
    ? raw.choices
        .filter(e => e && typeof e === 'object')
        .map(e => {
          const r = e as Record<string, unknown>;
          return typeof r.name === 'string' && typeof r.value === 'string'
            ? { name: r.name, value: r.value }
            : undefined;
        })
        .filter((e): e is { name: string; value: string } => Boolean(e))
    : undefined;

  if ((type === 'select' || type === 'checklist') && (!choices || choices.length === 0)) {
    return { ok: false, error: `questionType '${type}' requires a non-empty choices array.` };
  }

  return {
    ok: true,
    value: {
      question,
      questionType: type as QuestionArgs['questionType'],
      context: typeof raw.context === 'string' ? raw.context : undefined,
      choices,
      default: raw.default,
      allowEmpty: typeof raw.allowEmpty === 'boolean' ? raw.allowEmpty : undefined,
      mask: typeof raw.mask === 'string' ? raw.mask : undefined,
    },
  };
}

async function executeQuestionTool(
  toolName: string,
  args: unknown,
  ctx: OrchestratorContext,
): Promise<{ ok: true; result: unknown } | { ok: false; error: string }> {
  const parsed = parseQuestionArgs(args);
  if (!parsed.ok) return { ok: false, error: parsed.error };

  const { question, questionType = 'input', context, choices, default: def, allowEmpty, mask } = parsed.value;
  const message = context ? `${question}\n\nContext: ${context}` : question;

  try {
    switch (questionType) {
      case 'confirm': {
        const answer = await requestConfirm(ctx.hooks, {
          message,
          default: typeof def === 'boolean' ? def : false,
        });
        return { ok: true, result: { question, questionType, answer } };
      }
      case 'select': {
        const answer = await requestSelect(ctx.hooks, {
          message,
          choices: choices!,
        });
        return { ok: true, result: { question, questionType, answer } };
      }
      case 'checklist': {
        const answer = await requestChecklist(ctx.hooks, {
          message,
          choices: choices!,
        });
        return { ok: true, result: { question, questionType, answer } };
      }
      case 'password': {
        const answer = await requestPassword(ctx.hooks, {
          message,
          mask,
        });
        return { ok: true, result: { question, questionType, answer } };
      }
      default: {
        const answer = await requestInput(ctx.hooks, {
          message,
          validate: allowEmpty
            ? undefined
            : (v: string) => v.trim().length > 0 || 'Please provide a non-empty value.',
        });
        return { ok: true, result: { question, questionType, answer } };
      }
    }
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : String(e) };
  }
}

// ── Utilities ─────────────────────────────────────────────────────────────────

function formatArgs(args: unknown): string {
  if (!args || typeof args !== 'object') return String(args ?? '');
  try {
    const s = JSON.stringify(args);
    return s.length > 120 ? s.slice(0, 120) + '…' : s;
  } catch {
    return '[unparseable]';
  }
}

function serialise(value: unknown): string {
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value, null, 2);
  } catch {
    return String(value);
  }
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { SessionManager } from './session-manager.js';
import { SqliteMessageStorage } from './storage/sqlite/sqlite-storage.js';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const tempDirs: string[] = [];

async function createTempWorkspace(): Promise<string> {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'ai-team-sm-test-'));
  tempDirs.push(dir);
  return dir;
}

afterEach(async () => {
  await Promise.all(
    tempDirs.splice(0, tempDirs.length).map(dir =>
      fs.rm(dir, { recursive: true, force: true }),
    ),
  );
});

// ---------------------------------------------------------------------------
// findAgentSessionInChain
// ---------------------------------------------------------------------------

describe('SessionManager.findAgentSessionInChain', () => {
  let sessionManager: SessionManager;

  beforeEach(async () => {
    const workspaceRoot = await createTempWorkspace();
    const storage = new SqliteMessageStorage(workspaceRoot);
    // No AgentManager — IDs are used verbatim
    sessionManager = new SessionManager(workspaceRoot, storage);
    await sessionManager.initialize();
  });

  afterEach(async () => {
    await (sessionManager as any).storage.close();
  });

  it('returns the session when the root session belongs to the target agent', async () => {
    // Single session: root belongs to michael
    const michaelS1 = await sessionManager.createSession('michael-brown', 'dev-1');

    const found = await sessionManager.findAgentSessionInChain(michaelS1.id, 'michael-brown');
    expect(found).not.toBeNull();
    expect(found!.id).toBe(michaelS1.id);
  });

  it('returns null when the target agent has no session in the chain', async () => {
    const michaelS1 = await sessionManager.createSession('michael-brown', 'dev-1');

    const found = await sessionManager.findAgentSessionInChain(michaelS1.id, 'sarah-morgan');
    expect(found).toBeNull();
  });

  it('walks the chain and finds an earlier session for the target agent', async () => {
    // Chain: michaelS1 → alexS1 → michaelS2 (hand back)
    // findAgentSessionInChain(alexS1.id, 'michael-brown') should return michaelS1
    const michaelS1 = await sessionManager.createSession('michael-brown', 'dev-1');
    const alexS1 = await sessionManager.createHandoffSession('alex-johnson', 'dev-1', michaelS1.id);

    const found = await sessionManager.findAgentSessionInChain(alexS1.id, 'michael-brown');
    expect(found).not.toBeNull();
    expect(found!.id).toBe(michaelS1.id);
  });

  it('finds a session two hops back in the chain', async () => {
    // Chain: michaelS1 → alexS1 → sarahS1
    // findAgentSessionInChain(sarahS1.id, 'michael-brown') should return michaelS1
    const michaelS1 = await sessionManager.createSession('michael-brown', 'dev-1');
    const alexS1 = await sessionManager.createHandoffSession('alex-johnson', 'dev-1', michaelS1.id);
    const sarahS1 = await sessionManager.createHandoffSession('sarah-morgan', 'dev-1', alexS1.id);

    const found = await sessionManager.findAgentSessionInChain(sarahS1.id, 'michael-brown');
    expect(found).not.toBeNull();
    expect(found!.id).toBe(michaelS1.id);
  });

  it('finds an intermediate session, not a leaf or root', async () => {
    // Chain: michaelS1 → alexS1 → sarahS1
    // findAgentSessionInChain(sarahS1.id, 'alex-johnson') should return alexS1
    const michaelS1 = await sessionManager.createSession('michael-brown', 'dev-1');
    const alexS1 = await sessionManager.createHandoffSession('alex-johnson', 'dev-1', michaelS1.id);
    const sarahS1 = await sessionManager.createHandoffSession('sarah-morgan', 'dev-1', alexS1.id);

    const found = await sessionManager.findAgentSessionInChain(sarahS1.id, 'alex-johnson');
    expect(found).not.toBeNull();
    expect(found!.id).toBe(alexS1.id);
  });

  it('returns the starting session itself when it belongs to the target agent', async () => {
    // Chain: michaelS1 → alexS1
    // findAgentSessionInChain(alexS1.id, 'alex-johnson') should return alexS1 itself
    const michaelS1 = await sessionManager.createSession('michael-brown', 'dev-1');
    const alexS1 = await sessionManager.createHandoffSession('alex-johnson', 'dev-1', michaelS1.id);

    const found = await sessionManager.findAgentSessionInChain(alexS1.id, 'alex-johnson');
    expect(found).not.toBeNull();
    expect(found!.id).toBe(alexS1.id);
  });
});

// ---------------------------------------------------------------------------
// getSessionChain
// ---------------------------------------------------------------------------

describe('SessionManager.getSessionChain', () => {
  let sessionManager: SessionManager;

  beforeEach(async () => {
    const workspaceRoot = await createTempWorkspace();
    const storage = new SqliteMessageStorage(workspaceRoot);
    sessionManager = new SessionManager(workspaceRoot, storage);
    await sessionManager.initialize();
  });

  afterEach(async () => {
    await (sessionManager as any).storage.close();
  });

  it('returns a single-session chain for a root session', async () => {
    const s1 = await sessionManager.createSession('michael-brown', 'dev-1');

    const chain = await sessionManager.getSessionChain(s1.id);
    expect(chain).toHaveLength(1);
    expect(chain[0].id).toBe(s1.id);
  });

  it('returns sessions ordered root → leaf for a two-session chain', async () => {
    const s1 = await sessionManager.createSession('michael-brown', 'dev-1');
    const s2 = await sessionManager.createHandoffSession('alex-johnson', 'dev-1', s1.id);

    const chain = await sessionManager.getSessionChain(s2.id);
    expect(chain).toHaveLength(2);
    expect(chain[0].id).toBe(s1.id);  // root first
    expect(chain[1].id).toBe(s2.id);  // leaf last
  });

  it('returns sessions ordered root → leaf for a three-session chain', async () => {
    const s1 = await sessionManager.createSession('michael-brown', 'dev-1');
    const s2 = await sessionManager.createHandoffSession('alex-johnson', 'dev-1', s1.id);
    const s3 = await sessionManager.createHandoffSession('sarah-morgan', 'dev-1', s2.id);

    const chain = await sessionManager.getSessionChain(s3.id);
    expect(chain).toHaveLength(3);
    expect(chain[0].id).toBe(s1.id);
    expect(chain[1].id).toBe(s2.id);
    expect(chain[2].id).toBe(s3.id);
  });

  it('can start the walk from any session in the chain', async () => {
    const s1 = await sessionManager.createSession('michael-brown', 'dev-1');
    const s2 = await sessionManager.createHandoffSession('alex-johnson', 'dev-1', s1.id);
    const s3 = await sessionManager.createHandoffSession('sarah-morgan', 'dev-1', s2.id);

    // Starting from the middle session s2 returns the full connected graph
    // (root → all descendants), not just the upward path.
    const chainFromMiddle = await sessionManager.getSessionChain(s2.id);
    expect(chainFromMiddle).toHaveLength(3);
    expect(chainFromMiddle[0].id).toBe(s1.id);
    expect(chainFromMiddle[1].id).toBe(s2.id);
    expect(chainFromMiddle[2].id).toBe(s3.id);
  });
});

import { promises as fs } from 'fs';
import path from 'path';
import { ChatMessage, ChatSession, Artifact, type AgentManager } from '@ai-team/core';
import { resolveAgentForOperation } from './utils/agent-resolution.js';
import type { IMessageStorage } from './storage/contracts.js';

export class SessionManager {
  private workspaceRoot: string;
  private artifactsDir: string;
  private agentManager?: AgentManager;
  private storage: IMessageStorage;

  constructor(workspaceRoot: string, storage: IMessageStorage, agentManager?: AgentManager) {
    this.workspaceRoot = workspaceRoot;
    this.artifactsDir = path.join(workspaceRoot, '.ai-team', 'artifacts', 'briefs');
    this.agentManager = agentManager;
    this.storage = storage;
  }

  /**
   * Initialize storage and directories
   */
  async initialize(): Promise<void> {
    await this.storage.initialize();
    await fs.mkdir(this.artifactsDir, { recursive: true });
  }

  /**
   * Close storage connections
   */
  async close(): Promise<void> {
    await this.storage.close();
  }

  /**
   * Create a new session for an agent
   * @param agentQuery - Agent ID, role, name, or partial match
   * @param developerId - Developer ID
   */
  async createSession(agentQuery: string, developerId: string): Promise<ChatSession> {
    // Resolve agent query to exact ID if AgentManager is available
    let agentId = agentQuery;
    if (this.agentManager) {
      const resolved = resolveAgentForOperation(this.agentManager, agentQuery, 'create session');
      agentId = resolved.id;
    }

    const now = new Date().toISOString();
    const session = await this.storage.createSession({
      agentIds: [agentId],  // Primary field - array for multi-agent support
      agentId,  // Backward compatibility
      developerId,
      startedAt: now,
      lastActivityAt: now,
      artifacts: [],
      allowedFiles: [],
    });

    return session;
  }

  /**
   * Create a new session for a handoff from one agent to another
   * @param toAgentQuery - Target agent ID, role, name, or partial match
   * @param developerId - Developer ID
   * @param previousSessionId - Previous session ID
   * @param transferArtifacts - Whether to transfer artifacts
   * @param transferAllowedFiles - Whether to transfer allowed files
   */
  async createHandoffSession(
    toAgentQuery: string,
    developerId: string,
    previousSessionId: string,
    transferArtifacts: boolean = true,
    transferAllowedFiles: boolean = true
  ): Promise<ChatSession> {
    // Resolve agent query to exact ID if AgentManager is available
    let toAgentId = toAgentQuery;
    if (this.agentManager) {
      const resolved = resolveAgentForOperation(this.agentManager, toAgentQuery, 'create handoff session');
      toAgentId = resolved.id;
    }

    const previousSession = await this.getSession(previousSessionId);
    
    const now = new Date().toISOString();
    const newSession = await this.storage.createSession({
      agentIds: [toAgentId],  // Primary field - array for multi-agent support
      agentId: toAgentId,  // Backward compatibility
      developerId,
      startedAt: now,
      lastActivityAt: now,
      artifacts: transferArtifacts && previousSession ? [...previousSession.artifacts] : [],
      allowedFiles: transferAllowedFiles && previousSession ? [...previousSession.allowedFiles] : [],
      previousSessionId,
    });

    return newSession;
  }

  /**
   * Get the latest (most recent) session for an agent
   * @param agentQuery - Agent ID, role, name, or partial match
   */
  async getLatestSession(agentQuery: string): Promise<ChatSession | null> {
    // Resolve agent query to exact ID if AgentManager is available
    let agentId = agentQuery;
    if (this.agentManager) {
      const resolved = resolveAgentForOperation(this.agentManager, agentQuery, 'get latest session');
      agentId = resolved.id;
    }

    try {
      const sessions = await this.storage.listSessions({
        agentId,
        sortBy: 'lastActivityAt',
        sortOrder: 'desc',
        limit: 1,
      });

      return sessions.length > 0 ? sessions[0] : null;
    } catch (error) {
      console.error('Failed to get latest session:', error);
      return null;
    }
  }

  /**
   * List recent sessions across all agents
   * @param limit - Maximum number of sessions to return (default 10)
   */
  async listRecentSessions(limit = 10): Promise<ChatSession[]> {
    try {
      return await this.storage.listSessions({
        sortBy: 'lastActivityAt',
        sortOrder: 'desc',
        limit,
      });
    } catch (error) {
      console.error('Failed to list recent sessions:', error);
      return [];
    }
  }

  /**
   * List all sessions for an agent
   * @param agentQuery - Agent ID, role, name, or partial match
   * @param limit - Maximum number of sessions to return
   */
  async listSessions(agentQuery: string, limit?: number): Promise<ChatSession[]> {
    // Resolve agent query to exact ID if AgentManager is available
    let agentId = agentQuery;
    if (this.agentManager) {
      const resolved = resolveAgentForOperation(this.agentManager, agentQuery, 'list sessions');
      agentId = resolved.id;
    }

    try {
      return await this.storage.listSessions({
        agentId,
        sortBy: 'lastActivityAt',
        sortOrder: 'desc',
        limit,
      });
    } catch (error) {
      console.error('Failed to list sessions:', error);
      return [];
    }
  }

  /**
   * Load a session by ID
   */
  async getSession(sessionId: string): Promise<ChatSession | null> {
    try {
      return await this.storage.getSession(sessionId);
    } catch (error) {
      return null;
    }
  }

  /**
   * Save session metadata
   */
  async saveSession(session: ChatSession): Promise<void> {
    await this.storage.updateSession(session.id, session);
  }

  /**
   * Get messages for a session
   */
  async getSessionMessages(sessionId: string): Promise<ChatMessage[]> {
    try {
      return await this.storage.getSessionMessages(sessionId);
    } catch (error) {
      // If session doesn't exist, return empty array
      return [];
    }
  }

  /**
   * Append a message to a session
   */
  async appendMessage(sessionId: string, message: ChatMessage): Promise<void> {
    await this.storage.insertMessage(sessionId, message);
  }

  /**
   * Split a session at a specific message index
   * Creates a new session starting from the split point
   */
  async splitSession(
    sessionId: string,
    atIndex: number,
    developerId: string
  ): Promise<ChatSession> {
    const currentSession = await this.getSession(sessionId);
    if (!currentSession) {
      throw new Error(`Session ${sessionId} not found`);
    }

    const messages = await this.getSessionMessages(sessionId);
    if (atIndex < 0 || atIndex >= messages.length) {
      throw new Error(`Invalid split index ${atIndex}`);
    }

    // Create new session
    const newSession = await this.createSession(currentSession.agentId, developerId);

    // Copy messages from split point to new session
    const newMessages = messages.slice(atIndex);
    for (const message of newMessages) {
      await this.appendMessage(newSession.id, message);
    }

    // Delete messages from old session (split point onwards)
    // Since we don't have a bulk delete, we need to delete from the end
    for (let i = messages.length - 1; i >= atIndex; i--) {
      await this.storage.deleteMessage(sessionId, messages[i].timestamp);
    }

    return newSession;
  }

  /**
   * Create an artifact/brief from a range of messages
   */
  async createArtifact(
    sessionId: string,
    fromIndex: number,
    toIndex: number,
    summary: string,
    title: string,
    developerId: string
  ): Promise<Artifact> {
    const session = await this.getSession(sessionId);
    if (!session) {
      throw new Error(`Session ${sessionId} not found`);
    }

    // Generate artifact ID from title (kebab-case)
    const artifactId = title
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .substring(0, 50);

    const timestamp = Date.now();
    const filename = `${artifactId}-${timestamp}.md`;
    const filepath = path.join(this.artifactsDir, filename);

    // Build artifact content
    const content = `# ${title}

**Created:** ${new Date().toISOString()}
**Session:** ${sessionId}
**Created by:** ${developerId}
**Messages:** ${fromIndex} - ${toIndex}

---

${summary}
`;

    // Save artifact file
    await fs.writeFile(filepath, content, 'utf-8');

    const artifact: Artifact = {
      id: artifactId,
      type: 'brief',
      title,
      content: summary,
      createdAt: new Date().toISOString(),
      createdBy: developerId,
      sourceSessionId: sessionId,
      fromMessageIndex: fromIndex,
      toMessageIndex: toIndex,
      filepath: path.relative(this.workspaceRoot, filepath),
    };

    // Add artifact to session
    if (!session.artifacts.includes(artifactId)) {
      session.artifacts.push(artifactId);
      await this.saveSession(session);
    }

    return artifact;
  }

  /**
   * List all artifacts
   */
  async listArtifacts(): Promise<Artifact[]> {
    try {
      const files = await fs.readdir(this.artifactsDir);
      const mdFiles = files.filter((f) => f.endsWith('.md'));

      const artifacts: Artifact[] = [];
      for (const file of mdFiles) {
        const filepath = path.join(this.artifactsDir, file);
        const content = await fs.readFile(filepath, 'utf-8');

        // Parse frontmatter-like metadata
        const titleMatch = content.match(/^# (.+)$/m);
        const createdMatch = content.match(/\*\*Created:\*\* (.+)$/m);
        const sessionMatch = content.match(/\*\*Session:\*\* (.+)$/m);
        const createdByMatch = content.match(/\*\*Created by:\*\* (.+)$/m);
        const messagesMatch = content.match(/\*\*Messages:\*\* (\d+) - (\d+)$/m);

        if (titleMatch && createdMatch && sessionMatch && createdByMatch && messagesMatch) {
          const summaryContent = content.split('---\n')[1]?.trim() || '';
          artifacts.push({
            id: file.replace(/-.+\.md$/, ''),
            type: 'brief',
            title: titleMatch[1],
            content: summaryContent,
            createdAt: createdMatch[1],
            createdBy: createdByMatch[1],
            sourceSessionId: sessionMatch[1],
            fromMessageIndex: parseInt(messagesMatch[1], 10),
            toMessageIndex: parseInt(messagesMatch[2], 10),
            filepath: path.relative(this.workspaceRoot, filepath),
          });
        }
      }

      return artifacts;
    } catch (error) {
      console.error('Failed to list artifacts:', error);
      return [];
    }
  }

  /**
   * Get artifact by ID
   */
  async getArtifact(artifactId: string): Promise<Artifact | null> {
    const artifacts = await this.listArtifacts();
    return artifacts.find((a) => a.id === artifactId) || null;
  }

  /**
   * Get or create the latest session for an agent (auto-resume behavior)
   * @param agentId - Agent ID
   * @param developerId - Developer ID
   * @returns Latest existing session or newly created session
   */
  async getOrCreateLatestSession(agentId: string, developerId: string): Promise<ChatSession> {
    // Try to get latest session first
    const latest = await this.getLatestSession(agentId);
    
    if (latest && latest.developerId === developerId) {
      return latest;
    }
    
    // No session exists or developer mismatch - create new one
    return await this.createSession(agentId, developerId);
  }

  /**
   * Generate a title for a session using LLM
   * Reads first 2 human + 2 agent messages and generates descriptive title
   * @param sessionId - Session ID
   * @param llmService - LLM service instance for title generation
   * @returns Generated title
   */
  async generateTitle(sessionId: string, llmService: any): Promise<string> {
    const messages = await this.getSessionMessages(sessionId);
    
    // Get first 2 human and 2 agent messages for context
    const humanMessages = messages.filter(m => m.isHuman).slice(0, 2);
    const agentMessages = messages.filter(m => !m.isHuman).slice(0, 2);
    const contextMessages = [...humanMessages, ...agentMessages]
      .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())
      .slice(0, 4);
    
    if (contextMessages.length === 0) {
      return 'New Conversation';
    }
    
    // Use LLM to generate title
    const title = await llmService.generateTitle(contextMessages);
    
    // Update session with title
    const session = await this.getSession(sessionId);
    if (session) {
      session.title = title;
      await this.saveSession(session);
    }
    
    return title;
  }

  /**
   * Add an agent to an existing session (multi-agent mode)
   * @param sessionId - Session ID
   * @param agentId - Agent ID to add
   */
  async addAgentToSession(sessionId: string, agentId: string): Promise<ChatSession> {
    await this.storage.addSessionAgent(sessionId, agentId);
    
    // Update lastActivityAt
    await this.storage.updateSession(sessionId, {
      lastActivityAt: new Date().toISOString(),
    });
    
    const session = await this.getSession(sessionId);
    if (!session) {
      throw new Error(`Session ${sessionId} not found`);
    }
    
    return session;
  }

  /**
   * Merge two sessions - combines messages from newer session into older one
   * @param olderSessionId - Target session (will receive all messages)
   * @param newerSessionId - Source session (will be deleted)
   */
  async mergeSessionsIntoOlder(olderSessionId: string, newerSessionId: string): Promise<ChatSession> {
    const olderSession = await this.getSession(olderSessionId);
    const newerSession = await this.getSession(newerSessionId);
    
    if (!olderSession || !newerSession) {
      throw new Error('Both sessions must exist');
    }
    
    if (olderSession.developerId !== newerSession.developerId) {
      throw new Error('Cannot merge sessions from different developers');
    }
    
    // Load messages from newer session and copy to older
    const newerMessages = await this.getSessionMessages(newerSessionId);
    for (const message of newerMessages) {
      await this.storage.insertMessage(olderSessionId, message);
    }
    
    // Merge agentIds arrays
    const mergedAgentIds = new Set([
      ...olderSession.agentIds,
      ...newerSession.agentIds,
    ]);
    
    for (const agentId of mergedAgentIds) {
      await this.storage.addSessionAgent(olderSessionId, agentId);
    }
    
    // Track merge history and merge artifacts/files
    const mergedFromSessionIds = [
      ...(olderSession.mergedFromSessionIds || []),
      newerSessionId,
      ...(newerSession.mergedFromSessionIds || []),
    ];
    
    await this.storage.updateSession(olderSessionId, {
      lastActivityAt: new Date().toISOString(),
      mergedFromSessionIds,
      artifacts: [...new Set([...olderSession.artifacts, ...newerSession.artifacts])],
      allowedFiles: [...new Set([...olderSession.allowedFiles, ...newerSession.allowedFiles])],
    });
    
    // Delete newer session
    await this.storage.deleteSession(newerSessionId);
    
    const updatedSession = await this.getSession(olderSessionId);
    if (!updatedSession) {
      throw new Error(`Failed to retrieve merged session ${olderSessionId}`);
    }
    
    return updatedSession;
  }

  /**
   * Walk the previousSessionId chain from the given session back to the root.
   * Returns sessions ordered root → leaf (oldest first).
   * A visited-set guards against corrupt data cycles.
   */
  async getSessionChain(sessionId: string): Promise<ChatSession[]> {
    // 1. Walk upward to find the root session.
    const upwardChain: ChatSession[] = [];
    const visited = new Set<string>();
    let current: ChatSession | null = await this.getSession(sessionId);

    while (current) {
      if (visited.has(current.id)) break; // cycle guard
      visited.add(current.id);
      upwardChain.push(current);
      if (!current.previousSessionId) break;
      current = await this.getSession(current.previousSessionId);
    }

    upwardChain.reverse(); // root first
    const root = upwardChain[0];
    if (!root) return [];

    // 2. BFS downward from root to collect all descendants.
    // This gives the full connected graph the caller is part of, regardless
    // of which session they started from.
    const allSessions = await this.storage.listSessions(
      root.developerId ? { developerId: root.developerId } : undefined,
    );

    const childrenOf = new Map<string, ChatSession[]>();
    for (const s of allSessions) {
      if (!s.previousSessionId) continue;
      const children = childrenOf.get(s.previousSessionId) ?? [];
      children.push(s);
      childrenOf.set(s.previousSessionId, children);
    }

    // BFS from root
    const result: ChatSession[] = [];
    const queue: ChatSession[] = [root];
    const seen = new Set<string>([root.id]);

    while (queue.length > 0) {
      const node = queue.shift()!;
      result.push(node);
      for (const child of (childrenOf.get(node.id) ?? [])) {
        if (!seen.has(child.id)) {
          seen.add(child.id);
          queue.push(child);
        }
      }
    }

    return result;
  }

  /**
   * Walk the session chain from the given session to the root and return the
   * first session that belongs to the specified agent. Returns null if no such
   * session exists in the chain.
   *
   * This is used by the handoff logic to avoid creating a duplicate session
   * when the developer is sent back to an agent they have already spoken with
   * earlier in the same thread (e.g. Alex → Michael → Alex → Michael should
   * reuse Michael's first session, not open a third one).
   */
  async findAgentSessionInChain(fromSessionId: string, agentId: string): Promise<ChatSession | null> {
    const visited = new Set<string>();
    let current: ChatSession | null = await this.getSession(fromSessionId);

    while (current) {
      if (visited.has(current.id)) break; // cycle guard
      visited.add(current.id);

      const ids: string[] = current.agentIds?.length
        ? current.agentIds
        : current.agentId ? [current.agentId] : [];

      if (ids.includes(agentId)) return current;

      if (!current.previousSessionId) break;
      current = await this.getSession(current.previousSessionId);
    }

    return null;
  }

  /**
   * Delete a session and all its messages
   * @param sessionId - Session ID to delete
   */
  async deleteSession(sessionId: string): Promise<void> {
    await this.storage.deleteSession(sessionId);
  }
}

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { ProposalStore, type StoredProposal } from './proposal-store.js';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const tempDirs: string[] = [];

function createTempWorkspace(): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ai-team-proposals-test-'));
  tempDirs.push(dir);
  return dir;
}

function makeProposal(overrides: Partial<StoredProposal> = {}): StoredProposal {
  return {
    proposalId: 'proposal-abc-123',
    agentName: 'alex-morgan',
    description: 'Update bio section',
    createdAt: '2026-03-05T10:00:00.000Z',
    files: [
      {
        filePath: '/workspace/agents/alex-morgan.md',
        oldContent: '# Alex\n\nOld bio.',
        newContent: '# Alex\n\nNew bio.',
        additions: 1,
        deletions: 1,
      },
    ],
    ...overrides,
  };
}

afterEach(() => {
  for (const dir of tempDirs.splice(0)) {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

// ---------------------------------------------------------------------------
// save
// ---------------------------------------------------------------------------

describe('ProposalStore.save', () => {
  let store: ProposalStore;
  let workspaceRoot: string;

  beforeEach(() => {
    workspaceRoot = createTempWorkspace();
    store = new ProposalStore(workspaceRoot);
  });

  it('creates the proposals directory if it does not exist', () => {
    const proposal = makeProposal();
    store.save(proposal);

    const dir = path.join(workspaceRoot, '.ai-team', 'proposals');
    expect(fs.existsSync(dir)).toBe(true);
  });

  it('writes a JSON file named <proposalId>.json', () => {
    const proposal = makeProposal();
    store.save(proposal);

    const file = path.join(workspaceRoot, '.ai-team', 'proposals', 'proposal-abc-123.json');
    expect(fs.existsSync(file)).toBe(true);
  });

  it('serialises all proposal fields correctly', () => {
    const proposal = makeProposal();
    store.save(proposal);

    const file = path.join(workspaceRoot, '.ai-team', 'proposals', 'proposal-abc-123.json');
    const parsed = JSON.parse(fs.readFileSync(file, 'utf8')) as StoredProposal;

    expect(parsed.proposalId).toBe(proposal.proposalId);
    expect(parsed.agentName).toBe(proposal.agentName);
    expect(parsed.description).toBe(proposal.description);
    expect(parsed.createdAt).toBe(proposal.createdAt);
    expect(parsed.files).toHaveLength(1);
    expect(parsed.files[0].oldContent).toBe('# Alex\n\nOld bio.');
    expect(parsed.files[0].newContent).toBe('# Alex\n\nNew bio.');
  });

  it('overwrites an existing file when saving the same proposalId again', () => {
    const original = makeProposal({ description: 'First save' });
    const updated = makeProposal({ description: 'Second save' });

    store.save(original);
    store.save(updated);

    const file = path.join(workspaceRoot, '.ai-team', 'proposals', 'proposal-abc-123.json');
    const parsed = JSON.parse(fs.readFileSync(file, 'utf8')) as StoredProposal;
    expect(parsed.description).toBe('Second save');
  });

  it('can save multiple proposals with different IDs simultaneously', () => {
    store.save(makeProposal({ proposalId: 'p-1' }));
    store.save(makeProposal({ proposalId: 'p-2' }));
    store.save(makeProposal({ proposalId: 'p-3' }));

    const dir = path.join(workspaceRoot, '.ai-team', 'proposals');
    const files = fs.readdirSync(dir);
    expect(files).toHaveLength(3);
    expect(files.sort()).toEqual(['p-1.json', 'p-2.json', 'p-3.json']);
  });
});

// ---------------------------------------------------------------------------
// delete
// ---------------------------------------------------------------------------

describe('ProposalStore.delete', () => {
  let store: ProposalStore;

  beforeEach(() => {
    store = new ProposalStore(createTempWorkspace());
  });

  it('removes the proposal file from disk', () => {
    const proposal = makeProposal();
    store.save(proposal);
    store.delete(proposal.proposalId);

    const file = path.join(
      (store as any).dir,
      `${proposal.proposalId}.json`,
    );
    expect(fs.existsSync(file)).toBe(false);
  });

  it('does not throw when deleting a non-existent proposal (ENOENT)', () => {
    expect(() => store.delete('does-not-exist')).not.toThrow();
  });

  it('only removes the targeted proposal, leaving others intact', () => {
    store.save(makeProposal({ proposalId: 'keep-me' }));
    store.save(makeProposal({ proposalId: 'delete-me' }));

    store.delete('delete-me');

    const remaining = store.loadAll();
    expect(remaining).toHaveLength(1);
    expect(remaining[0].proposalId).toBe('keep-me');
  });
});

// ---------------------------------------------------------------------------
// loadAll
// ---------------------------------------------------------------------------

describe('ProposalStore.loadAll', () => {
  let store: ProposalStore;

  beforeEach(() => {
    store = new ProposalStore(createTempWorkspace());
  });

  it('returns an empty array when the proposals directory does not exist', () => {
    expect(store.loadAll()).toEqual([]);
  });

  it('returns an empty array when the directory exists but is empty', () => {
    fs.mkdirSync(path.join((store as any).dir), { recursive: true });
    expect(store.loadAll()).toEqual([]);
  });

  it('returns all saved proposals', () => {
    store.save(makeProposal({ proposalId: 'p-1' }));
    store.save(makeProposal({ proposalId: 'p-2' }));

    const all = store.loadAll();
    expect(all).toHaveLength(2);
    const ids = all.map(p => p.proposalId).sort();
    expect(ids).toEqual(['p-1', 'p-2']);
  });

  it('skips corrupt/non-JSON files without throwing', () => {
    fs.mkdirSync(path.join((store as any).dir), { recursive: true });
    fs.writeFileSync(path.join((store as any).dir, 'corrupt.json'), 'not-json', 'utf8');
    store.save(makeProposal({ proposalId: 'valid-one' }));

    const all = store.loadAll();
    expect(all).toHaveLength(1);
    expect(all[0].proposalId).toBe('valid-one');
  });

  it('ignores non-.json files in the directory', () => {
    fs.mkdirSync(path.join((store as any).dir), { recursive: true });
    fs.writeFileSync(path.join((store as any).dir, 'readme.txt'), 'hello', 'utf8');
    store.save(makeProposal({ proposalId: 'p-1' }));

    const all = store.loadAll();
    expect(all).toHaveLength(1);
  });

  it('preserves oldContent and newContent faithfully (used for undo and diff)', () => {
    const proposal = makeProposal({
      files: [
        {
          filePath: '/workspace/src/index.ts',
          oldContent: 'const x = 1;',
          newContent: 'const x = 42;',
          additions: 1,
          deletions: 1,
        },
      ],
    });
    store.save(proposal);

    const [loaded] = store.loadAll();
    expect(loaded.files[0].oldContent).toBe('const x = 1;');
    expect(loaded.files[0].newContent).toBe('const x = 42;');
  });
});

// ---------------------------------------------------------------------------
// load (single)
// ---------------------------------------------------------------------------

describe('ProposalStore.load', () => {
  let store: ProposalStore;

  beforeEach(() => {
    store = new ProposalStore(createTempWorkspace());
  });

  it('returns the proposal when it exists', () => {
    const proposal = makeProposal();
    store.save(proposal);

    const loaded = store.load(proposal.proposalId);
    expect(loaded).not.toBeNull();
    expect(loaded!.proposalId).toBe(proposal.proposalId);
  });

  it('returns null for a non-existent proposalId', () => {
    expect(store.load('ghost-id')).toBeNull();
  });

  it('returns null for a corrupt file', () => {
    fs.mkdirSync(path.join((store as any).dir), { recursive: true });
    fs.writeFileSync(path.join((store as any).dir, 'bad.json'), '{broken', 'utf8');

    expect(store.load('bad')).toBeNull();
  });
});

// ---------------------------------------------------------------------------
// round-trip
// ---------------------------------------------------------------------------

describe('ProposalStore round-trip', () => {
  it('save → loadAll → delete lifecycle works end-to-end', () => {
    const workspaceRoot = createTempWorkspace();
    const store = new ProposalStore(workspaceRoot);

    // Nothing pending initially
    expect(store.loadAll()).toHaveLength(0);

    // Save two proposals
    store.save(makeProposal({ proposalId: 'r-1', description: 'First' }));
    store.save(makeProposal({ proposalId: 'r-2', description: 'Second' }));
    expect(store.loadAll()).toHaveLength(2);

    // Accept r-1 (user clicks Keep)
    store.delete('r-1');
    const remaining = store.loadAll();
    expect(remaining).toHaveLength(1);
    expect(remaining[0].proposalId).toBe('r-2');

    // Reject r-2 (user clicks Undo)
    store.delete('r-2');
    expect(store.loadAll()).toHaveLength(0);
  });

  it('a fresh ProposalStore on same workspaceRoot sees previously persisted proposals', () => {
    const workspaceRoot = createTempWorkspace();

    // Simulate api-server writing the proposal
    const storeA = new ProposalStore(workspaceRoot);
    storeA.save(makeProposal({ proposalId: 'persisted-1' }));

    // Simulate IDE reconnect: new ProposalStore instance reads from disk
    const storeB = new ProposalStore(workspaceRoot);
    const all = storeB.loadAll();
    expect(all).toHaveLength(1);
    expect(all[0].proposalId).toBe('persisted-1');
  });
});

import * as fs from 'fs';
import * as path from 'path';

export interface StoredProposalFile {
  filePath: string;   // absolute path
  oldContent: string;
  newContent: string;
  additions?: number;
  deletions?: number;
}

export interface StoredProposal {
  proposalId: string;
  agentName: string;
  description: string;
  createdAt: string; // ISO date
  files: StoredProposalFile[];
}

/**
 * Persists code-edit proposals to `.ai-team/proposals/<id>.json`.
 *
 * Used by:
 *  - service layer (chat.ts): save on proposal creation, delete on ack
 *  - api-server (routes/ide.ts): loadAll() on IDE reconnect to replay pending proposals
 *  - cli: save when it directly writes code edits to disk
 */
export class ProposalStore {
  private readonly dir: string;

  constructor(workspaceRoot: string) {
    this.dir = path.join(workspaceRoot, '.ai-team', 'proposals');
  }

  save(proposal: StoredProposal): void {
    fs.mkdirSync(this.dir, { recursive: true });
    fs.writeFileSync(
      path.join(this.dir, `${proposal.proposalId}.json`),
      JSON.stringify(proposal, null, 2),
      'utf8',
    );
  }

  delete(proposalId: string): void {
    try {
      fs.unlinkSync(path.join(this.dir, `${proposalId}.json`));
    } catch (err: any) {
      if (err?.code !== 'ENOENT') throw err;
    }
  }

  loadAll(): StoredProposal[] {
    try {
      const files = fs.readdirSync(this.dir);
      const proposals: StoredProposal[] = [];
      for (const file of files) {
        if (!file.endsWith('.json')) continue;
        try {
          const content = fs.readFileSync(path.join(this.dir, file), 'utf8');
          proposals.push(JSON.parse(content) as StoredProposal);
        } catch {
          // skip corrupt files
        }
      }
      return proposals;
    } catch {
      return [];
    }
  }

  load(proposalId: string): StoredProposal | null {
    try {
      const content = fs.readFileSync(path.join(this.dir, `${proposalId}.json`), 'utf8');
      return JSON.parse(content) as StoredProposal;
    } catch {
      return null;
    }
  }
}

import sqlite3 from 'sqlite3';
import * as path from 'node:path';
import * as fs from 'node:fs/promises';

/**
 * Promisified SQLite database wrapper
 * Wraps the callback-based sqlite3 API with Promises for async/await usage
 */
export class SqliteConnection {
  private db: sqlite3.Database | null = null;
  private dbPath: string;
  
  constructor(workspaceRoot: string, dbFileName: string = 'ai-team.db') {
    const dbDir = path.join(workspaceRoot, '.ai-team', 'private');
    this.dbPath = path.join(dbDir, dbFileName);
  }
  
  /**
   * Open the database connection
   * Creates the .ai-team/private directory if it doesn't exist
   * Enables WAL mode for better concurrent access
   */
  async open(): Promise<void> {
    if (this.db) {
      return; // Already open
    }
    
    // Ensure directory exists
    const dbDir = path.dirname(this.dbPath);
    await fs.mkdir(dbDir, { recursive: true });
    
    return new Promise((resolve, reject) => {
      this.db = new sqlite3.Database(this.dbPath, (err) => {
        if (err) {
          reject(new Error(`Failed to open database at ${this.dbPath}: ${err.message}`));
          return;
        }
        
        // Enable WAL mode for concurrent reads/writes
        this.db!.run('PRAGMA journal_mode = WAL;', (walErr) => {
          if (walErr) {
            reject(new Error(`Failed to enable WAL mode: ${walErr.message}`));
            return;
          }
          
          // Enable foreign keys
          this.db!.run('PRAGMA foreign_keys = ON;', (fkErr) => {
            if (fkErr) {
              reject(new Error(`Failed to enable foreign keys: ${fkErr.message}`));
              return;
            }
            resolve();
          });
        });
      });
    });
  }
  
  /**
   * Close the database connection
   */
  async close(): Promise<void> {
    if (!this.db) {
      return;
    }
    
    return new Promise((resolve, reject) => {
      this.db!.close((err) => {
        this.db = null;
        if (err) {
          reject(new Error(`Failed to close database: ${err.message}`));
        } else {
          resolve();
        }
      });
    });
  }
  
  /**
   * Execute a SQL query that doesn't return rows (INSERT, UPDATE, DELETE, CREATE, etc.)
   * @returns Object with lastID and changes count
   */
  async run(sql: string, params: any[] = []): Promise<{ lastID: number; changes: number }> {
    if (!this.db) {
      throw new Error('Database not open. Call open() first.');
    }
    
    return new Promise((resolve, reject) => {
      this.db!.run(sql, params, function(err) {
        if (err) {
          reject(new Error(`SQL run error: ${err.message}\nSQL: ${sql}`));
        } else {
          resolve({ lastID: this.lastID, changes: this.changes });
        }
      });
    });
  }
  
  /**
   * Execute a SQL query that returns a single row
   * @returns The first row or null if no results
   */
  async get<T = any>(sql: string, params: any[] = []): Promise<T | null> {
    if (!this.db) {
      throw new Error('Database not open. Call open() first.');
    }
    
    return new Promise((resolve, reject) => {
      this.db!.get(sql, params, (err, row) => {
        if (err) {
          reject(new Error(`SQL get error: ${err.message}\nSQL: ${sql}`));
        } else {
          resolve((row as T) || null);
        }
      });
    });
  }
  
  /**
   * Execute a SQL query that returns multiple rows
   * @returns Array of rows (empty array if no results)
   */
  async all<T = any>(sql: string, params: any[] = []): Promise<T[]> {
    if (!this.db) {
      throw new Error('Database not open. Call open() first.');
    }
    
    return new Promise((resolve, reject) => {
      this.db!.all(sql, params, (err, rows) => {
        if (err) {
          reject(new Error(`SQL all error: ${err.message}\nSQL: ${sql}`));
        } else {
          resolve((rows as T[]) || []);
        }
      });
    });
  }
  
  /**
   * Execute multiple SQL statements in one string (convenience method for migrations)
   * Cannot use parameterized queries. Use transaction() method if you need parameters.
   */
  async exec(sql: string): Promise<void> {
    if (!this.db) {
      throw new Error('Database not open. Call open() first.');
    }
    
    return new Promise((resolve, reject) => {
      this.db!.exec(sql, (err) => {
        if (err) {
          reject(new Error(`SQL exec error: ${err.message}`));
        } else {
          resolve();
        }
      });
    });
  }
  
  /**
   * Execute multiple SQL statements in a transaction
   * If any statement fails, the entire transaction is rolled back
   */
  async transaction(statements: Array<{ sql: string; params?: any[] }>): Promise<void> {
    if (!this.db) {
      throw new Error('Database not open. Call open() first.');
    }
    
    await this.run('BEGIN TRANSACTION');
    
    try {
      for (const stmt of statements) {
        await this.run(stmt.sql, stmt.params || []);
      }
      await this.run('COMMIT');
    } catch (error) {
      await this.run('ROLLBACK');
      throw error;
    }
  }
  
  /**
   * Get the database file path
   */
  getPath(): string {
    return this.dbPath;
  }
  
  /**
   * Check if database file exists
   */
  async exists(): Promise<boolean> {
    try {
      await fs.access(this.dbPath);
      return true;
    } catch {
      return false;
    }
  }
}

import type { ChatMessage, ChatSession } from '@ai-team/core';
import type {
  IMessageStorage,
  MessageFilter,
  SessionFilter,
  StorageStats,
  MessageInsertResult,
  Note,
} from '../contracts.js';
import { SqliteConnection } from './connection.js';
import { MigrationManager } from './migrations.js';
import * as fs from 'node:fs/promises';
import { randomBytes } from 'node:crypto';

/**
 * SQLite-based implementation of message storage
 * Stores messages and sessions in a local SQLite database
 */
export class SqliteMessageStorage implements IMessageStorage {
  private connection: SqliteConnection;
  private migrations: MigrationManager;
  
  constructor(workspaceRoot: string) {
    this.connection = new SqliteConnection(workspaceRoot);
    this.migrations = new MigrationManager(this.connection);
  }
  
  // ========== Lifecycle ==========
  
  async initialize(): Promise<void> {
    await this.connection.open();
    await this.migrations.initialize();
  }
  
  async close(): Promise<void> {
    await this.connection.close();
  }
  
  // ========== Messages ==========
  
  async insertMessage(sessionId: string, message: ChatMessage): Promise<MessageInsertResult> {
    const timestamp = message.timestamp || new Date().toISOString();
    
    // Start transaction
    const statements: Array<{ sql: string; params?: any[] }> = [];
    
    // Insert message
    const messageResult = await this.connection.run(
      `INSERT INTO messages (session_id, timestamp, from_id, to_id, is_human, content, archived, handoff_type, target_agent_id, handoff_from_session_id, handoff_to_session_id, handoff_id, importance)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        sessionId,
        timestamp,
        message.from,
        message.to || null,
        message.isHuman ? 1 : 0,
        message.content,
        message.archived ? 1 : 0,
        message.handoffType || null,
        message.targetAgentId || null,
        message.handoffFromSessionId || null,
        message.handoffToSessionId || null,
        message.handoffId || null,
        message.importance || null,
      ]
    );
    
    const messageId = messageResult.lastID;
    
    // Insert context files
    if (message.context && message.context.length > 0) {
      for (const filePath of message.context) {
        statements.push({
          sql: 'INSERT INTO message_files (message_id, file_path) VALUES (?, ?)',
          params: [messageId, filePath],
        });
      }
    }
    
    // Insert tool calls
    if (message.tool_calls && message.tool_calls.length > 0) {
      for (const toolCall of message.tool_calls) {
        statements.push({
          sql: 'INSERT INTO message_tool_calls (message_id, tool_name, params_json, result_json) VALUES (?, ?, ?, ?)',
          params: [
            messageId,
            toolCall.tool,
            JSON.stringify(toolCall.params),
            toolCall.result ? JSON.stringify(toolCall.result) : null,
          ],
        });
      }
    }
    
    // Insert code suggestions
    if (message.suggestions && message.suggestions.length > 0) {
      for (const suggestion of message.suggestions) {
        statements.push({
          sql: 'INSERT INTO message_suggestions (message_id, suggestion_type, file_path, line_number, description, code) VALUES (?, ?, ?, ?, ?, ?)',
          params: [
            messageId,
            suggestion.type,
            suggestion.file,
            suggestion.line || null,
            suggestion.description,
            suggestion.code || null,
          ],
        });
      }
    }
    
    // Update session message count and last activity
    statements.push({
      sql: `UPDATE sessions 
            SET message_count = message_count + 1,
                last_activity_at = ?,
                updated_at = ?
            WHERE id = ?`,
      params: [timestamp, timestamp, sessionId],
    });
    
    // Execute all statements in transaction
    if (statements.length > 0) {
      await this.connection.transaction(statements);
    }
    
    return {
      messageId,
      timestamp,
    };
  }
  
  async getSessionMessages(sessionId: string, includeArchived: boolean = false): Promise<ChatMessage[]> {
    const sql = `
      SELECT 
        m.id,
        m.timestamp,
        m.from_id,
        m.to_id,
        m.is_human,
        m.content,
        m.archived,
        m.handoff_type,
        m.target_agent_id,
        m.handoff_from_session_id,
        m.handoff_to_session_id,
        m.handoff_id,
        m.importance
      FROM messages m
      WHERE m.session_id = ?
        ${!includeArchived ? 'AND m.archived = 0' : ''}
      ORDER BY m.timestamp ASC
    `;
    
    const rows = await this.connection.all<any>(sql, [sessionId]);
    
    // Load related data for each message
    const messages: ChatMessage[] = [];
    for (const row of rows) {
      const message = await this.rowToMessage(row);
      messages.push(message);
    }
    
    return messages;
  }
  
  async queryMessages(filter: MessageFilter): Promise<ChatMessage[]> {
    const conditions: string[] = [];
    const params: any[] = [];
    
    if (filter.sessionId) {
      conditions.push('m.session_id = ?');
      params.push(filter.sessionId);
    }
    
    if (filter.fromId) {
      conditions.push('m.from_id = ?');
      params.push(filter.fromId);
    }
    
    if (filter.toId) {
      conditions.push('m.to_id = ?');
      params.push(filter.toId);
    }
    
    if (filter.isHuman !== undefined) {
      conditions.push('m.is_human = ?');
      params.push(filter.isHuman ? 1 : 0);
    }
    
    if (filter.archived !== undefined) {
      conditions.push('m.archived = ?');
      params.push(filter.archived ? 1 : 0);
    }
    
    if (filter.handoffType) {
      conditions.push('m.handoff_type = ?');
      params.push(filter.handoffType);
    }
    
    if (filter.timestampFrom) {
      conditions.push('m.timestamp >= ?');
      params.push(filter.timestampFrom);
    }
    
    if (filter.timestampTo) {
      conditions.push('m.timestamp <= ?');
      params.push(filter.timestampTo);
    }
    
    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
    const limitClause = filter.limit ? `LIMIT ${filter.limit}` : '';
    const offsetClause = filter.offset ? `OFFSET ${filter.offset}` : '';
    
    const sql = `
      SELECT 
        m.id,
        m.timestamp,
        m.from_id,
        m.to_id,
        m.is_human,
        m.content,
        m.archived,
        m.handoff_type,
        m.target_agent_id,
        m.handoff_from_session_id,
        m.handoff_to_session_id,
        m.handoff_id,
        m.importance
      FROM messages m
      ${whereClause}
      ORDER BY m.timestamp ASC
      ${limitClause} ${offsetClause}
    `;
    
    const rows = await this.connection.all<any>(sql, params);
    
    const messages: ChatMessage[] = [];
    for (const row of rows) {
      const message = await this.rowToMessage(row);
      messages.push(message);
    }
    
    return messages;
  }
  
  async archiveMessage(sessionId: string, messageTimestamp: string): Promise<boolean> {
    const result = await this.connection.run(
      'UPDATE messages SET archived = 1 WHERE session_id = ? AND timestamp = ?',
      [sessionId, messageTimestamp]
    );
    return result.changes > 0;
  }
  
  async deleteMessage(sessionId: string, messageTimestamp: string): Promise<boolean> {
    // Get message ID first
    const row = await this.connection.get<{ id: number }>(
      'SELECT id FROM messages WHERE session_id = ? AND timestamp = ?',
      [sessionId, messageTimestamp]
    );
    
    if (!row) {
      return false;
    }
    
    // Delete message (CASCADE will delete related rows)
    await this.connection.transaction([
      {
        sql: 'DELETE FROM messages WHERE id = ?',
        params: [row.id],
      },
      {
        sql: 'UPDATE sessions SET message_count = message_count - 1, updated_at = ? WHERE id = ?',
        params: [new Date().toISOString(), sessionId],
      },
    ]);
    
    return true;
  }
  
  async searchMessages(query: string, sessionId?: string): Promise<ChatMessage[]> {
    // Use FTS5 for full-text search with relevance ranking
    const conditions = ['messages_fts MATCH ?'];
    const params: any[] = [query];
    
    if (sessionId) {
      conditions.push('messages_fts.session_id = ?');
      params.push(sessionId);
    }
    
    const sql = `
      SELECT 
        m.id,
        m.timestamp,
        m.from_id,
        m.to_id,
        m.is_human,
        m.content,
        m.archived,
        m.handoff_type,
        m.target_agent_id,
        m.handoff_from_session_id,
        m.handoff_to_session_id,
        m.handoff_id,
        m.importance,
        messages_fts.rank
      FROM messages m
      INNER JOIN messages_fts ON messages_fts.message_id = m.id
      WHERE ${conditions.join(' AND ')}
      ORDER BY messages_fts.rank, m.timestamp DESC
      LIMIT 100
    `;
    
    const rows = await this.connection.all<any>(sql, params);
    
    const messages: ChatMessage[] = [];
    for (const row of rows) {
      const message = await this.rowToMessage(row);
      messages.push(message);
    }
    
    return messages;
  }
  
  // ========== Sessions ==========
  
  async createSession(session: Omit<ChatSession, 'id' | 'messageCount'>): Promise<ChatSession> {
    const now = new Date().toISOString();
    const id = session.startedAt ? `session-${session.startedAt.split('T')[0]}-${Math.random().toString(36).substring(2, 8)}` : `session-${now.split('T')[0]}-${Math.random().toString(36).substring(2, 8)}`;
    
    const statements: Array<{ sql: string; params?: any[] }> = [];
    
    // Insert session
    statements.push({
      sql: `INSERT INTO sessions (
        id, developer_id, started_at, last_activity_at, message_count,
        title, notes, previous_session_id, created_at, updated_at
      ) VALUES (?, ?, ?, ?, 0, ?, ?, ?, ?, ?)`,
      params: [
        id,
        session.developerId,
        session.startedAt || now,
        session.lastActivityAt || now,
        session.title || null,
        session.notes || null,
        session.previousSessionId || null,
        now,
        now,
      ],
    });
    
    // Insert agent associations
    for (const agentId of session.agentIds) {
      statements.push({
        sql: 'INSERT INTO session_agents (session_id, agent_id) VALUES (?, ?)',
        params: [id, agentId],
      });
    }
    
    // Insert artifacts
    if (session.artifacts && session.artifacts.length > 0) {
      for (const artifact of session.artifacts) {
        statements.push({
          sql: 'INSERT INTO session_artifacts (session_id, artifact_path) VALUES (?, ?)',
          params: [id, artifact],
        });
      }
    }
    
    // Insert allowed files
    if (session.allowedFiles && session.allowedFiles.length > 0) {
      for (const filePath of session.allowedFiles) {
        statements.push({
          sql: 'INSERT INTO session_files (session_id, file_path, is_prioritized) VALUES (?, ?, ?)',
          params: [id, filePath, session.prioritizedFiles?.includes(filePath) ? 1 : 0],
        });
      }
    }
    
    // Insert tasks
    if (session.tasks && session.tasks.length > 0) {
      for (const taskId of session.tasks) {
        statements.push({
          sql: 'INSERT INTO session_tasks (session_id, task_id) VALUES (?, ?)',
          params: [id, taskId],
        });
      }
    }
    
    // Insert merged from sessions
    if (session.mergedFromSessionIds && session.mergedFromSessionIds.length > 0) {
      for (const mergedId of session.mergedFromSessionIds) {
        statements.push({
          sql: 'INSERT INTO session_merged_from (session_id, merged_session_id) VALUES (?, ?)',
          params: [id, mergedId],
        });
      }
    }
    
    // Insert RAG config
    if (session.ragConfig) {
      statements.push({
        sql: 'INSERT INTO session_rag_config (session_id, config_json) VALUES (?, ?)',
        params: [id, JSON.stringify(session.ragConfig)],
      });
    }
    
    await this.connection.transaction(statements);
    
    return {
      id,
      ...session,
      messageCount: 0,
    };
  }
  
  async getSession(sessionId: string): Promise<ChatSession | null> {
    const row = await this.connection.get<any>(
      `SELECT 
        id, developer_id, started_at, last_activity_at, message_count,
        title, notes, previous_session_id, created_at, updated_at
       FROM sessions
       WHERE id = ?`,
      [sessionId]
    );
    
    if (!row) {
      return null;
    }
    
    return this.rowToSession(row);
  }
  
  async updateSession(sessionId: string, updates: Partial<Omit<ChatSession, 'id' | 'messageCount'>>): Promise<void> {
    const now = new Date().toISOString();
    const statements: Array<{ sql: string; params?: any[] }> = [];
    
    // Build UPDATE statement for main session fields
    const fields: string[] = [];
    const params: any[] = [];
    
    if (updates.title !== undefined) {
      fields.push('title = ?');
      params.push(updates.title);
    }
    
    if (updates.notes !== undefined) {
      fields.push('notes = ?');
      params.push(updates.notes);
    }
    
    if (updates.lastActivityAt) {
      fields.push('last_activity_at = ?');
      params.push(updates.lastActivityAt);
    }
    
    if (updates.previousSessionId !== undefined) {
      fields.push('previous_session_id = ?');
      params.push(updates.previousSessionId);
    }
    
    fields.push('updated_at = ?');
    params.push(now);
    
    if (fields.length > 0) {
      params.push(sessionId);
      statements.push({
        sql: `UPDATE sessions SET ${fields.join(', ')} WHERE id = ?`,
        params,
      });
    }
    
    // Handle artifacts update
    if (updates.artifacts !== undefined) {
      statements.push({
        sql: 'DELETE FROM session_artifacts WHERE session_id = ?',
        params: [sessionId],
      });
      for (const artifact of updates.artifacts) {
        statements.push({
          sql: 'INSERT INTO session_artifacts (session_id, artifact_path) VALUES (?, ?)',
          params: [sessionId, artifact],
        });
      }
    }
    
    // Handle files update
    if (updates.allowedFiles !== undefined || updates.prioritizedFiles !== undefined) {
      statements.push({
        sql: 'DELETE FROM session_files WHERE session_id = ?',
        params: [sessionId],
      });
      const allowedFiles = updates.allowedFiles || [];
      const prioritizedFiles = updates.prioritizedFiles || [];
      for (const filePath of allowedFiles) {
        statements.push({
          sql: 'INSERT INTO session_files (session_id, file_path, is_prioritized) VALUES (?, ?, ?)',
          params: [sessionId, filePath, prioritizedFiles.includes(filePath) ? 1 : 0],
        });
      }
    }
    
    // Handle tasks update
    if (updates.tasks !== undefined) {
      statements.push({
        sql: 'DELETE FROM session_tasks WHERE session_id = ?',
        params: [sessionId],
      });
      for (const taskId of updates.tasks) {
        statements.push({
          sql: 'INSERT INTO session_tasks (session_id, task_id) VALUES (?, ?)',
          params: [sessionId, taskId],
        });
      }
    }
    
    // Handle RAG config update
    if (updates.ragConfig !== undefined) {
      statements.push({
        sql: 'DELETE FROM session_rag_config WHERE session_id = ?',
        params: [sessionId],
      });
      if (updates.ragConfig) {
        statements.push({
          sql: 'INSERT INTO session_rag_config (session_id, config_json) VALUES (?, ?)',
          params: [sessionId, JSON.stringify(updates.ragConfig)],
        });
      }
    }
    
    // Handle merged sessions tracking
    if (updates.mergedFromSessionIds !== undefined) {
      statements.push({
        sql: 'DELETE FROM session_merged_from WHERE session_id = ?',
        params: [sessionId],
      });
      for (const mergedId of updates.mergedFromSessionIds) {
        statements.push({
          sql: 'INSERT INTO session_merged_from (session_id, merged_session_id) VALUES (?, ?)',
          params: [sessionId, mergedId],
        });
      }
    }
    
    if (statements.length > 0) {
      await this.connection.transaction(statements);
    }
  }
  
  async listSessions(filter?: SessionFilter): Promise<ChatSession[]> {
    const conditions: string[] = [];
    const params: any[] = [];
    
    if (filter?.developerId) {
      conditions.push('s.developer_id = ?');
      params.push(filter.developerId);
    }
    
    if (filter?.agentId) {
      conditions.push('EXISTS (SELECT 1 FROM session_agents sa WHERE sa.session_id = s.id AND sa.agent_id = ?)');
      params.push(filter.agentId);
    }
    
    if (filter?.hasAgents && filter.hasAgents.length > 0) {
      for (const agentId of filter.hasAgents) {
        conditions.push('EXISTS (SELECT 1 FROM session_agents sa WHERE sa.session_id = s.id AND sa.agent_id = ?)');
        params.push(agentId);
      }
    }
    
    if (filter?.timestampFrom) {
      conditions.push('s.started_at >= ?');
      params.push(filter.timestampFrom);
    }
    
    if (filter?.timestampTo) {
      conditions.push('s.started_at <= ?');
      params.push(filter.timestampTo);
    }
    
    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
    const sortBy = filter?.sortBy || 'lastActivityAt';
    const sortOrder = filter?.sortOrder || 'desc';
    const orderByColumn = sortBy === 'lastActivityAt' ? 'last_activity_at' :
                           sortBy === 'startedAt' ? 'started_at' :
                           'message_count';
    const orderClause = `ORDER BY s.${orderByColumn} ${sortOrder.toUpperCase()}`;
    const limitClause = filter?.limit ? `LIMIT ${filter.limit}` : '';
    const offsetClause = filter?.offset ? `OFFSET ${filter.offset}` : '';
    
    const sql = `
      SELECT 
        s.id, s.developer_id, s.started_at, s.last_activity_at, s.message_count,
        s.title, s.notes, s.previous_session_id, s.created_at, s.updated_at
      FROM sessions s
      ${whereClause}
      ${orderClause}
      ${limitClause} ${offsetClause}
    `;
    
    const rows = await this.connection.all<any>(sql, params);
    
    const sessions: ChatSession[] = [];
    for (const row of rows) {
      const session = await this.rowToSession(row);
      sessions.push(session);
    }
    
    return sessions;
  }
  
  async deleteSession(sessionId: string): Promise<boolean> {
    // NULL-out cross-session references before deleting so linked sessions/messages
    // don't hold dangling IDs. These columns have no FK ON DELETE SET NULL because
    // they were added via ALTER TABLE (SQLite limitation).
    await this.connection.run(
      'UPDATE sessions SET previous_session_id = NULL WHERE previous_session_id = ?',
      [sessionId]
    );
    await this.connection.run(
      'UPDATE messages SET handoff_from_session_id = NULL WHERE handoff_from_session_id = ?',
      [sessionId]
    );
    await this.connection.run(
      'UPDATE messages SET handoff_to_session_id = NULL WHERE handoff_to_session_id = ?',
      [sessionId]
    );
    const result = await this.connection.run(
      'DELETE FROM sessions WHERE id = ?',
      [sessionId]
    );
    return result.changes > 0;
  }
  
  async addSessionAgent(sessionId: string, agentId: string): Promise<void> {
    await this.connection.run(
      'INSERT OR IGNORE INTO session_agents (session_id, agent_id) VALUES (?, ?)',
      [sessionId, agentId]
    );
  }
  
  async removeSessionAgent(sessionId: string, agentId: string): Promise<void> {
    await this.connection.run(
      'DELETE FROM session_agents WHERE session_id = ? AND agent_id = ?',
      [sessionId, agentId]
    );
  }
  
  // ========== Statistics ==========
  
  async getStats(): Promise<StorageStats> {
    const sessionCount = await this.connection.get<{ count: number }>(
      'SELECT COUNT(*) as count FROM sessions'
    );
    
    const messageCount = await this.connection.get<{ count: number }>(
      'SELECT COUNT(*) as count FROM messages'
    );
    
    const version = await this.migrations.getCurrentVersion();
    
    let storageSize: number | undefined;
    try {
      const dbPath = this.connection.getPath();
      const stats = await fs.stat(dbPath);
      storageSize = stats.size;
    } catch {
      // File doesn't exist or can't be accessed
      storageSize = undefined;
    }
    
    return {
      totalSessions: sessionCount?.count || 0,
      totalMessages: messageCount?.count || 0,
      storageSize,
      schemaVersion: version,
    };
  }
  
  // ========== Helper Methods ==========
  
  /**
   * Convert a database row to a ChatMessage with all related data
   */
  private async rowToMessage(row: any): Promise<ChatMessage> {
    const messageId = row.id;
    
    // Load context files
    const contextRows = await this.connection.all<{ file_path: string }>(
      'SELECT file_path FROM message_files WHERE message_id = ?',
      [messageId]
    );
    const context = contextRows.map(r => r.file_path);
    
    // Load tool calls
    const toolCallRows = await this.connection.all<any>(
      'SELECT tool_name, params_json, result_json FROM message_tool_calls WHERE message_id = ?',
      [messageId]
    );
    const tool_calls = toolCallRows.map(r => ({
      tool: r.tool_name,
      params: JSON.parse(r.params_json),
      result: r.result_json ? JSON.parse(r.result_json) : undefined,
    }));
    
    // Load suggestions
    const suggestionRows = await this.connection.all<any>(
      'SELECT suggestion_type, file_path, line_number, description, code FROM message_suggestions WHERE message_id = ?',
      [messageId]
    );
    const suggestions = suggestionRows.map(r => ({
      type: r.suggestion_type as any,
      file: r.file_path,
      line: r.line_number || undefined,
      description: r.description,
      code: r.code || undefined,
    }));
    
    return {
      timestamp: row.timestamp,
      from: row.from_id,
      to: row.to_id || undefined,
      isHuman: row.is_human === 1,
      content: row.content,
      context: context.length > 0 ? context : undefined,
      tool_calls: tool_calls.length > 0 ? tool_calls : undefined,
      suggestions: suggestions.length > 0 ? suggestions : undefined,
      archived: row.archived === 1 || undefined,
      handoffType: row.handoff_type || undefined,
      targetAgentId: row.target_agent_id || undefined,
      handoffFromSessionId: row.handoff_from_session_id || undefined,
      handoffToSessionId: row.handoff_to_session_id || undefined,
      handoffId: row.handoff_id || undefined,
      importance: (row.importance as 'low' | 'normal' | 'high' | null) || undefined,
    };
  }
  
  /**
   * Convert a database row to a ChatSession with all related data
   */
  private async rowToSession(row: any): Promise<ChatSession> {
    const sessionId = row.id;
    
    // Load agent IDs
    const agentRows = await this.connection.all<{ agent_id: string }>(
      'SELECT agent_id FROM session_agents WHERE session_id = ?',
      [sessionId]
    );
    const agentIds = agentRows.map(r => r.agent_id);
    
    // Load artifacts
    const artifactRows = await this.connection.all<{ artifact_path: string }>(
      'SELECT artifact_path FROM session_artifacts WHERE session_id = ?',
      [sessionId]
    );
    const artifacts = artifactRows.map(r => r.artifact_path);
    
    // Load files
    const fileRows = await this.connection.all<{ file_path: string; is_prioritized: number }>(
      'SELECT file_path, is_prioritized FROM session_files WHERE session_id = ?',
      [sessionId]
    );
    const allowedFiles = fileRows.map(r => r.file_path);
    const prioritizedFiles = fileRows.filter(r => r.is_prioritized === 1).map(r => r.file_path);
    
    // Load tasks
    const taskRows = await this.connection.all<{ task_id: string }>(
      'SELECT task_id FROM session_tasks WHERE session_id = ?',
      [sessionId]
    );
    const tasks = taskRows.map(r => r.task_id);
    
    // Load merged from sessions
    const mergedRows = await this.connection.all<{ merged_session_id: string }>(
      'SELECT merged_session_id FROM session_merged_from WHERE session_id = ?',
      [sessionId]
    );
    const mergedFromSessionIds = mergedRows.map(r => r.merged_session_id);
    
    // Load RAG config
    const ragRow = await this.connection.get<{ config_json: string }>(
      'SELECT config_json FROM session_rag_config WHERE session_id = ?',
      [sessionId]
    );
    const ragConfig = ragRow ? JSON.parse(ragRow.config_json) : undefined;
    
    return {
      id: sessionId,
      agentIds,
      agentId: agentIds[0] || '',  // Backward compatibility
      developerId: row.developer_id,
      startedAt: row.started_at,
      lastActivityAt: row.last_activity_at,
      messageCount: row.message_count,
      title: row.title || undefined,
      artifacts,
      allowedFiles,
      prioritizedFiles: prioritizedFiles.length > 0 ? prioritizedFiles : undefined,
      tasks: tasks.length > 0 ? tasks : undefined,
      notes: row.notes || undefined,
      ragConfig,
      previousSessionId: row.previous_session_id || undefined,
      mergedFromSessionIds: mergedFromSessionIds.length > 0 ? mergedFromSessionIds : undefined,
    };
  }
  
  // ========== Notes ==========
  
  async createNote(note: Omit<Note, 'id' | 'createdAt' | 'updatedAt'>): Promise<Note> {
    const id = randomBytes(8).toString('hex');
    const now = new Date().toISOString();
    const tagsJson = note.tags ? JSON.stringify(note.tags) : null;
    
    await this.connection.run(
      `INSERT INTO notes (id, agent_id, title, content, tags_json, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [id, note.agentId, note.title || null, note.content, tagsJson, now, now]
    );
    
    return {
      id,
      agentId: note.agentId,
      title: note.title,
      content: note.content,
      tags: note.tags,
      createdAt: now,
      updatedAt: now,
    };
  }
  
  async getNote(noteId: string): Promise<Note | null> {
    const row = await this.connection.get<any>(
      'SELECT id, agent_id, title, content, tags_json, created_at, updated_at FROM notes WHERE id = ?',
      [noteId]
    );
    
    if (!row) {
      return null;
    }
    
    return {
      id: row.id,
      agentId: row.agent_id,
      title: row.title || undefined,
      content: row.content,
      tags: row.tags_json ? JSON.parse(row.tags_json) : undefined,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }
  
  async listAgentNotes(agentId: string): Promise<Note[]> {
    const rows = await this.connection.all<any>(
      'SELECT id, agent_id, title, content, tags_json, created_at, updated_at FROM notes WHERE agent_id = ? ORDER BY created_at DESC',
      [agentId]
    );
    
    return rows.map(row => ({
      id: row.id,
      agentId: row.agent_id,
      title: row.title || undefined,
      content: row.content,
      tags: row.tags_json ? JSON.parse(row.tags_json) : undefined,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    }));
  }
  
  async updateNote(noteId: string, updates: Partial<Omit<Note, 'id' | 'agentId' | 'createdAt' | 'updatedAt'>>): Promise<void> {
    const now = new Date().toISOString();
    const setParts: string[] = [];
    const params: any[] = [];
    
    if (updates.title !== undefined) {
      setParts.push('title = ?');
      params.push(updates.title || null);
    }
    
    if (updates.content !== undefined) {
      setParts.push('content = ?');
      params.push(updates.content);
    }
    
    if (updates.tags !== undefined) {
      setParts.push('tags_json = ?');
      params.push(updates.tags ? JSON.stringify(updates.tags) : null);
    }
    
    if (setParts.length === 0) {
      return; // No updates
    }
    
    setParts.push('updated_at = ?');
    params.push(now);
    
    params.push(noteId);
    
    await this.connection.run(
      `UPDATE notes SET ${setParts.join(', ')} WHERE id = ?`,
      params
    );
  }
  
  async deleteNote(noteId: string): Promise<boolean> {
    const result = await this.connection.run(
      'DELETE FROM notes WHERE id = ?',
      [noteId]
    );
    return (result.changes || 0) > 0;
  }
  
  async searchNotes(query: string, agentId?: string): Promise<Note[]> {
    // Use FTS5 for full-text search with Porter stemming and relevance ranking
    const conditions = ['notes_fts MATCH ?'];
    const params: any[] = [query];
    
    if (agentId) {
      conditions.push('notes_fts.agent_id = ?');
      params.push(agentId);
    }
    
    const sql = `
      SELECT 
        n.id,
        n.agent_id,
        n.title,
        n.content,
        n.tags_json,
        n.created_at,
        n.updated_at,
        notes_fts.rank
      FROM notes n
      INNER JOIN notes_fts ON notes_fts.note_id = n.id
      WHERE ${conditions.join(' AND ')}
      ORDER BY notes_fts.rank, n.created_at DESC
      LIMIT 100
    `;
    
    const rows = await this.connection.all<any>(sql, params);
    
    return rows.map(row => ({
      id: row.id,
      agentId: row.agent_id,
      title: row.title || undefined,
      content: row.content,
      tags: row.tags_json ? JSON.parse(row.tags_json) : undefined,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    }));
  }
}

import * as path from "node:path";
import * as fs from "node:fs/promises";
import {
  Task,
  TaskStatus,
  TaskPriority,
  TaskType,
  TaskTemplate,
  TaskStatistics,
  WorkflowStep,
  TimeLogEntry,
  TaskDelegationRecord,
  type AgentManager,
} from "@ai-team/core";
import matter from "gray-matter";
import { resolveAgentForOperation } from './utils/agent-resolution.js';

export interface TaskFilter {
  status?: TaskStatus | TaskStatus[];
  priority?: TaskPriority | TaskPriority[];
  assignedTo?: string;
  createdBy?: string;
  type?: TaskType | TaskType[];
  tags?: string[];
  parentTaskId?: string;
  includeSubtasks?: boolean;
}

export class TaskManager {
  private workspaceRoot: string;
  private tasksDir: string;
  private indexPath: string;
  private templatesPath: string;
  private index: Map<string, Task> = new Map();
  private agentManager?: AgentManager;

  constructor(workspaceRoot: string, agentManager?: AgentManager) {
    this.workspaceRoot = workspaceRoot;
    this.tasksDir = path.join(workspaceRoot, ".ai-team", "tasks");
    this.indexPath = path.join(this.tasksDir, "index.json");
    this.templatesPath = path.join(this.tasksDir, "templates.json");
    this.agentManager = agentManager;
  }

  async initialize(): Promise<void> {
    await fs.mkdir(this.tasksDir, { recursive: true });

    // Load index
    try {
      const indexData = await fs.readFile(this.indexPath, "utf-8");
      const tasks = JSON.parse(indexData) as Task[];
      this.index = new Map(tasks.map((task) => [task.id, task]));
    } catch (error) {
      // Index doesn't exist yet, start fresh
      this.index = new Map();
      await this.saveIndex();
    }

    // Create default templates if they don't exist
    try {
      await fs.access(this.templatesPath);
    } catch {
      await this.createDefaultTemplates();
    }
  }

  private async createDefaultTemplates(): Promise<void> {
    const defaultTemplates: TaskTemplate[] = [
      {
        id: "feature-implementation",
        name: "Feature Implementation",
        type: TaskType.FEATURE,
        description: "Template for implementing a new feature",
        titleTemplate: "Implement {feature_name}",
        descriptionTemplate:
          "Implement the {feature_name} feature according to specifications.\n\n## Requirements\n{requirements}\n\n## Acceptance Criteria\n{acceptance_criteria}",
        priority: TaskPriority.MEDIUM,
        estimatedHours: 8,
        requiresApproval: true,
        workflowSteps: [
          {
            title: "Design & Planning",
            autoAssign: false,
            order: 1,
          },
          {
            title: "Implementation",
            autoAssign: true,
            order: 2,
            dependencies: ["Design & Planning"],
          },
          {
            title: "Testing",
            autoAssign: true,
            order: 3,
            dependencies: ["Implementation"],
          },
          {
            title: "Code Review",
            autoAssign: false,
            order: 4,
            dependencies: ["Testing"],
          },
        ],
        tags: ["feature", "development"],
      },
      {
        id: "bug-fix",
        name: "Bug Fix",
        type: TaskType.BUG,
        description: "Template for fixing a bug",
        titleTemplate: "Fix: {bug_summary}",
        descriptionTemplate:
          "## Bug Description\n{bug_description}\n\n## Steps to Reproduce\n{steps}\n\n## Expected Behavior\n{expected}\n\n## Actual Behavior\n{actual}",
        priority: TaskPriority.HIGH,
        estimatedHours: 4,
        requiresApproval: false,
        workflowSteps: [
          {
            title: "Investigate & Reproduce",
            autoAssign: true,
            order: 1,
          },
          {
            title: "Fix Implementation",
            autoAssign: true,
            order: 2,
            dependencies: ["Investigate & Reproduce"],
          },
          {
            title: "Verification",
            autoAssign: false,
            order: 3,
            dependencies: ["Fix Implementation"],
          },
        ],
        tags: ["bug", "fix"],
      },
      {
        id: "documentation",
        name: "Documentation",
        type: TaskType.DOCUMENTATION,
        description: "Template for documentation tasks",
        titleTemplate: "Document {topic}",
        descriptionTemplate:
          "Create documentation for {topic}.\n\n## Scope\n{scope}\n\n## Target Audience\n{audience}",
        priority: TaskPriority.LOW,
        estimatedHours: 2,
        requiresApproval: false,
        tags: ["documentation"],
      },
    ];

    await fs.writeFile(
      this.templatesPath,
      JSON.stringify(defaultTemplates, null, 2),
      "utf-8"
    );
  }

  private generateTaskId(type: TaskType): string {
    const prefix = type === TaskType.FEATURE ? "FEAT" : type === TaskType.BUG ? "BUG" : "DOC";
    const timestamp = Date.now().toString(36).toUpperCase();
    const random = Math.random().toString(36).substring(2, 6).toUpperCase();
    return `${prefix}-${timestamp}-${random}`;
  }

  async createTask(
    taskData: Omit<Task, "id" | "createdAt" | "updatedAt" | "status">
  ): Promise<Task> {
    const task: Task = {
      ...taskData,
      id: this.generateTaskId(taskData.type),
      status: TaskStatus.NOT_STARTED,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    // Initialize workflow steps if provided
    if (task.workflowSteps && task.workflowSteps.length > 0) {
      task.workflowSteps = task.workflowSteps.map((step, index) => ({
        ...step,
        id: step.id || `${task.id}-step-${index + 1}`,
        status: step.status || TaskStatus.NOT_STARTED,
      }));
    }

    // Save task to markdown file
    await this.saveTask(task);

    // Update index
    this.index.set(task.id, task);
    await this.saveIndex();

    return task;
  }

  async getTask(taskId: string): Promise<Task | null> {
    // Try index first
    const cached = this.index.get(taskId);
    if (cached) {
      return cached;
    }

    // Try loading from file
    const taskPath = path.join(this.tasksDir, `${taskId}.md`);
    try {
      const content = await fs.readFile(taskPath, "utf-8");
      const task = this.markdownToTask(content);
      this.index.set(task.id, task);
      return task;
    } catch {
      return null;
    }
  }

  async listTasks(filter?: TaskFilter): Promise<Task[]> {
    let tasks = Array.from(this.index.values());

    if (!filter) {
      return tasks;
    }

    // Resolve agent queries in filter if AgentManager is available
    let resolvedAssignedTo = filter.assignedTo;
    let resolvedCreatedBy = filter.createdBy;

    if (this.agentManager) {
      if (filter.assignedTo) {
        const resolved = resolveAgentForOperation(this.agentManager, filter.assignedTo, 'filter tasks by assignedTo');
        resolvedAssignedTo = resolved.id;
      }
      if (filter.createdBy) {
        const resolved = resolveAgentForOperation(this.agentManager, filter.createdBy, 'filter tasks by createdBy');
        resolvedCreatedBy = resolved.id;
      }
    }

    // Apply filters
    if (filter.status) {
      const statuses = Array.isArray(filter.status) ? filter.status : [filter.status];
      tasks = tasks.filter((task) => statuses.includes(task.status));
    }

    if (filter.priority) {
      const priorities = Array.isArray(filter.priority) ? filter.priority : [filter.priority];
      tasks = tasks.filter((task) => priorities.includes(task.priority));
    }

    if (resolvedAssignedTo) {
      tasks = tasks.filter((task) => task.assignedTo === resolvedAssignedTo);
    }

    if (resolvedCreatedBy) {
      tasks = tasks.filter((task) => task.createdBy === resolvedCreatedBy);
    }

    if (filter.type) {
      const types = Array.isArray(filter.type) ? filter.type : [filter.type];
      tasks = tasks.filter((task) => types.includes(task.type));
    }

    if (filter.tags && filter.tags.length > 0) {
      tasks = tasks.filter(
        (task) => task.tags && filter.tags!.some((tag) => task.tags!.includes(tag))
      );
    }

    if (filter.parentTaskId !== undefined) {
      tasks = tasks.filter((task) => task.parentTaskId === filter.parentTaskId);
    }

    return tasks;
  }

  async updateTask(taskId: string, updates: Partial<Task>): Promise<Task> {
    const task = await this.getTask(taskId);
    if (!task) {
      throw new Error(`Task ${taskId} not found`);
    }

    const updatedTask: Task = {
      ...task,
      ...updates,
      id: task.id, // Preserve ID
      createdAt: task.createdAt, // Preserve creation date
      updatedAt: new Date(),
    };

    await this.saveTask(updatedTask);
    this.index.set(taskId, updatedTask);
    await this.saveIndex();

    return updatedTask;
  }

  async splitTask(
    taskId: string,
    subtasks: Array<Omit<Task, "id" | "createdAt" | "updatedAt" | "status" | "parentTaskId">>
  ): Promise<Task[]> {
    const parentTask = await this.getTask(taskId);
    if (!parentTask) {
      throw new Error(`Parent task ${taskId} not found`);
    }

    const createdSubtasks: Task[] = [];
    const subtaskIds: string[] = [];

    for (const subtaskData of subtasks) {
      const subtask = await this.createTask({
        ...subtaskData,
        parentTaskId: taskId,
      });
      createdSubtasks.push(subtask);
      subtaskIds.push(subtask.id);
    }

    // Update parent task
    await this.updateTask(taskId, {
      subtaskIds: [...(parentTask.subtaskIds || []), ...subtaskIds],
    });

    return createdSubtasks;
  }

  async delegateTask(
    taskId: string,
    fromAgentQuery: string,
    toAgentQuery: string,
    reason?: string
  ): Promise<Task> {
    // Resolve agent queries if AgentManager is available
    let fromAgentId = fromAgentQuery;
    let toAgentId = toAgentQuery;

    if (this.agentManager) {
      const resolvedFrom = resolveAgentForOperation(this.agentManager, fromAgentQuery, 'delegate task from agent');
      const resolvedTo = resolveAgentForOperation(this.agentManager, toAgentQuery, 'delegate task to agent');
      fromAgentId = resolvedFrom.id;
      toAgentId = resolvedTo.id;
    }

    const task = await this.getTask(taskId);
    if (!task) {
      throw new Error(`Task ${taskId} not found`);
    }

    const delegationRecord: TaskDelegationRecord = {
      id: `${taskId}-delegation-${Date.now()}`,
      fromAgentId,
      toAgentId,
      delegatedAt: new Date(),
      reason,
      accepted: false,
    };

    const updatedTask = await this.updateTask(taskId, {
      status: TaskStatus.DELEGATED,
      delegatedTo: toAgentId,
      delegationHistory: [...(task.delegationHistory || []), delegationRecord],
    });

    return updatedTask;
  }

  async logTime(
    taskId: string,
    agentQuery: string,
    durationMinutes: number,
    description?: string
  ): Promise<Task> {
    // Resolve agent query if AgentManager is available
    let agentId = agentQuery;
    if (this.agentManager) {
      const resolved = resolveAgentForOperation(this.agentManager, agentQuery, 'log time for task');
      agentId = resolved.id;
    }

    const task = await this.getTask(taskId);
    if (!task) {
      throw new Error(`Task ${taskId} not found`);
    }

    const timeEntry: TimeLogEntry = {
      id: `${taskId}-time-${Date.now()}`,
      taskId,
      agentId,
      startTime: new Date(Date.now() - durationMinutes * 60 * 1000),
      endTime: new Date(),
      durationMinutes,
      description,
      createdAt: new Date(),
    };

    const totalMinutes = (task.timeLog || []).reduce(
      (sum, entry) => sum + (entry.durationMinutes || 0),
      0
    );
    const actualHours = (totalMinutes + durationMinutes) / 60;

    const updatedTask = await this.updateTask(taskId, {
      timeLog: [...(task.timeLog || []), timeEntry],
      actualHours,
    });

    return updatedTask;
  }

  async getTaskHierarchy(taskId: string): Promise<Task[]> {
    const task = await this.getTask(taskId);
    if (!task) {
      throw new Error(`Task ${taskId} not found`);
    }

    const hierarchy: Task[] = [task];

    // Get all subtasks recursively
    if (task.subtaskIds && task.subtaskIds.length > 0) {
      for (const subtaskId of task.subtaskIds) {
        const subtaskHierarchy = await this.getTaskHierarchy(subtaskId);
        hierarchy.push(...subtaskHierarchy);
      }
    }

    return hierarchy;
  }

  async getStatistics(): Promise<TaskStatistics> {
    const allTasks = Array.from(this.index.values());

    const tasksByStatus = Object.values(TaskStatus).reduce(
      (acc, status) => {
        acc[status] = allTasks.filter((task) => task.status === status).length;
        return acc;
      },
      {} as Record<TaskStatus, number>
    );

    const tasksByPriority = Object.values(TaskPriority).reduce(
      (acc, priority) => {
        acc[priority] = allTasks.filter((task) => task.priority === priority).length;
        return acc;
      },
      {} as Record<TaskPriority, number>
    );

    const tasksByAgent: Record<string, number> = {};
    allTasks.forEach((task) => {
      if (task.assignedTo) {
        tasksByAgent[task.assignedTo] = (tasksByAgent[task.assignedTo] || 0) + 1;
      }
    });

    const completedTasks = allTasks.filter((task) => task.status === TaskStatus.COMPLETED);
    const totalCompletionTime = completedTasks.reduce((sum, task) => {
      if (task.completedAt && task.startedAt) {
        return sum + (task.completedAt.getTime() - task.startedAt.getTime());
      }
      return sum;
    }, 0);
    const averageCompletionTime =
      completedTasks.length > 0 ? totalCompletionTime / completedTasks.length : undefined;

    const totalEstimatedHours = allTasks.reduce(
      (sum, task) => sum + (task.estimatedHours || 0),
      0
    );
    const totalActualHours = allTasks.reduce((sum, task) => sum + (task.actualHours || 0), 0);

    return {
      totalTasks: allTasks.length,
      tasksByStatus,
      tasksByPriority,
      tasksByAgent,
      averageCompletionTime,
      totalEstimatedHours,
      totalActualHours,
    };
  }

  async getTemplates(): Promise<TaskTemplate[]> {
    try {
      const content = await fs.readFile(this.templatesPath, "utf-8");
      return JSON.parse(content) as TaskTemplate[];
    } catch {
      await this.createDefaultTemplates();
      return this.getTemplates();
    }
  }

  async createFromTemplate(
    templateId: string,
    variables: Record<string, string>,
    overrides?: Partial<Omit<Task, "id" | "createdAt" | "updatedAt" | "status">>
  ): Promise<Task> {
    const templates = await this.getTemplates();
    const template = templates.find((t) => t.id === templateId);
    if (!template) {
      throw new Error(`Template ${templateId} not found`);
    }

    // Replace variables in title and description
    let title = template.titleTemplate;
    let description = template.descriptionTemplate;
    for (const [key, value] of Object.entries(variables)) {
      title = title.replace(new RegExp(`\\{${key}\\}`, "g"), value);
      description = description.replace(new RegExp(`\\{${key}\\}`, "g"), value);
    }

    // Create workflow steps from template
    const workflowSteps: WorkflowStep[] | undefined = template.workflowSteps?.map((step, idx) => ({
      ...step,
      id: `step-${idx + 1}`,
      status: TaskStatus.NOT_STARTED,
    }));

    const taskData: Omit<Task, "id" | "createdAt" | "updatedAt" | "status"> = {
      type: template.type,
      title,
      description,
      priority: template.priority,
      estimatedHours: template.estimatedHours,
      requiresApproval: template.requiresApproval,
      tags: template.tags,
      workflowSteps,
      createdBy: "system",
      createdByType: "human",
      ...overrides,
    };

    return this.createTask(taskData);
  }

  private taskToMarkdown(task: Task): string {
    const frontmatter = {
      id: task.id,
      type: task.type,
      title: task.title,
      createdBy: task.createdBy,
      createdByType: task.createdByType,
      assignedTo: task.assignedTo,
      status: task.status,
      priority: task.priority,
      requiresApproval: task.requiresApproval,
      approved: task.approved,
      approvedBy: task.approvedBy,
      approvedAt: task.approvedAt,
      parentTaskId: task.parentTaskId,
      subtaskIds: task.subtaskIds,
      executionMode: task.executionMode,
      workflowSteps: task.workflowSteps,
      estimatedHours: task.estimatedHours,
      actualHours: task.actualHours,
      timeLog: task.timeLog,
      dueDate: task.dueDate,
      startedAt: task.startedAt,
      completedAt: task.completedAt,
      cancelledAt: task.cancelledAt,
      tags: task.tags,
      sessionId: task.sessionId,
      artifactIds: task.artifactIds,
      delegationHistory: task.delegationHistory,
      delegatedTo: task.delegatedTo,
      blockedReason: task.blockedReason,
      blockedBy: task.blockedBy,
      metadata: task.metadata,
      createdAt: task.createdAt,
      updatedAt: task.updatedAt,
    };

    const content = task.description || "";
    return matter.stringify(content, frontmatter);
  }

  private markdownToTask(content: string): Task {
    const parsed = matter(content);
    const frontmatter = parsed.data as any;

    return {
      id: frontmatter.id,
      type: frontmatter.type,
      title: frontmatter.title,
      description: parsed.content.trim() || undefined,
      createdBy: frontmatter.createdBy,
      createdByType: frontmatter.createdByType,
      assignedTo: frontmatter.assignedTo,
      status: frontmatter.status,
      priority: frontmatter.priority,
      requiresApproval: frontmatter.requiresApproval,
      approved: frontmatter.approved,
      approvedBy: frontmatter.approvedBy,
      approvedAt: frontmatter.approvedAt,
      parentTaskId: frontmatter.parentTaskId,
      subtaskIds: frontmatter.subtaskIds,
      executionMode: frontmatter.executionMode,
      workflowSteps: frontmatter.workflowSteps,
      estimatedHours: frontmatter.estimatedHours,
      actualHours: frontmatter.actualHours,
      timeLog: frontmatter.timeLog,
      dueDate: frontmatter.dueDate,
      startedAt: frontmatter.startedAt,
      completedAt: frontmatter.completedAt,
      cancelledAt: frontmatter.cancelledAt,
      tags: frontmatter.tags,
      sessionId: frontmatter.sessionId,
      artifactIds: frontmatter.artifactIds,
      delegationHistory: frontmatter.delegationHistory,
      delegatedTo: frontmatter.delegatedTo,
      blockedReason: frontmatter.blockedReason,
      blockedBy: frontmatter.blockedBy,
      metadata: frontmatter.metadata,
      createdAt: new Date(frontmatter.createdAt),
      updatedAt: new Date(frontmatter.updatedAt),
    };
  }

  private async saveTask(task: Task): Promise<void> {
    const taskPath = path.join(this.tasksDir, `${task.id}.md`);
    const content = this.taskToMarkdown(task);
    await fs.writeFile(taskPath, content, "utf-8");
  }

  private async saveIndex(): Promise<void> {
    const tasks = Array.from(this.index.values());
    await fs.writeFile(this.indexPath, JSON.stringify(tasks, null, 2), "utf-8");
  }
}

import { describe, it, expect, beforeEach } from 'vitest';
import { AgentManager } from '@ai-team/core';
import { resolveAgentForOperation, resolveAgentSafe } from './agent-resolution.js';
import { AmbiguousAgentQueryError } from '../errors.js';
import { AgentNotFoundError } from '@ai-team/core';

describe('Agent Resolution Utilities', () => {
  let agentManager: AgentManager;

  beforeEach(() => {
    // Create a mock agent manager with test agents
    agentManager = new AgentManager('/test/workspace');
    
    // Mock the agents map and resolveAgent method
    const mockAgents = [
      { id: 'john-smith', name: 'John Smith', role: 'hr-director' },
      { id: 'michael-brown', name: 'Michael Brown', role: 'cto' },
      { id: 'emily-davis', name: 'Emily Davis', role: 'developer' },
      { id: 'jordan-lee', name: 'Jordan Lee', role: 'chief-architect' },
    ];

    // Override resolveAgent to return mock data
    agentManager.resolveAgent = (query: string) => {
      const q = query.toLowerCase().trim();
      
      // Exact ID match
      const exactId = mockAgents.find(a => a.id === q);
      if (exactId) return [exactId];
      
      // Exact role match
      const exactRole = mockAgents.filter(a => a.role.toLowerCase() === q);
      if (exactRole.length > 0) return exactRole;
      
      // Exact name match
      const exactName = mockAgents.filter(a => a.name.toLowerCase() === q);
      if (exactName.length > 0) return exactName;
      
      // Partial name match
      const partialName = mockAgents.filter(a => a.name.toLowerCase().includes(q));
      if (partialName.length > 0) return partialName;
      
      return [];
    };

    agentManager.getAllAgents = () => mockAgents as any;
  });

  describe('resolveAgentForOperation', () => {
    it('should resolve exact agent ID', () => {
      const result = resolveAgentForOperation(agentManager, 'john-smith', 'test operation');
      expect(result).toEqual({ id: 'john-smith', name: 'John Smith', role: 'hr-director' });
    });

    it('should resolve agent by role', () => {
      const result = resolveAgentForOperation(agentManager, 'cto', 'test operation');
      expect(result).toEqual({ id: 'michael-brown', name: 'Michael Brown', role: 'cto' });
    });

    it('should resolve agent by full name', () => {
      const result = resolveAgentForOperation(agentManager, 'Emily Davis', 'test operation');
      expect(result).toEqual({ id: 'emily-davis', name: 'Emily Davis', role: 'developer' });
    });

    it('should resolve agent by partial name', () => {
      const result = resolveAgentForOperation(agentManager, 'Michael', 'test operation');
      expect(result).toEqual({ id: 'michael-brown', name: 'Michael Brown', role: 'cto' });
    });

    it('should throw AgentNotFoundError when no match found', () => {
      expect(() => {
        resolveAgentForOperation(agentManager, 'nonexistent', 'test operation');
      }).toThrow(AgentNotFoundError);
    });

    it('should throw AmbiguousAgentQueryError when multiple matches found', () => {
      // Mock multiple matches
      agentManager.resolveAgent = () => [
        { id: 'emily-davis', name: 'Emily Davis', role: 'developer' } as any,
        { id: 'alex-jones', name: 'Alex Jones', role: 'developer' } as any,
      ];

      expect(() => {
        resolveAgentForOperation(agentManager, 'developer', 'test operation');
      }).toThrow(AmbiguousAgentQueryError);
    });

    it('should include operation context in error message', () => {
      try {
        resolveAgentForOperation(agentManager, 'nonexistent', 'list sessions');
        expect.fail('Should have thrown error');
      } catch (error: any) {
        expect(error.message).toContain('list sessions');
        expect(error.message).toContain('nonexistent');
      }
    });
  });

  describe('resolveAgentSafe', () => {
    it('should resolve agent without throwing', () => {
      const result = resolveAgentSafe(agentManager, 'cto');
      expect(result).toEqual({ id: 'michael-brown', name: 'Michael Brown', role: 'cto' });
    });

    it('should return null when no match found', () => {
      const result = resolveAgentSafe(agentManager, 'nonexistent');
      expect(result).toBeNull();
    });

    it('should return null when multiple matches found', () => {
      agentManager.resolveAgent = () => [
        { id: 'emily-davis', name: 'Emily Davis', role: 'developer' } as any,
        { id: 'alex-jones', name: 'Alex Jones', role: 'developer' } as any,
      ];

      const result = resolveAgentSafe(agentManager, 'developer');
      expect(result).toBeNull();
    });

    it('should return null when agentManager is undefined', () => {
      const result = resolveAgentSafe(undefined, 'cto');
      expect(result).toBeNull();
    });

    it('should handle exact ID match', () => {
      const result = resolveAgentSafe(agentManager, 'john-smith');
      expect(result).toEqual({ id: 'john-smith', name: 'John Smith', role: 'hr-director' });
    });
  });

  describe('AmbiguousAgentQueryError', () => {
    it('should format error message with match details', () => {
      const matches = [
        { id: 'emily-davis', name: 'Emily Davis', role: 'developer' },
        { id: 'alex-jones', name: 'Alex Jones', role: 'developer' },
      ];

      const error = new AmbiguousAgentQueryError('developer', matches);
      
      expect(error.query).toBe('developer');
      expect(error.matches).toEqual(matches);
      expect(error.message).toContain('developer');
      expect(error.message).toContain('Emily Davis');
      expect(error.message).toContain('Alex Jones');
      expect(error.message).toContain('Please be more specific');
    });
  });
});

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate, useMatch } from 'react-router-dom';
import { useTeam, API_BASE } from '../context/TeamContext';
import { ChatMessage } from '../types';
import { Avatar } from './Avatar';
import { MarkdownMessage } from './MarkdownMessage';
import { ContextPanel } from './ContextPanel';
import { AgentBriefingBadge } from './AgentBriefingBadge';
import { RelativeTime } from './RelativeTime';
import { SessionGraphLoader } from './SessionGraph';
import { getAgentColor } from '../utils/color';
import './ChatPanel.css';

/** Match patterns for URL-driven session + graph routing */
const SESSION_ROUTE  = '/chat/:agentId/session/:sessionId';
const GRAPH_ROUTE   = '/chat/:agentId/session/:sessionId/thread';

interface QuestionChoice {
  name: string;
  value: string;
}

interface InputQuestionRequest {
  message: string;
}

interface ConfirmQuestionRequest {
  message: string;
  default?: boolean;
}

interface SelectQuestionRequest {
  message: string;
  choices: QuestionChoice[];
}

interface PasswordQuestionRequest {
  message: string;
}

interface ChecklistQuestionRequest {
  message: string;
  choices: QuestionChoice[];
}

type PendingQuestion =
  | {
      kind: 'input';
      message: string;
    }
  | {
      kind: 'password';
      message: string;
    }
  | {
      kind: 'confirm';
      message: string;
      defaultValue: boolean;
    }
  | {
      kind: 'select';
      message: string;
      choices: QuestionChoice[];
    }
  | {
      kind: 'checklist';
      message: string;
      choices: QuestionChoice[];
    };

interface MessageDividerProps {
  messageIndex: number;
  onSummarize: (toIndex: number) => void;
  onSplitSession: (atIndex: number) => void;
}

function MessageDivider({ messageIndex, onSummarize, onSplitSession }: MessageDividerProps) {
  const [isHovered, setIsHovered] = useState(false);

  return (
    <div 
      className={`message-divider ${isHovered ? 'message-divider-hovered' : ''}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div className="message-divider-line" />
      {isHovered && (
        <div className="message-divider-actions">
          <button
            onClick={() => onSummarize(messageIndex)}
            className="btn-divider-action"
            title="Summarize conversation up to here and create a brief"
          >
            📝 Summarize
          </button>
          <button
            onClick={() => onSplitSession(messageIndex)}
            className="btn-divider-action"
            title="Start a new session from this point"
          >
            ✂️ Split Session
          </button>
        </div>
      )}
    </div>
  );
}

export function ChatPanel() {
  const { agentId } = useParams<{ agentId: string }>();
  const navigate = useNavigate();
  const { agents, client, developer } = useTeam();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [sending, setSending] = useState(false);
  const [streaming, setStreaming] = useState(false);
  const [loading, setLoading] = useState(true);
  const [currentAgentId, setCurrentAgentId] = useState(agentId || '');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [editContent, setEditContent] = useState('');
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [artifactsInContext, setArtifactsInContext] = useState<string[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [recognition, setRecognition] = useState<any>(null);
  const [pendingQuestion, setPendingQuestion] = useState<PendingQuestion | null>(null);
  const [pendingInputAnswer, setPendingInputAnswer] = useState('');
  const [pendingPasswordAnswer, setPendingPasswordAnswer] = useState('');
  const [pendingConfirmAnswer, setPendingConfirmAnswer] = useState(false);
  const [pendingSelectAnswer, setPendingSelectAnswer] = useState('');
  const [pendingChecklistAnswer, setPendingChecklistAnswer] = useState<string[]>([]);
  const [scrollToHandoffId, setScrollToHandoffId] = useState<string | null>(null);
  const [sessionRefreshTrigger, setSessionRefreshTrigger] = useState(0);
  // True when a greeting is showing but no session has been persisted yet
  const [isEphemeral, setIsEphemeral] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [isUserScrolledUp, setIsUserScrolledUp] = useState(false);
  const lastScrollTopRef = useRef<number>(0);
  const abortControllerRef = useRef<AbortController | null>(null);
  const pendingQuestionResolveRef = useRef<((value: unknown) => void) | null>(null);
  const pendingQuestionRejectRef = useRef<((reason?: unknown) => void) | null>(null);
  // Mutable ref tracking current assistant message slot — survives handoff resets
  const assistantIndexRef = useRef<number>(-1);
  // When handleSend lazy-creates a session and navigates to its URL, the URL change would
  // normally re-trigger loadSession and wipe the in-progress stream. We store the
  // just-navigated session ID here so loadSession can skip that one reload.
  const skipNextSessionLoadRef = useRef<string | null>(null);

  // Detect when we are on the graph subroute or session subroute
  const graphRouteMatch   = useMatch(GRAPH_ROUTE);
  const sessionRouteMatch = useMatch(SESSION_ROUTE);
  // sessionId from URL — present on both session and graph routes
  const urlSessionId  = graphRouteMatch?.params?.sessionId ?? sessionRouteMatch?.params?.sessionId ?? null;
  const graphSessionId = graphRouteMatch?.params?.sessionId ?? null;

  const agent = agents.find((a) => a.id === currentAgentId);

  // Auto-resize textarea based on content
  const autoResizeTextarea = () => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${textarea.scrollHeight}px`;
    }
  };

  // Helper: check if message is from human (handles both old 'human' format and new isHuman flag)
  const isHumanMessage = (message: ChatMessage): boolean => {
    return message.isHuman === true || message.from === 'human';
  };

  // Helper: check if message is a handoff (has handoffType or legacy 'to' field or HANDOFF pattern)
  const isHandoffMessage = (message: ChatMessage): boolean => {
    return !!(
      message.handoffType ||
      message.to ||
      /HANDOFF:\s*[a-z0-9-]+\s*\|/i.test(message.content)
    );
  };

  // Helper: check if message is an agent-to-agent briefing
  const isAgentBriefing = (message: ChatMessage): boolean => {
    return message.handoffType === 'agent-briefing';
  };

  // Helper: get target agent name from briefing message
  const getTargetAgentName = (message: ChatMessage): string | null => {
    if (!message.targetAgentId) return null;
    const targetAgent = agents.find((a) => a.id === message.targetAgentId);
    return targetAgent ? targetAgent.name : message.targetAgentId;
  };

  // Helper: format developer ID to display name (e.g., "clemens-meier" -> "Clemens Meier")
  const formatDeveloperName = (developerId: string): string => {
    if (developerId === 'human') return 'You'; // Backward compat for old messages
    return developerId
      .split('-')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  };

  // Helper: extract target agent ID from handoff message
  const extractHandoffTarget = (content: string): string | null => {
    const match = content.match(/HANDOFF:\s*([a-z0-9-]+)\s*\|/i);
    return match ? match[1] : null;
  };

  // Resolve which agent to show a "Go to" button for, covering two cases:
  //   1. Message has a HANDOFF directive: target = message.to or extracted from content
  //   2. Message is an agent-briefing FROM a different agent: target = message.from (the sender)
  // Also returns the existing session ID if known, so we navigate there directly.
  const resolveNavigateAgent = (message: ChatMessage): { agent: (typeof agents)[0]; sessionId: string | null } | null => {
    const currentAgent = currentAgentId || agentId;
    // Case 1: outgoing handoff directive
    if (isHandoffMessage(message)) {
      const targetId = message.to || extractHandoffTarget(message.content);
      if (targetId && targetId !== currentAgent) {
        const a = agents.find((ag) => ag.id === targetId);
        if (a) return { agent: a, sessionId: message.handoffToSessionId ?? null };
      }
    }
    // Case 2: incoming agent-briefing authored by a different agent
    if (message.handoffType === 'agent-briefing' && message.from && message.from !== currentAgent) {
      const a = agents.find((ag) => ag.id === message.from);
      if (a) {
        // handoffFromSessionId = the session the briefing came FROM (the other agent's session)
        // handoffToSessionId   = the session the briefing was directed TO (current session)
        // We want to navigate to the OTHER agent's session → handoffFromSessionId
        return { agent: a, sessionId: message.handoffFromSessionId ?? null };
      }
    }
    return null;
  };

  // Handle handoff link click
  const handleHandoffClick = async (targetAgentId: string, existingSessionId?: string | null) => {
    // If the handoff session already exists, navigate directly — do NOT create a new one
    if (existingSessionId) {
      navigate(`/chat/${targetAgentId}/session/${existingSessionId}`);
      return;
    }

    if (!currentSessionId) {
      console.error('Cannot handoff: no current session');
      return;
    }

    try {
      // No existing session found — create a new handoff session
      const response = await fetch(`${API_BASE}/api/sessions/handoff`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          toAgentId: targetAgentId,
          developerId: developer?.id || 'clemens-meier',
          previousSessionId: currentSessionId,
          transferArtifacts: true,
          transferAllowedFiles: true,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to create handoff session');
      }

      const newSession = await response.json();
      console.log('Created handoff session:', newSession.id);

      // Load messages from the new session
      const messagesResponse = await fetch(`${API_BASE}/api/sessions/${newSession.id}/messages?includeMessages=true`);
      if (messagesResponse.ok) {
        const sessionWithMessages = await messagesResponse.json();
        setMessages(sessionWithMessages.messages || []);
        setCurrentSessionId(newSession.id);
        setCurrentAgentId(targetAgentId);
        setArtifactsInContext(sessionWithMessages.artifacts || newSession.artifacts || []);
      }

      // Notify parent to switch agent
      // Navigate to the target agent's chat
      navigate(`/chat/${targetAgentId}`);
    } catch (error) {
      console.error('Failed to handle handoff:', error);
    }
  };

  // Open the session thread graph as a subroute
  const handleOpenSessionGraph = (sessionId: string) => {
    const currentAgent = agentId || currentAgentId;
    if (currentAgent) {
      navigate(`/chat/${currentAgent}/session/${sessionId}/thread`);
    }
  };

  // Called when a node is clicked inside the session graph
  const handleSelectSessionFromGraph = (targetSessionId: string, targetAgentId: string, handoffId?: string) => {
    if (handoffId) setScrollToHandoffId(handoffId);
    // Navigate to that session using the correct agent, closes graph view
    const agent = targetAgentId || agentId || currentAgentId;
    if (agent) navigate(`/chat/${agent}/session/${targetSessionId}`);
  };

  /** Fetch the agent introduction and display it as an ephemeral (not-yet-persisted) greeting */
  const loadGreeting = async (targetAgentId: string, cancelled?: { value: boolean }) => {
    try {
      const developerName = encodeURIComponent(developer?.name || 'Developer');
      const res = await fetch(
        `${API_BASE}/api/agents/${targetAgentId}/introduction?developerName=${developerName}`,
      );
      if (cancelled?.value) return;
      if (res.ok) {
        const data = await res.json();
        const greetingMessage: ChatMessage = {
          from: data.agentId ?? targetAgentId,
          content: data.content ?? '',
          timestamp: data.timestamp ?? new Date().toISOString(),
        };
        setMessages([greetingMessage]);
        setIsEphemeral(true);
      } else {
        // Greeting endpoint unavailable — just show an empty chat
        setMessages([]);
        setIsEphemeral(false);
      }
    } catch {
      setMessages([]);
      setIsEphemeral(false);
    }
  };

  // Scroll to a handoff message identified by handoffId after messages have loaded
  useEffect(() => {
    if (!scrollToHandoffId) return;
    const timer = setTimeout(() => {
      const el = messagesContainerRef.current?.querySelector<HTMLElement>(
        `[data-handoff-id="${scrollToHandoffId}"]`,
      );
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        el.classList.add('handoff-highlight');
        setTimeout(() => el.classList.remove('handoff-highlight'), 1800);
        setScrollToHandoffId(null);
      }
    }, 120); // brief delay for React to flush messages to the DOM
    return () => clearTimeout(timer);
  }, [scrollToHandoffId, messages]);

  // Load chat history — driven by the agentId and URL session ID
  useEffect(() => {
    if (!agentId) return;
    
    let cancelled = false;
    
    const loadSession = async () => {
      // Skip reload if this URL change was caused by our own lazy session creation
      if (urlSessionId && urlSessionId === skipNextSessionLoadRef.current) {
        skipNextSessionLoadRef.current = null;
        setLoading(false);
        return;
      }

      setLoading(true);
      try {
        // If URL already specifies a session, load that one directly
        const targetUrl = urlSessionId
          ? `${API_BASE}/api/sessions/${urlSessionId}?includeMessages=true`
          : `${API_BASE}/api/sessions/${agentId}/latest?includeMessages=true`;

        const sessionResponse = await fetch(targetUrl);
        
        if (sessionResponse.ok) {
          const sessionWithMessages = await sessionResponse.json();
          const sessionId = sessionWithMessages.id;
          const sessionArtifacts = sessionWithMessages.artifacts || [];
          const sessionMessages = sessionWithMessages.messages || [];
          console.log('Loaded session:', sessionId);
          
          if (!cancelled) {
            setCurrentSessionId(sessionId);
            setMessages(sessionMessages);
            setArtifactsInContext(sessionArtifacts);
            setCurrentAgentId(agentId);

            // Reflect the session ID in the URL (replace so back button stays clean)
            if (!urlSessionId && sessionId) {
              navigate(`/chat/${agentId}/session/${sessionId}`, { replace: true });
            }
          }
        } else {
          // No session exists yet — show the agent greeting without creating a session
          console.log('No existing session found for agent:', agentId);
          if (!cancelled) {
            setCurrentSessionId(null);
            setArtifactsInContext([]);
            setCurrentAgentId(agentId);
          }
          // loadGreeting has its own cancel guard via the closure flag
          const cancelObj = { value: false };
          if (!cancelled) await loadGreeting(agentId, cancelObj);
          if (cancelled) cancelObj.value = true;
        }
      } catch (error) {
        console.error('Failed to load session:', error);
        if (!cancelled) {
          setCurrentSessionId(null);
          setArtifactsInContext([]);
          setCurrentAgentId(agentId);
          await loadGreeting(agentId);
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };
    
    loadSession();
    
    return () => {
      cancelled = true;
    };
  }, [agentId, urlSessionId]);

  // Helper: Check if scroll position is at bottom
  const isAtBottom = () => {
    const container = messagesContainerRef.current;
    if (!container) return true;
    const { scrollTop, scrollHeight, clientHeight } = container;
    // Consider "at bottom" if within 5 pixels
    return scrollHeight - scrollTop - clientHeight < 5;
  };

  // Handle scroll events to detect user scrolling
  const handleScroll = () => {
    const container = messagesContainerRef.current;
    if (!container) return;

    const currentScrollTop = container.scrollTop;
    const previousScrollTop = lastScrollTopRef.current;

    // If user scrolled up (even by 1 pixel), stop auto-scroll
    if (currentScrollTop < previousScrollTop) {
      setIsUserScrolledUp(true);
    }
    // If user scrolled to the very bottom, resume auto-scroll
    else if (isAtBottom()) {
      setIsUserScrolledUp(false);
    }

    lastScrollTopRef.current = currentScrollTop;
  };

  useEffect(() => {
    // Only auto-scroll if user hasn't scrolled up
    if (!isUserScrolledUp) {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  const rejectAndClearPendingQuestion = (reason: Error) => {
    if (pendingQuestionRejectRef.current) {
      pendingQuestionRejectRef.current(reason);
    }
    clearPendingQuestion();
  };

  const handleInterrupt = () => {
    rejectAndClearPendingQuestion(new Error('Question interrupted by user.'));

    // Abort streaming (the HTTP client forwards this to websocket cancel)
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }
    setSending(false);
    setStreaming(false);
  };

  useEffect(() => {
    return () => {
      rejectAndClearPendingQuestion(new Error('Question interrupted: chat panel unmounted.'));
    };
  }, []);

  const clearPendingQuestion = () => {
    pendingQuestionResolveRef.current = null;
    pendingQuestionRejectRef.current = null;
    setPendingQuestion(null);
    setPendingInputAnswer('');
    setPendingPasswordAnswer('');
    setPendingConfirmAnswer(false);
    setPendingSelectAnswer('');
    setPendingChecklistAnswer([]);
  };

  const beginPendingQuestion = <T,>(question: PendingQuestion): Promise<T> => {
    if (pendingQuestionRejectRef.current) {
      pendingQuestionRejectRef.current(new Error('Previous question was replaced before submission.'));
    }

    if (question.kind === 'input') {
      setPendingInputAnswer('');
    } else if (question.kind === 'password') {
      setPendingPasswordAnswer('');
    } else if (question.kind === 'confirm') {
      setPendingConfirmAnswer(question.defaultValue);
    } else if (question.kind === 'select') {
      setPendingSelectAnswer(question.choices[0]?.value ?? '');
    } else if (question.kind === 'checklist') {
      setPendingChecklistAnswer([]);
    }

    setPendingQuestion(question);

    return new Promise<T>((resolve, reject) => {
      pendingQuestionResolveRef.current = (value: unknown) => resolve(value as T);
      pendingQuestionRejectRef.current = reject;
    });
  };

  const togglePendingChecklistValue = (choiceValue: string, checked: boolean) => {
    setPendingChecklistAnswer((prev) =>
      checked ? [...prev, choiceValue] : prev.filter((value) => value !== choiceValue)
    );
  };

  const handlePendingQuestionSubmit = (e: { preventDefault: () => void }) => {
    e.preventDefault();

    if (!pendingQuestion || !pendingQuestionResolveRef.current) {
      return;
    }

    if (pendingQuestion.kind === 'input') {
      pendingQuestionResolveRef.current(pendingInputAnswer);
    } else if (pendingQuestion.kind === 'password') {
      pendingQuestionResolveRef.current(pendingPasswordAnswer);
    } else if (pendingQuestion.kind === 'confirm') {
      pendingQuestionResolveRef.current(pendingConfirmAnswer);
    } else if (pendingQuestion.kind === 'select') {
      pendingQuestionResolveRef.current(pendingSelectAnswer);
    } else if (pendingQuestion.kind === 'checklist') {
      pendingQuestionResolveRef.current(pendingChecklistAnswer);
    }

    clearPendingQuestion();
  };

  const askInputQuestion = async (request: InputQuestionRequest): Promise<string> => {
    return beginPendingQuestion<string>({ kind: 'input', message: request.message });
  };

  const askConfirmQuestion = async (request: ConfirmQuestionRequest): Promise<boolean> => {
    return beginPendingQuestion<boolean>({ kind: 'confirm', message: request.message, defaultValue: request.default ?? false });
  };

  const askSelectQuestion = async (request: SelectQuestionRequest): Promise<string> => {
    return beginPendingQuestion<string>({ kind: 'select', message: request.message, choices: request.choices });
  };

  const askPasswordQuestion = async (request: PasswordQuestionRequest): Promise<string> => {
    return beginPendingQuestion<string>({ kind: 'password', message: request.message });
  };

  const askChecklistQuestion = async (request: ChecklistQuestionRequest): Promise<string[]> => {
    return beginPendingQuestion<string[]>({ kind: 'checklist', message: request.message, choices: request.choices });
  };

  const handleSend = async () => {
    if (!input.trim() || sending) return;

    const messageContent = input.trim();
    // Capture the ephemeral greeting now, before state changes clear it
    const pendingIntroductionContent = isEphemeral ? messages[0]?.content : undefined;

    const userMessage: ChatMessage = {
      from: 'human',
      content: messageContent,
      timestamp: new Date().toISOString(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput('');
    // Reset textarea height
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }
    // Reset scroll lock when user sends a message
    setIsUserScrolledUp(false);
    setSending(true);
    setStreaming(true);
    abortControllerRef.current = new AbortController();

    // Create a placeholder for the streaming response.
    // assistantIndexRef tracks the current slot dynamically so it survives handoff resets.
    assistantIndexRef.current = messages.length + 1;
    const assistantMessage: ChatMessage = {
      from: currentAgentId || 'agent',
      content: '',
      timestamp: new Date().toISOString(),
    };
    setMessages((prev) => [...prev, assistantMessage]);

    try {
      // Create session if it doesn't exist (lazy session creation)
      let sessionId = currentSessionId;
      if (!sessionId) {
        console.log('Creating new session for first message...');
        const createResponse = await fetch(`${API_BASE}/api/sessions`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            agentId: currentAgentId,
            developerId: developer?.id || 'clemens-meier',
          }),
        });
        
        if (!createResponse.ok) {
          throw new Error('Failed to create new session');
        }
        
        const newSession = await createResponse.json();
        sessionId = newSession.id;
        setCurrentSessionId(sessionId);
        setIsEphemeral(false);
        setSessionRefreshTrigger((t) => t + 1);
        // Mark this session ID so loadSession skips the redundant reload
        skipNextSessionLoadRef.current = sessionId;
        navigate(`/chat/${currentAgentId}/session/${sessionId}`, { replace: true });
        console.log('Created new session:', sessionId);
      }
      const abortSignal = abortControllerRef.current?.signal;
      if (!abortSignal) {
        throw new Error('Chat request was interrupted before it started. Please try again.');
      }

      const stream = client.stream({
        command: 'chat',
        payload: {
          employeeId: currentAgentId,
          options: {
            message: messageContent,
            sessionId: sessionId ?? undefined,
            ...(pendingIntroductionContent ? { pendingIntroduction: pendingIntroductionContent } : {}),
          },
        },
      }, {
        signal: abortSignal,
        questionInput: askInputQuestion,
        questionConfirm: askConfirmQuestion,
        questionSelect: askSelectQuestion,
        questionPassword: askPasswordQuestion,
        questionChecklist: askChecklistQuestion,
      });

      let accumulator = '';
      let handoffDetected = false;
      
      for await (const event of stream) {
        if (event.kind === 'handoff') {
          // Agent handoff: server has already created the session and saved the briefing.
          // Use toSessionId from the event to navigate directly — no need to create a new session.
          const fromAgentId = (event as any).fromAgentId;
          const toAgentId = (event as any).toAgentId;
          const toSessionId: string | undefined = (event as any).toSessionId;

          if (toAgentId) {
            handoffDetected = true;
            console.log(`Handoff detected: ${fromAgentId} → ${toAgentId} (session: ${toSessionId ?? 'unknown'})`);

            try {
              let targetSessionId = toSessionId ?? null;

              if (!targetSessionId) {
                // Legacy fallback: server didn't supply toSessionId, create via API
                const handoffResponse = await fetch(`${API_BASE}/api/sessions/handoff`, {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({
                    toAgentId,
                    developerId: developer?.id || 'clemens-meier',
                    previousSessionId: currentSessionId,
                    transferArtifacts: true,
                    transferAllowedFiles: true,
                  }),
                });
                if (!handoffResponse.ok) throw new Error('Failed to create handoff session');
                const newSession = await handoffResponse.json();
                targetSessionId = newSession.id;
                console.log('Created handoff session (fallback):', targetSessionId);
              }

              // Load messages from the already-existing session (includes the briefing message)
              const messagesResponse = await fetch(`${API_BASE}/api/sessions/${targetSessionId}?includeMessages=true`);
              if (messagesResponse.ok) {
                const sessionWithMessages = await messagesResponse.json();
                const existingMessages: ChatMessage[] = sessionWithMessages.messages || [];
                // Add placeholder for the incoming agent's streaming response
                const newAssistantPlaceholder: ChatMessage = {
                  from: toAgentId,
                  content: '',
                  timestamp: new Date().toISOString(),
                };
                assistantIndexRef.current = existingMessages.length;
                setMessages([...existingMessages, newAssistantPlaceholder]);
                setCurrentSessionId(targetSessionId);
                setCurrentAgentId(toAgentId);
                setArtifactsInContext(sessionWithMessages.artifacts || []);
                setSessionRefreshTrigger((t) => t + 1);
                // Navigate to the real session URL immediately — no F5 needed
                skipNextSessionLoadRef.current = targetSessionId;
                navigate(`/chat/${toAgentId}/session/${targetSessionId}`, { replace: true });
                // Scroll to the agent-briefing message
                const briefing = existingMessages.find(
                  (m) => m.handoffType === 'agent-briefing' && m.handoffId,
                );
                if (briefing?.handoffId) setScrollToHandoffId(briefing.handoffId);
              }
            } catch (error) {
              console.error('Failed to set up handoff session:', error);
            }

            // Reset accumulator for the new agent's response
            accumulator = '';
          }
        } else if (event.kind === 'token') {
          // Append token to accumulated text
          accumulator += event.text;
          setMessages((prev) => {
            const updated = [...prev];
            const idx = assistantIndexRef.current;
            if (idx >= 0 && idx < updated.length) {
              updated[idx] = {
                ...updated[idx],
                // Do NOT overwrite `from` — the placeholder already has the correct agent ID.
                // Setting it from `currentAgentId` would use a stale closure value after handoff.
                content: accumulator,
              };
            }
            return updated;
          });
        } else if (event.kind === 'status') {
          // Could show status like "thinking..." in UI
          console.log('Status:', event);
        } else if (event.kind === 'tool') {
          // Could show tool usage in UI
          console.log('Tool:', event);
        } else if (event.kind === 'error') {
          throw new Error(event.message || 'Chat error');
        }
      }

      // If no tokens were received and no handoff, show a message
      if (!accumulator && !handoffDetected) {
        setMessages((prev) => {
          const updated = [...prev];
          const idx = assistantIndexRef.current;
          if (idx >= 0 && idx < updated.length) {
            updated[idx] = {
              ...updated[idx],
              content: 'No response received.',
            };
          }
          return updated;
        });
      }
    } catch (error) {
      console.error('Failed to send message:', error);
      const rawMessage = error instanceof Error ? error.message : 'Failed to send message';
      const normalizedMessage = /question timeout|did not receive a response in time/i.test(rawMessage)
        ? 'The request could not be completed. Please try again.'
        : rawMessage;
      const errorMessage: ChatMessage = {
        from: currentAgentId || 'agent',
        content: `Error: ${normalizedMessage}`,
        timestamp: new Date().toISOString(),
      };
      setMessages((prev) => {
        const updated = [...prev];
        const idx = assistantIndexRef.current;
        if (idx >= 0 && idx < updated.length) {
          updated[idx] = errorMessage;
        } else {
          updated.push(errorMessage);
        }
        return updated;
      });
    } finally {
      setSending(false);
      setStreaming(false);
      abortControllerRef.current = null;
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const startVoiceRecording = () => {
    // Check if browser supports speech recognition
    const SpeechRecognition = (globalThis as any).SpeechRecognition || (globalThis as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert('Speech recognition is not supported in your browser. Please try Chrome or Edge.');
      return;
    }

    const recognitionInstance = new SpeechRecognition();
    recognitionInstance.continuous = false;
    recognitionInstance.interimResults = false;
    recognitionInstance.lang = 'en-US';

    recognitionInstance.onstart = () => {
      setIsRecording(true);
    };

    recognitionInstance.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput((prev) => prev ? `${prev} ${transcript}` : transcript);
    };

    recognitionInstance.onerror = (event: any) => {
      console.error('Speech recognition error:', event.error);
      setIsRecording(false);
      if (event.error === 'not-allowed') {
        alert('Microphone access denied. Please allow microphone access in your browser settings.');
      }
    };

    recognitionInstance.onend = () => {
      setIsRecording(false);
    };

    setRecognition(recognitionInstance);
    recognitionInstance.start();
  };

  // Message operations
  const handleEditMessage = async (index: number) => {
    if (editingIndex === index) {
      // Save the edit
      try {
        const response = await fetch(`${API_BASE}/api/chat/${currentAgentId}/messages/${index}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ content: editContent }),
        });

        if (response.ok) {
          setMessages((prev) => {
            const updated = [...prev];
            updated[index] = { ...updated[index], content: editContent };
            return updated;
          });
          setEditingIndex(null);
          setEditContent('');
        }
      } catch (error) {
        console.error('Failed to edit message:', error);
      }
    } else {
      // Start editing
      setEditingIndex(index);
      setEditContent(messages[index].content);
    }
  };

  const handleCancelEdit = () => {
    setEditingIndex(null);
    setEditContent('');
  };

  const handleDeleteMessage = async (index: number) => {
    if (!confirm('Delete this message?')) return;

    try {
      const response = await fetch(`${API_BASE}/api/chat/${currentAgentId}/messages/${index}`, {
        method: 'DELETE',
      });

      if (response.ok) {
        setMessages((prev) => prev.filter((_, i) => i !== index));
      }
    } catch (error) {
      console.error('Failed to delete message:', error);
    }
  };

  const handleCopyMessage = (content: string) => {
    navigator.clipboard.writeText(content).then(
      () => console.log('Message copied to clipboard'),
      (err) => console.error('Failed to copy message:', err)
    );
  };

  const handleToggleArchive = async (index: number, currentlyArchived: boolean) => {
    try {
      const endpoint = currentlyArchived ? 'unarchive' : 'archive';
      const response = await fetch(
        `${API_BASE}/api/chat/${currentAgentId}/messages/${index}/${endpoint}`,
        { method: 'PATCH' }
      );

      if (response.ok) {
        setMessages((prev) => {
          const updated = [...prev];
          updated[index] = { ...updated[index], archived: !currentlyArchived };
          return updated;
        });
      }
    } catch (error) {
      console.error('Failed to toggle archive:', error);
    }
  };

  // Session operations
  const handleSummarize = async (toIndex: number) => {
    try {
      if (!currentSessionId) {
        alert('No active session. Please start a chat first.');
        return;
      }

      const title = prompt('Enter a title for this brief:');
      if (!title) return;

      // Create a summary from the message content
      const messagesToSummarize = messages.slice(0, toIndex + 1);
      const summary = messagesToSummarize
        .map(
          (m) =>
            `**${isHumanMessage(m) ? formatDeveloperName(m.from) : m.from}** (${new Date(m.timestamp).toLocaleString()}):\n${m.content}`
        )
        .join('\n\n---\n\n');

      const response = await fetch(`${API_BASE}/api/sessions/${currentSessionId}/summarize`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          fromIndex: 0,
          toIndex,
          title,
          summary,
          developerId: developer?.id || 'clemens-meier',
        }),
      });

      if (!response.ok) {
        throw new Error(`Summarize failed: ${response.statusText}`);
      }

      const artifact = await response.json();
      console.log('Created artifact:', artifact);
      alert(`Brief "${title}" created successfully!`);

      // Reload messages to show updated state
      // TODO: Refresh artifact list in ContextPanel
    } catch (error) {
      console.error('Failed to create summary:', error);
      alert('Failed to create brief. Check the console for details.');
    }
  };

  const handleSplitSession = async (atIndex: number) => {
    try {
      if (!currentSessionId) {
        alert('No active session. Please start a chat first.');
        return;
      }

      const confirmed = confirm(
        `Split session at message ${atIndex + 1}? This will create a new session with messages from that point forward.`
      );
      if (!confirmed) return;

      const response = await fetch(`${API_BASE}/api/sessions/${currentSessionId}/split`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          atIndex,
          developerId: developer?.id || 'clemens-meier',
        }),
      });

      if (!response.ok) {
        throw new Error(`Split failed: ${response.statusText}`);
      }

      const newSession = await response.json();
      console.log('Created new session:', newSession);

      // Update current session ID and reload messages from new session
      setCurrentSessionId(newSession.id);
      setSessionRefreshTrigger((t) => t + 1);
      handleSwitchSession(newSession.id);
      alert(`Session split successfully! New session: ${newSession.id}`);
    } catch (error) {
      console.error('Failed to split session:', error);
      alert('Failed to split session. Check the console for details.');
    }
  };

  const handleToggleArtifact = async (artifactId: string) => {
    const updatedArtifacts = artifactsInContext.includes(artifactId)
      ? artifactsInContext.filter((id) => id !== artifactId)
      : [...artifactsInContext, artifactId];

    // Update local state
    setArtifactsInContext(updatedArtifacts);

    // Persist to session if we have an active session
    if (currentSessionId) {
      try {
        const response = await fetch(`${API_BASE}/api/sessions/${currentSessionId}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ artifacts: updatedArtifacts }),
        });

        if (!response.ok) {
          throw new Error(`Failed to update session: ${response.statusText}`);
        }

        console.log('Session artifacts updated:', updatedArtifacts);
      } catch (error) {
        console.error('Failed to persist artifacts to session:', error);
        // Revert local state on error
        setArtifactsInContext(artifactsInContext);
      }
    }
  };

  const handleDeleteSession = async (deletedSessionId: string) => {
    if (deletedSessionId === currentSessionId) {
      // Current session was deleted — clear state and go back to agent base URL
      setCurrentSessionId(null);
      setMessages([]);
      setArtifactsInContext([]);
      navigate(`/chat/${agentId || currentAgentId}`);
      console.log('Current session deleted, chat cleared');
    }
  };

  const handleCreateSession = async () => {
    // Do NOT create a session immediately — show the greeting and wait for the first user message
    setCurrentSessionId(null);
    setArtifactsInContext([]);
    setMessages([]);
    setIsEphemeral(false);
    // Navigate to the agent base URL so no stale session ID lingers in the URL
    navigate(`/chat/${currentAgentId}`);
    await loadGreeting(currentAgentId);
    console.log('New ephemeral session started for agent:', currentAgentId);
  };

  const handleSwitchSession = async (sessionId: string) => {
    try {
      // Navigate to the session URL — the URL-driven effect will load messages
      const currentAgent = agentId || currentAgentId;
      navigate(`/chat/${currentAgent}/session/${sessionId}`);
    } catch (error) {
      console.error('Failed to switch session:', error);
    }
  };

  if (!agent) {
    return <div className="error">Agent not found: {currentAgentId}</div>;
  }

  if (loading) {
    return (
      <div className="chat-panel">
        <div className="chat-header">
          <Avatar agent={agent} size="medium" />
          <div className="chat-header-info">
            <h2>Chat with {agent.name}</h2>
            <p className="agent-role">{agent.role}</p>
          </div>
        </div>
        <div className="chat-messages">
          <div className="empty-chat">
            <p>Loading chat history...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="chat-panel-container">
      <div className="chat-panel">
        <div className="chat-header">
          <Avatar agent={agent} size="medium" />
          <div className="chat-header-info">
            <h2>Chat with {agent.name}</h2>
            <p className="agent-role">{agent.role}</p>
          </div>
          <button
            onClick={() => navigate(`/portfolio/${agent.id}`)}
            className="btn-header-action"
            title="View portfolio"
          >
            <i className="codicon codicon-account" /> Portfolio
          </button>
          {streaming && <span className="streaming-indicator">●</span>}
        </div>

        {graphSessionId ? (
          <>
            <div className="graph-view-header">
              <button
                className="graph-view-back"
              onClick={() => navigate(`/chat/${agentId || currentAgentId}/session/${currentSessionId ?? ''}`.replace(/\/session\/$/, ''))}
              >
                <i className="codicon codicon-arrow-left" /> Back to chat
              </button>
              <span className="graph-view-header-title">Session thread</span>
            </div>
            <div className="chat-messages chat-messages-graph">
              <SessionGraphLoader
                sessionId={graphSessionId}
                activeSessionId={currentSessionId}
                onSelectSession={handleSelectSessionFromGraph}
              />
            </div>
          </>
        ) : (
          <div className="chat-messages" ref={messagesContainerRef} onScroll={handleScroll}>
            {messages.length === 0 && (
              <div className="empty-chat">
                <p>Start a conversation with {agent.name}</p>
                <div className="agent-info">
                  <strong>Role:</strong> {agent.role}
                </div>
              </div>
            )}

          {messages.map((message, index) => (
            <React.Fragment key={`message-${index}`}>
              {/* Show divider before each message (except the first) */}
              {index > 0 && (
                <MessageDivider
                  key={`divider-${index}`}
                  messageIndex={index}
                  onSummarize={handleSummarize}
                  onSplitSession={handleSplitSession}
                />
              )}
              <div
                className={`message message-${isHumanMessage(message) ? 'user' : 'assistant'}${
                  message.archived ? ' message-archived' : ''
                }`}
                style={(() => {
                  if (isHumanMessage(message)) return undefined;
                  const senderAgent = agents.find((a) => a.id === message.from) ?? agent;
                  return { '--agent-color': getAgentColor(senderAgent) } as React.CSSProperties;
                })()}
                {...(message.handoffId ? { 'data-handoff-id': message.handoffId } : {})}
              >
              <div className="message-avatar">
                {isHumanMessage(message) ? (
                  <div 
                    className={`avatar avatar-small avatar-initials${developer?.portfolioUrl ? ' avatar-clickable' : ''}`}
                    onClick={() => {
                      if (developer?.portfolioUrl) {
                        window.open(developer.portfolioUrl, '_blank');
                      }
                    }}
                    title={developer?.portfolioUrl ? `Visit ${developer.name}'s portfolio` : undefined}
                  >
                    {developer?.avatar ? (
                      <img
                        src={developer.avatar}
                        alt={developer.name}
                        className="avatar avatar-small developer-avatar-img"
                      />
                    ) : (
                      (developer?.name || formatDeveloperName(message.from)).substring(0, 2).toUpperCase()
                    )}
                  </div>
                ) : (
                  <Avatar agent={agents.find((a) => a.id === message.from) ?? agent} size="small" />
                )}
              </div>
              <div className="message-bubble">
                <div className="message-header">
                  <strong>{isHumanMessage(message) ? (developer?.name || formatDeveloperName(message.from)) : (agents.find((a) => a.id === message.from) ?? agent).name}</strong>
                  {isAgentBriefing(message) && getTargetAgentName(message) && (
                    <AgentBriefingBadge targetAgentName={getTargetAgentName(message)!} />
                  )}
                  <RelativeTime timestamp={message.timestamp} className="message-time" />
                  {message.archived && <span className="archived-badge">📦 Archived</span>}
                </div>
                <div className="message-content">
                  {editingIndex === index ? (
                    <div className="message-edit-mode">
                      <textarea
                        value={editContent}
                        onChange={(e) => setEditContent(e.target.value)}
                        className="message-edit-textarea"
                        rows={5}
                        title="Edit message content"
                      />
                      <div className="message-edit-actions">
                        <button onClick={() => handleEditMessage(index)} className="btn-save">
                          Save
                        </button>
                        <button onClick={handleCancelEdit} className="btn-cancel">
                          Cancel
                        </button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <MarkdownMessage content={message.content} />
                      {(() => {
                        const nav = resolveNavigateAgent(message);
                        if (!nav) return null;
                        return (
                          <button
                            onClick={() => handleHandoffClick(nav.agent.id, nav.sessionId)}
                            className="btn-handoff-link"
                            title={`Go to ${nav.agent.name}`}
                          >
                            <Avatar agent={nav.agent} size="small" />
                            <span>Go to {nav.agent.name}</span>
                          </button>
                        );
                      })()}
                    </>
                  )}
                </div>
                {editingIndex !== index && (
                  <div className="message-actions">
                    <button
                      onClick={() => handleEditMessage(index)}
                      className="btn-action"
                      title="Edit message"
                    >
                      ✏️
                    </button>
                    <button
                      onClick={() => handleCopyMessage(message.content)}
                      className="btn-action"
                      title="Copy raw content"
                    >
                      📋
                    </button>
                    <button
                      onClick={() => handleToggleArchive(index, message.archived || false)}
                      className="btn-action"
                      title={message.archived ? 'Unarchive' : 'Archive (hide from LLM context)'}
                    >
                      {message.archived ? '📂' : '📦'}
                    </button>
                    <button
                      onClick={() => handleDeleteMessage(index)}
                      className="btn-action btn-delete"
                      title="Delete message"
                    >
                      🗑️
                    </button>
                  </div>
                )}
              </div>
            </div>
            </React.Fragment>
          ))}
          <div ref={messagesEndRef} />
          </div>
        )}

        <div className="chat-input-area">
          {pendingQuestion ? (
            <form className="chat-input-container pending-question-form" onSubmit={handlePendingQuestionSubmit}>
              <div className="pending-question-title">{pendingQuestion.message}</div>

              {pendingQuestion.kind === 'input' && (
                <input
                  type="text"
                  className="pending-question-control pending-question-input"
                  value={pendingInputAnswer}
                  onChange={(e) => setPendingInputAnswer(e.target.value)}
                  placeholder="Enter your answer"
                  title="Answer"
                />
              )}

              {pendingQuestion.kind === 'password' && (
                <input
                  type="password"
                  className="pending-question-control pending-question-input"
                  value={pendingPasswordAnswer}
                  onChange={(e) => setPendingPasswordAnswer(e.target.value)}
                  placeholder="Enter your answer"
                  title="Answer"
                />
              )}

              {pendingQuestion.kind === 'confirm' && (
                <label className="pending-question-control pending-question-confirm">
                  <input
                    type="checkbox"
                    checked={pendingConfirmAnswer}
                    onChange={(e) => setPendingConfirmAnswer(e.target.checked)}
                  />
                  <span>Confirm</span>
                </label>
              )}

              {pendingQuestion.kind === 'select' && (
                <select
                  className="pending-question-control pending-question-select"
                  value={pendingSelectAnswer}
                  onChange={(e) => setPendingSelectAnswer(e.target.value)}
                  title="Choose an option"
                >
                  {pendingQuestion.choices.map((choice) => (
                    <option key={choice.value} value={choice.value}>
                      {choice.name}
                    </option>
                  ))}
                </select>
              )}

              {pendingQuestion.kind === 'checklist' && (
                <div className="pending-question-control pending-question-checklist">
                  {pendingQuestion.choices.map((choice) => (
                    <label key={choice.value} className="pending-question-checklist-item">
                      <input
                        type="checkbox"
                        checked={pendingChecklistAnswer.includes(choice.value)}
                        onChange={(e) => togglePendingChecklistValue(choice.value, e.target.checked)}
                      />
                      {choice.name}
                    </label>
                  ))}
                </div>
              )}

              <div className="chat-input-actions">
                <button type="submit" className="chat-action-button chat-send-button pending-question-submit">
                  Send answers
                </button>
              </div>
            </form>
          ) : (
            <div className="chat-input-container">
              <textarea
                ref={textareaRef}
                className="chat-input-textarea"
                value={input}
                onChange={(e) => {
                  setInput(e.target.value);
                  autoResizeTextarea();
                }}
                onKeyPress={handleKeyPress}
                placeholder={`Ask ${agent.name}...`}
                rows={1}
                disabled={Boolean(pendingQuestion) || (sending && !streaming)}
              />
              <div className="chat-input-actions">
                {streaming ? (
                  <button
                    onClick={handleInterrupt}
                    className="chat-action-button chat-interrupt-button"
                    title="Stop generation"
                  >
                    <i className="codicon codicon-debug-stop" />
                  </button>
                ) : (
                  <>
                    <button
                      onClick={() => {
                        if (isRecording) {
                          recognition?.stop();
                        } else {
                          startVoiceRecording();
                        }
                      }}
                      className={`chat-action-button ${isRecording ? 'chat-recording' : ''}`}
                      title={isRecording ? 'Stop recording' : 'Voice input'}
                      disabled={sending}
                    >
                      <i className={`codicon ${isRecording ? 'codicon-record' : 'codicon-mic'}`} />
                    </button>
                    <button
                      onClick={handleSend}
                      disabled={Boolean(pendingQuestion) || !input.trim() || sending}
                      className="chat-action-button chat-send-button"
                      title="Send message"
                    >
                      <i className="codicon codicon-send" />
                    </button>
                  </>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      <ContextPanel
        agentId={agentId || currentAgentId}
        sessionId={currentSessionId ?? undefined}
        artifacts={artifactsInContext}
        onToggleArtifact={handleToggleArtifact}
        onSwitchSession={handleSwitchSession}
        onDeleteSession={handleDeleteSession}
        onCreateSession={handleCreateSession}
        onOpenSessionGraph={handleOpenSessionGraph}
        refreshTrigger={sessionRefreshTrigger}
      />
    </div>
  );
}

import { useNavigate } from 'react-router-dom';
import { useTeam } from '../context/TeamContext';
import { Logo } from './Logo';
import { Avatar } from './Avatar';
import { useMemo, useEffect, useState } from 'react';
import { TaskStatistics, SystemInfo, ChatSession, Agent } from '../types';
import { getAgentColor } from '../utils/color';
import './Dashboard.css';

export function Dashboard() {
  const { agents, loading, client } = useTeam();
  const navigate = useNavigate();
  const [taskStats, setTaskStats] = useState<TaskStatistics | null>(null);
  const [statsLoading, setStatsLoading] = useState(true);
  const [systemInfo, setSystemInfo] = useState<SystemInfo | null>(null);
  const [recentSessions, setRecentSessions] = useState<ChatSession[]>([]);

  // Find CEO (root of hierarchy - no reportsTo)
  const ceoAgent = useMemo(() => {
    if (loading || agents.length === 0) return null;
    const ceo = agents.find(a => !a.reportsTo);
    return ceo || agents[0]; // Fallback to first agent
  }, [agents, loading]);

  // FindCEO(agent with most direct reports, excluding CEO)
  const ctoAgent = useMemo(() => {
    if (loading || agents.length === 0 || !ceoAgent) return null;
    const nonCeoAgents = agents.filter(a => a.id !== ceoAgent.id);
    if (nonCeoAgents.length === 0) return null;
    
    // Count direct reports for each agent
    const reportCounts = nonCeoAgents.map(agent => ({
      agent,
      count: agents.filter(a => a.reportsTo === agent.id).length
    }));
    
    // Find agent with most direct reports (create copy before sorting)
    const sorted = [...reportCounts];
    sorted.sort((a, b) => b.count - a.count);
    constCEO= sorted[0];
    return cto.count > 0 ? cto.agent : null;
  }, [agents, loading, ceoAgent]);

  // Get recently chatted agents based on session activity
  const recentAgents = useMemo(() => {
    if (loading || agents.length === 0 || recentSessions.length === 0) return [];
    
    // Get unique agent IDs from recent sessions
    const agentIds = [...new Set(recentSessions.map(s => s.agentId))]
      .filter(id => id !== ceoAgent?.id && id !== ctoAgent?.id); // Exclude CEO and CEO
    
    // Map to agent objects
    return agentIds
      .map(id => agents.find(a => a.id === id))
      .filter((a): a is Agent => a !== undefined)
      .slice(0, 2); // Take 2 most recent
  }, [agents, loading, recentSessions, ceoAgent, ctoAgent]);

  // Combine featured agents (CEO, CEO, 2 recent)
  const featuredAgents = useMemo(() => {
    const featured: Agent[] = [];
    if (ceoAgent) featured.push(ceoAgent);
    if (ctoAgent) featured.push(ctoAgent);
    featured.push(...recentAgents);
    return featured;
  }, [ceoAgent, ctoAgent, recentAgents]);

  // Fetch task statistics
  useEffect(() => {
    async function fetchTaskStats() {
      try {
        setStatsLoading(true);
        const response = await fetch(`${(client as any).baseUrl || 'http://localhost:3002'}/api/tasks/dashboard`);
        if (response.ok) {
          const stats = await response.json();
          setTaskStats(stats);
        }
      } catch (error) {
        console.error('Failed to fetch task statistics:', error);
      } finally {
        setStatsLoading(false);
      }
    }
    fetchTaskStats();
  }, [client]);

  // Fetch system information
  useEffect(() => {
    async function fetchSystemInfo() {
      try {
        const response = await fetch(`${(client as any).baseUrl || 'http://localhost:3002'}/api/info`);
        if (response.ok) {
          const info = await response.json();
          setSystemInfo(info);
        }
      } catch (error) {
        console.error('Failed to fetch system info:', error);
      }
    }
    fetchSystemInfo();
  }, [client]);

  // Fetch recent sessions for dashboard
  useEffect(() => {
    async function fetchRecentSessions() {
      try {
        const response = await fetch(`${(client as any).baseUrl || 'http://localhost:3002'}/api/sessions/recent?limit=10`);
        if (response.ok) {
          const sessions = await response.json();
          setRecentSessions(sessions);
        }
      } catch (error) {
        console.error('Failed to fetch recent sessions:', error);
      }
    }
    fetchRecentSessions();
  }, [client]);

  // Calculate agent activity stats
  const agentStats = useMemo(() => {
    if (loading || agents.length === 0) return null;
    const available = agents.filter(a => a.status === 'available' || !a.status).length;
    const busy = agents.filter(a => a.status === 'busy').length;
    const offline = agents.filter(a => a.status === 'offline').length;
    const inMeeting = agents.filter(a => a.status === 'in-meeting').length;
    return { total: agents.length, available, busy, offline, inMeeting };
  }, [agents, loading]);

  // Calculate open tasks
  const openTasks = useMemo(() => {
    if (!taskStats) return 0;
    const notStarted = taskStats.tasksByStatus?.['not_started'] || 0;
    const inProgress = taskStats.tasksByStatus?.['in_progress'] || 0;
    const blocked = taskStats.tasksByStatus?.['blocked'] || 0;
    return notStarted + inProgress + blocked;
  }, [taskStats]);

  const handleChatWithAgent = (agentId: string) => {
    navigate(`/chat/${agentId}`);
  };

  const handleViewEmployees = () => {
    navigate('/employees');
  };

  return (
    <div className="dashboard">
      <div className="dashboard-container">
        <header className="dashboard-hero">
          <Logo size={80} className="dashboard-logo" />
          <h1 className="dashboard-title">AI Team Management</h1>
          <p className="dashboard-mission">
            Your virtual software organization
          </p>
        </header>

        {featuredAgents.length > 0 && (
          <div className="featured-agents">
            {featuredAgents.map((agent) => (
              <button
                key={agent.id}
                className="featured-agent-card"
                style={{ '--agent-color': getAgentColor(agent) } as React.CSSProperties}
                onClick={() => handleChatWithAgent(agent.id)}
              >
                <Avatar agent={agent} size="medium" />
                <div className="featured-agent-info">
                  <h3 className="featured-agent-name">{agent.name}</h3>
                  <span className="agent-role-badge">{agent.role}</span>
                </div>
              </button>
            ))}
          </div>
        )}

        <div className="dashboard-stats">
          <button className="stat-card stat-card-clickable stat-card-agents" onClick={handleViewEmployees}>
            <div className="stat-header">
              Agents
              <i className="codicon codicon-arrow-right" />
            </div>
            <div className="stat-content">
              {loading ? (
                <div className="stat-value">—</div>
              ) : (
                <>
                  <div className="stat-value">{agentStats?.total || 0}</div>
                  <div className="stat-breakdown">
                    <span className="stat-item stat-available">{agentStats?.available || 0} available</span>
                    <span className="stat-item stat-busy">{agentStats?.busy || 0} busy</span>
                  </div>
                </>
              )}
            </div>
          </button>

          <div className="stat-card stat-card-tasks">
            <div className="stat-header">Open Tasks</div>
            <div className="stat-content">
              {statsLoading ? (
                <div className="stat-value">—</div>
              ) : (
                <>
                  <div className="stat-value">{openTasks}</div>
                  {taskStats && (
                    <div className="stat-breakdown">
                      <span className="stat-item stat-in-progress">{taskStats.tasksByStatus?.['in_progress'] || 0} in progress</span>
                      <span className="stat-item stat-not-started">{taskStats.tasksByStatus?.['not_started'] || 0} to do</span>
                    </div>
                  )}
                </>
              )}
            </div>
          </div>

          <div className="stat-card stat-card-completion">
            <div className="stat-header">Completion</div>
            <div className="stat-content">
              {statsLoading ? (
                <div className="stat-value">—</div>
              ) : taskStats && taskStats.totalTasks > 0 ? (
                <>
                  <div className="stat-value">
                    {Math.round(((taskStats.tasksByStatus?.['completed'] || 0) / taskStats.totalTasks) * 100)}%
                  </div>
                  <div className="stat-breakdown">
                    <span className="stat-item stat-completed">{taskStats.tasksByStatus?.['completed'] || 0} of {taskStats.totalTasks}</span>
                  </div>
                </>
              ) : (
                <div className="stat-value">—</div>
              )}
            </div>
          </div>
        </div>

        {systemInfo && (
          <div className="system-info">
            <h2 className="system-info-title">System Information</h2>
            <div className="system-info-grid">
              <div className="info-item">
                <span className="info-label">API URL</span>
                <span className="info-value">{systemInfo.apiUrl}</span>
              </div>
              <div className="info-item">
                <span className="info-label">Workspace</span>
                <span className="info-value" title={systemInfo.workspace}>
                  {systemInfo.workspace.length > 50 
                    ? `...${systemInfo.workspace.slice(-50)}` 
                    : systemInfo.workspace}
                </span>
              </div>
              <div className="info-item">
                <span className="info-label">Branch</span>
                <span className="info-value">
                  {systemInfo.branch || <span className="info-empty">not a git repository</span>}
                </span>
              </div>
              {systemInfo.package && (
                <>
                  <div className="info-item">
                    <span className="info-label">Package</span>
                    <span className="info-value">
                      {systemInfo.package.name || <span className="info-empty">unnamed</span>}
                    </span>
                  </div>
                  <div className="info-item">
                    <span className="info-label">Version</span>
                    <span className="info-value">
                      {systemInfo.package.version || <span className="info-empty">unversioned</span>}
                    </span>
                  </div>
                  {systemInfo.package.description && (
                    <div className="info-item info-item-full">
                      <span className="info-label">Description</span>
                      <span className="info-value">{systemInfo.package.description}</span>
                    </div>
                  )}
                </>
              )}
              {!systemInfo.package && (
                <div className="info-item">
                  <span className="info-label">Package</span>
                  <span className="info-empty">no package.json found</span>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * FileTree component — shows workspace files annotated with an agent's read/write
 * permissions. In view mode, shows which files are readable/writable. In edit mode,
 * allows toggling read and write access per file.
 *
 * API used:
 *   GET  /api/agents/:id/files?all=true      → AgentFilesResponse
 *   POST /api/files/agents/:id/allow         { path, mode }
 *   DELETE /api/files/agents/:id/allow       { path, mode }
 */
import { useState, useEffect, useCallback, useMemo } from 'react';
import { API_BASE } from '../context/TeamContext';
import type { AgentFilesResponse } from '../types';
import './FileTree.css';

// ─── Types ────────────────────────────────────────────────────────────────────

interface FlatFile {
  path: string;      // workspace-relative
  readable: boolean;
  writable: boolean;
}

interface TreeNode {
  name: string;
  path: string;
  isDir: boolean;
  children: TreeNode[];
  file?: FlatFile;   // leaf only
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function buildTree(files: FlatFile[]): TreeNode[] {
  const root: TreeNode = { name: '', path: '', isDir: true, children: [] };

  for (const file of files) {
    const parts = file.path.replace(/\\/g, '/').split('/');
    let node = root;
    for (let i = 0; i < parts.length; i++) {
      const part = parts[i];
      const isLast = i === parts.length - 1;
      let child = node.children.find((c) => c.name === part);
      if (!child) {
        const partPath = parts.slice(0, i + 1).join('/');
        child = { name: part, path: partPath, isDir: !isLast, children: [] };
        if (isLast) child.file = file;
        node.children.push(child);
      }
      node = child;
    }
  }

  // Sort: dirs first, then files, alphabetically
  function sortChildren(n: TreeNode) {
    n.children.sort((a, b) => {
      if (a.isDir !== b.isDir) return a.isDir ? -1 : 1;
      return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
    });
    n.children.forEach(sortChildren);
  }
  sortChildren(root);

  return root.children;
}

function getExt(name: string): string {
  const i = name.lastIndexOf('.');
  return i > 0 ? name.slice(i + 1).toLowerCase() : '';
}

const EXT_ICON: Record<string, string> = {
  ts: '𝘛',  tsx: '⚛',  js: '𝙅',  jsx: '⚛',
  json: '{}', md: '📄',  css: '🎨', html: '🌐',
  yml: '⚙',  yaml: '⚙', sh: '⚡',  env: '🔑',
};

function fileIcon(name: string, isDir: boolean): string {
  if (isDir) return '📁';
  return EXT_ICON[getExt(name)] ?? '📄';
}

// ─── Tree Node Row ────────────────────────────────────────────────────────────

interface NodeRowProps {
  node: TreeNode;
  depth: number;
  editMode: boolean;
  pendingPaths: Set<string>;
  onToggle: (path: string, mode: 'read' | 'write', current: boolean) => void;
}

async function openFileInIde(relativePath: string) {
  try {
    await fetch(`${API_BASE}/api/ide/open-file`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ filePath: relativePath }),
    });
  } catch {
    // silent — IDE may not be connected
  }
}

function NodeRow({ node, depth, editMode, pendingPaths, onToggle }: NodeRowProps) {
  const [open, setOpen] = useState(depth < 2);

  const file = node.file;
  const readable = file?.readable ?? false;
  const writable = file?.writable ?? false;
  const isPending = pendingPaths.has(node.path);

  return (
    <>
      <div
        className={`ft-row ft-depth-${Math.min(depth, 8)} ${node.isDir ? 'ft-dir' : 'ft-file'} ${isPending ? 'ft-pending' : ''}`}
        style={{ paddingLeft: `${depth * 14 + 8}px` }}
      >
        {node.isDir ? (
          <button
            className="ft-expand"
            onClick={() => setOpen((o) => !o)}
            aria-label={open ? 'Collapse' : 'Expand'}
          >
            <i className={`codicon codicon-chevron-${open ? 'down' : 'right'}`} />
          </button>
        ) : !editMode ? (
          <button
            className="ft-expand ft-open-btn"
            onClick={() => openFileInIde(node.path)}
            title="Open in IDE"
            aria-label="Open in IDE"
          >
            <i className="codicon codicon-go-to-file" />
          </button>
        ) : (
          <span className="ft-expand ft-expand-spacer" />
        )}

        <span className="ft-icon">{fileIcon(node.name, node.isDir)}</span>
        {!node.isDir && !editMode ? (
          <button
            className="ft-name ft-name-link"
            title={`Open in IDE: ${node.path}`}
            onClick={() => openFileInIde(node.path)}
          >
            {node.name}
          </button>
        ) : (
          <span className="ft-name" title={node.path}>{node.name}</span>
        )}

        {!node.isDir && (
          <div className="ft-perms">
            {editMode ? (
              <>
                <button
                  type="button"
                  className={`ft-perm-btn ${readable ? 'ft-perm-on' : 'ft-perm-off'}`}
                  title={readable ? 'Revoke read access' : 'Grant read access'}
                  disabled={isPending}
                  onClick={() => onToggle(node.path, 'read', readable)}
                >
                  <i className="codicon codicon-eye" /> R
                </button>
                <button
                  type="button"
                  className={`ft-perm-btn ${writable ? 'ft-perm-on' : 'ft-perm-off'}`}
                  title={writable ? 'Revoke write access' : 'Grant write access'}
                  disabled={isPending}
                  onClick={() => onToggle(node.path, 'write', writable)}
                >
                  <i className="codicon codicon-edit" /> W
                </button>
              </>
            ) : (
              <>
                {readable && <span className="ft-badge ft-badge-read" title="Readable">R</span>}
                {writable && <span className="ft-badge ft-badge-write" title="Writable">W</span>}
              </>
            )}
          </div>
        )}
      </div>

      {node.isDir && open && node.children.map((child) => (
        <NodeRow
          key={child.path}
          node={child}
          depth={depth + 1}
          editMode={editMode}
          pendingPaths={pendingPaths}
          onToggle={onToggle}
        />
      ))}
    </>
  );
}

// ─── Main Component ───────────────────────────────────────────────────────────

interface FileTreeProps {
  agentId: string;
  editMode: boolean;
}

export function FileTree({ agentId, editMode }: FileTreeProps) {
  const [data, setData] = useState<AgentFilesResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pendingPaths, setPendingPaths] = useState<Set<string>>(new Set());
  const [filter, setFilter] = useState<'all' | 'read' | 'write'>('all');
  const [search, setSearch] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`${API_BASE}/api/agents/${encodeURIComponent(agentId)}/files?all=true`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json: AgentFilesResponse = await res.json();
      setData(json);
    } catch (e: any) {
      setError(e?.message || 'Failed to load files');
    } finally {
      setLoading(false);
    }
  }, [agentId]);

  useEffect(() => { load(); }, [load]);

  const handleToggle = useCallback(async (path: string, mode: 'read' | 'write', current: boolean) => {
    setPendingPaths((s) => new Set([...s, path]));
    try {
      const method = current ? 'DELETE' : 'POST';
      const res = await fetch(`${API_BASE}/api/files/agents/${encodeURIComponent(agentId)}/allow`, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ path, mode }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({ error: `HTTP ${res.status}` }));
        throw new Error(err.error || `HTTP ${res.status}`);
      }
      // Optimistically update local state
      setData((prev) => {
        if (!prev) return prev;
        const files = prev.files.map((f) => {
          if (f.path !== path) return f;
          return {
            ...f,
            readable: mode === 'read' ? !current : f.readable,
            writable: mode === 'write' ? !current : f.writable,
          };
        });
        return { ...prev, files };
      });
    } catch (e: any) {
      setError(e?.message || 'Failed to update permission');
    } finally {
      setPendingPaths((s) => { const n = new Set(s); n.delete(path); return n; });
    }
  }, [agentId]);

  const filteredFiles = useMemo<FlatFile[]>(() => {
    if (!data) return [];
    return data.files
      .filter((f) => {
        if (filter === 'read' && !f.readable) return false;
        if (filter === 'write' && !f.writable) return false;
        if (search) return f.path.toLowerCase().includes(search.toLowerCase());
        return true;
      })
      .map((f) => ({ path: f.path, readable: f.readable, writable: f.writable }));
  }, [data, filter, search]);

  const tree = useMemo(() => buildTree(filteredFiles), [filteredFiles]);

  const readCount = data?.files.filter((f) => f.readable).length ?? 0;
  const writeCount = data?.files.filter((f) => f.writable).length ?? 0;

  if (loading) return (
    <div className="ft-loading">
      <i className="codicon codicon-loading codicon-modifier-spin" /> Loading file tree…
    </div>
  );

  if (error) return (
    <div className="ft-error">
      <i className="codicon codicon-error" /> {error}
      <button className="ft-retry" onClick={load}>Retry</button>
    </div>
  );

  if (!data) return null;

  return (
    <div className="ft-root">
      {/* Summary row */}
      <div className="ft-summary">
        <span className="ft-summary-item ft-summary-read">
          <i className="codicon codicon-eye" /> {readCount} readable
        </span>
        <span className="ft-summary-item ft-summary-write">
          <i className="codicon codicon-edit" /> {writeCount} writable
        </span>
        {data.readPatterns.length > 0 && (
          <details className="ft-patterns">
            <summary>Patterns</summary>
            <div className="ft-pattern-list">
              {data.readPatterns.map((p) => <span key={p} className="ft-pattern ft-pattern-read">{p}</span>)}
              {data.writePatterns.map((p) => <span key={p} className="ft-pattern ft-pattern-write">{p}</span>)}
            </div>
          </details>
        )}
      </div>

      {/* Toolbar */}
      <div className="ft-toolbar">
        <input
          className="ft-search"
          placeholder="Filter files…"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <div className="ft-filter-group">
          {(['all', 'read', 'write'] as const).map((v) => (
            <button
              key={v}
              type="button"
              className={`ft-filter-btn ${filter === v ? 'ft-filter-active' : ''}`}
              onClick={() => setFilter(v)}
            >
              {v === 'all' ? 'All' : v === 'read' ? <><i className="codicon codicon-eye" /> Read</> : <><i className="codicon codicon-edit" /> Write</>}
            </button>
          ))}
        </div>
      </div>

      {/* Tree */}
      <div className="ft-tree">
        {tree.length === 0 ? (
          <p className="ft-empty">
            {filter !== 'all' || search
              ? 'No files match the current filter.'
              : 'No files accessible.'}
          </p>
        ) : (
          tree.map((node) => (
            <NodeRow
              key={node.path}
              node={node}
              depth={0}
              editMode={editMode}
              pendingPaths={pendingPaths}
              onToggle={handleToggle}
            />
          ))
        )}
      </div>
    </div>
  );
}

import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import './MarkdownMessage.css';

interface MarkdownMessageProps {
  content: string;
}

export function MarkdownMessage({ content }: MarkdownMessageProps) {
  return (
    <ReactMarkdown
      remarkPlugins={[remarkGfm]}
      components={{
        // Custom renderers for better control
        code({ node, inline, className, children, ...props }: any) {
          return !inline ? (
            <pre className="code-block">
              <code className={className} {...props}>
                {children}
              </code>
            </pre>
          ) : (
            <code className="inline-code" {...props}>
              {children}
            </code>
          );
        },
        p({ node, children, ...props }: any) {
          // Prevent <p> from wrapping <pre> elements
          const hasCodeBlock = node.children?.some(
            (child: any) => child.tagName === 'pre' || child.tagName === 'code'
          );
          return hasCodeBlock ? <>{children}</> : <p {...props}>{children}</p>;
        },
        a({ node, children, href, ...props }: any) {
          return (
            <a href={href} target="_blank" rel="noopener noreferrer" {...props}>
              {children}
            </a>
          );
        },
      }}
    >
      {content}
    </ReactMarkdown>
  );
}

import { useEffect, useState, KeyboardEvent } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { useTeam } from '../context/TeamContext';
import { Agent, AgentPersonality, AgentSkill, AgentCapabilities } from '../types';
