            </>
          )}
        </div>
      </div>

      {saveError && (
        <div className="portfolio-save-error">
          <i className="codicon codicon-error" /> {saveError}
        </div>
      )}

      <div className="portfolio-content">

        {/* ── Identity (edit only) ── */}
        {isEditing && (
          <SectionCard title="Identity" icon="🪪">
            <div className="portfolio-form-grid">
              <label><span>Type</span>
