                    <span className="personality-icon">{v.personality.mentoring ? '✅' : '—'}</span>
                    <div>
                      <div className="personality-label">Mentoring</div>
                      <div className="personality-value">{v.personality.mentoring ? 'Available' : 'Not available'}</div>
                    </div>
                  </div>
                )}
              </div>
            )}
          </SectionCard>
        )}

        {/* ── Hierarchy ── */}
        <SectionCard title="Hierarchy" icon="🏢">
          {isEditing ? (
            <label className="portfolio-form-label-full"><span>Reports To</span>
              <select value={draft.reportsTo ?? agent.reportsTo ?? ''}
                onChange={(e) => patchDraft({ reportsTo: e.target.value || undefined })}>
                <option value="">— none (top level) —</option>
                {agents.filter((a) => a.id !== agent.id)
                  .sort((a, b) => a.name.localeCompare(b.name))
                  .map((a) => <option key={a.id} value={a.id}>{a.name} · {a.role}</option>)}
              </select>
            </label>
          ) : (
            <div className="hierarchy-section">
              {manager ? (
                <div className="hierarchy-row">
                  <span className="hierarchy-label">Reports to</span>
                  <Link to={`/portfolio/${manager.id}`} className="hierarchy-agent-link">
                    <Avatar agent={manager} size="small" />
                    <span>{manager.name}</span>
                    <span className="hierarchy-role">{manager.role}</span>
                  </Link>
                </div>
              ) : (
                <p className="text-muted">No manager defined (top level).</p>
              )}
              {directReports.length > 0 && (
                <div className="hierarchy-row">
                  <span className="hierarchy-label">Direct reports</span>
                  <div className="direct-reports-list">
                    {directReports.map((r) => (
                      <Link key={r.id} to={`/portfolio/${r.id}`} className="hierarchy-agent-link">
                        <Avatar agent={r} size="small" />
                        <span>{r.name}</span>
                        <span className="hierarchy-role">{r.role}</span>
                      </Link>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </SectionCard>

        {/* ── Skills & Features ── */}
        {((v.specializations?.length ?? 0) > 0 || (v.features?.length ?? 0) > 0 || isEditing) && (
          <SectionCard title="Skills & Features" icon="⚡">
            {isEditing ? (
              <div className="portfolio-form-stack">
                <label><span>Specializations</span>
                  <TagInput tags={draft.specializations ?? agent.specializations ?? []}
                    onChange={(tags) => patchDraft({ specializations: tags })} placeholder="Add specialization…" />
                </label>
                <label><span>Features</span>
                  <TagInput tags={draft.features ?? agent.features ?? []}
                    onChange={(tags) => patchDraft({ features: tags })} placeholder="Add feature…" />
                </label>
              </div>
            ) : (
              <div className="skill-tags-group">
                {v.specializations?.map((s) => <span key={s} className="skill-tag">{s}</span>)}
                {v.features?.map((f) => <span key={f} className="skill-tag skill-tag-feature">{f}</span>)}
              </div>
            )}
          </SectionCard>
        )}

        {/* ── Agent Skills (structured A2A) ── */}
        {((v.skills?.length ?? 0) > 0 || isEditing) && (
          <SectionCard title="Agent Skills" icon="🧩">
            {isEditing ? (
              <SkillEditor
                skills={draft.skills ?? agent.skills ?? []}
                onChange={(skills) => patchDraft({ skills })}
              />
            ) : (
              <div className="agent-skills-list">
                {(v.skills ?? []).map((sk) => (
                  <div key={sk.id} className="agent-skill-card">
                    <div className="agent-skill-header">
                      <span className="agent-skill-name">{sk.name}</span>
                      {sk.tags?.map((t) => <span key={t} className="skill-tag skill-tag-sm">{t}</span>)}
                    </div>
                    {sk.description && <p className="agent-skill-desc">{sk.description}</p>}
                    {sk.examples && sk.examples.length > 0 && (
                      <ul className="agent-skill-examples">
                        {sk.examples.map((ex, i) => <li key={i}>{ex}</li>)}
                      </ul>
                    )}
                  </div>
                ))}
              </div>
            )}
          </SectionCard>
        )}

        {/* ── Agent Capabilities (A2A) ── */}
        {(v.capabilities || isEditing) && (
          <SectionCard title="Agent Capabilities" icon="⚙️">
            {isEditing ? (
              <div className="portfolio-form-grid">
                <label className="portfolio-checkbox-label">
                  <input type="checkbox"
                    checked={draft.capabilities?.streaming ?? agent.capabilities?.streaming ?? false}
                    onChange={(e) => patchCapabilities({ streaming: e.target.checked })} />
                  <span>Streaming</span>
                </label>
                <label className="portfolio-checkbox-label">
                  <input type="checkbox"
                    checked={draft.capabilities?.multimodal ?? agent.capabilities?.multimodal ?? false}
                    onChange={(e) => patchCapabilities({ multimodal: e.target.checked })} />
                  <span>Multimodal</span>
                </label>
                <label className="portfolio-checkbox-label">
                  <input type="checkbox"
                    checked={draft.capabilities?.codeExecution ?? agent.capabilities?.codeExecution ?? false}
                    onChange={(e) => patchCapabilities({ codeExecution: e.target.checked })} />
                  <span>Code Execution</span>
                </label>
                <label className="portfolio-checkbox-label">
                  <input type="checkbox"
                    checked={draft.capabilities?.reasoning ?? agent.capabilities?.reasoning ?? false}
                    onChange={(e) => patchCapabilities({ reasoning: e.target.checked })} />
                  <span>Reasoning</span>
                </label>
              </div>
            ) : (
              <div className="capabilities-grid">
                <div className="capability-item">
                  <span className={`capability-icon ${v.capabilities?.streaming ? 'capability-enabled' : ''}`}>
                    {v.capabilities?.streaming ? '✓' : '—'}
                  </span>
                  <span>Streaming</span>
                </div>
                <div className="capability-item">
                  <span className={`capability-icon ${v.capabilities?.multimodal ? 'capability-enabled' : ''}`}>
                    {v.capabilities?.multimodal ? '✓' : '—'}
                  </span>
                  <span>Multimodal</span>
                </div>
                <div className="capability-item">
                  <span className={`capability-icon ${v.capabilities?.codeExecution ? 'capability-enabled' : ''}`}>
                    {v.capabilities?.codeExecution ? '✓' : '—'}
                  </span>
                  <span>Code Execution</span>
                </div>
                <div className="capability-item">
                  <span className={`capability-icon ${v.capabilities?.reasoning ? 'capability-enabled' : ''}`}>
                    {v.capabilities?.reasoning ? '✓' : '—'}
                  </span>
                  <span>Reasoning</span>
                </div>
              </div>
            )}
          </SectionCard>
        )}

        {/* ── Tools ── */}
        {((v.tools?.length ?? 0) > 0 || isEditing) && (
          <SectionCard title="Tools" icon="🔧">
            {isEditing ? (
              <TagInput tags={draft.tools ?? agent.tools ?? []}
                onChange={(tags) => patchDraft({ tools: tags })} placeholder="Add tool…" />
            ) : (
              <div className="tool-tags">
                {v.tools?.map((t) => <span key={t} className="tool-tag">{t}</span>)}
              </div>
            )}
          </SectionCard>
        )}

        {/* ── Capabilities ── */}
        {(v.capabilities || isEditing) && (
          <SectionCard title="Capabilities" icon="⚙️">
            {isEditing ? (
              <div className="portfolio-capabilities-grid">
                {(['streaming', 'multimodal', 'codeExecution', 'reasoning'] as const).map((cap) => (
                  <label key={cap} className="portfolio-checkbox-label">
                    <input type="checkbox"
                      checked={!!(draft.capabilities?.[cap] ?? agent.capabilities?.[cap])}
                      onChange={(e) => patchCapabilities({ [cap]: e.target.checked || undefined })} />
                    <span>{cap.charAt(0).toUpperCase() + cap.replace(/([A-Z])/g, ' $1').slice(1)}</span>
                  </label>
                ))}
              </div>
            ) : (
              <div className="capabilities-grid">
                {v.capabilities?.streaming && <span className="capability-chip">Streaming</span>}
                {v.capabilities?.multimodal && <span className="capability-chip">Multimodal</span>}
                {v.capabilities?.codeExecution && <span className="capability-chip">Code Execution</span>}
                {v.capabilities?.reasoning && <span className="capability-chip">Reasoning</span>}
              </div>
            )}
          </SectionCard>
        )}

        {/* ── LLM Config (view only) ── */}
        {!isEditing && v.llm && (v.llm.provider || v.llm.model || v.llm.modelKey) && (
          <SectionCard title="LLM Configuration" icon="🤖">
            <div className="llm-row">
              {v.llm.provider && <span className="llm-item"><span className="llm-label">Provider</span>{v.llm.provider}</span>}
              {(v.llm.model || v.llm.modelKey) && <span className="llm-item"><span className="llm-label">Model</span>{v.llm.model ?? v.llm.modelKey}</span>}
            </div>
          </SectionCard>
        )}

        {/* ── File Access ── */}
        <SectionCard title="File Access" icon="📂">
          <FileTree agentId={agent.id} editMode={isEditing} />
        </SectionCard>

        {/* ── Activity (view only) ── */}
        {!isEditing && (v.conversationCount !== undefined || v.lastInteraction || v.createdAt) && (
          <SectionCard title="Activity" icon="📊">
            <div className="activity-row">
              {v.conversationCount !== undefined && (
                <div className="activity-item">
                  <span className="activity-value">{v.conversationCount}</span>
                  <span className="activity-label">Conversations</span>
                </div>
              )}
              {v.lastInteraction && (
                <div className="activity-item">
                  <RelativeTime timestamp={v.lastInteraction} className="activity-value" />
                  <span className="activity-label">Last interaction</span>
                </div>
              )}
              {v.createdAt && (
                <div className="activity-item">
                  <RelativeTime timestamp={v.createdAt} className="activity-value" />
                  <span className="activity-label">Created</span>
                </div>
              )}
            </div>
          </SectionCard>
        )}

      </div>
    </div>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';

// Extend Window interface for webkit prefix
declare global {
  interface Window {
    SpeechRecognition: any;
    webkitSpeechRecognition: any;
  }
}

interface UseSpeechRecognitionResult {
  transcript: string;
  listening: boolean;
  supported: boolean;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
}

export function useSpeechRecognition(): UseSpeechRecognitionResult {
  const [transcript, setTranscript] = useState('');
  const [listening, setListening] = useState(false);
  const [supported, setSupported] = useState(false);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecognition) {
      setSupported(true);
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'en-US';

      recognition.onresult = (event: any) => {
        let interimTranscript = '';
        let finalTranscript = '';

        for (let i = event.resultIndex; i < event.results.length; i++) {
          const transcriptPiece = event.results[i][0].transcript;
          if (event.results[i].isFinal) {
            finalTranscript += transcriptPiece + ' ';
          } else {
            interimTranscript += transcriptPiece;
          }
        }

        setTranscript((prev) => {
          const base = prev || '';
          return finalTranscript ? base + finalTranscript : base + interimTranscript;
        });
      };

      recognition.onerror = (event: any) => {
        console.error('Speech recognition error:', event.error);
        if (event.error === 'no-speech' || event.error === 'aborted') {
          // These are not critical errors, just log them
        } else {
          setListening(false);
        }
      };

      recognition.onend = () => {
        setListening(false);
      };

      recognitionRef.current = recognition;
    }

    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.abort();
      }
    };
  }, []);

  const startListening = useCallback(() => {
    if (recognitionRef.current && !listening) {
      setTranscript('');
      try {
        recognitionRef.current.start();
        setListening(true);
      } catch (error) {
        console.error('Error starting speech recognition:', error);
      }
    }
  }, [listening]);

  const stopListening = useCallback(() => {
    if (recognitionRef.current && listening) {
      try {
        recognitionRef.current.stop();
      } catch (error) {
        console.error('Error stopping speech recognition:', error);
      }
      setListening(false);
    }
  }, [listening]);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  return {
    transcript,
    listening,
    supported,
    startListening,
    stopListening,
    resetTranscript,
  };
}

// Browser-safe types (subset of @ai-team/core types)
// DO NOT import @ai-team/core - it uses Node.js APIs

export type ViewMode = 'hierarchy' | 'features' | 'expertise' | 'matrix';

export interface FileTreeNode {
  name: string;
  path: string;
  relativePath: string;
  isDirectory: boolean;
  children?: FileTreeNode[];
  size?: number;
  modified?: string;
  extension?: string;
  gitignored?: boolean;
}

export interface AnnotatedFile {
  path: string;
  readable: boolean;
  writable: boolean;
}

export interface AgentFilesResponse {
  agent: string;
  readPatterns: string[];
  writePatterns: string[];
  files: AnnotatedFile[];
}

export interface AvatarConfig {
  type?: 'url' | 'ai-generated' | 'initials';
  url?: string;
  style?: 'professional-headshot' | 'avatar' | 'illustrated';
  seed?: string;
}

export interface Developer {
  id: string;
  name: string;
  email: string;
  avatar?: string;
  portfolioUrl?: string | null;
}

export interface AgentPersonality {
  communication_style?: 'collaborative' | 'direct' | 'supportive' | 'analytical' | 'strategic';
  expertise_level?: 'executive' | 'senior' | 'mid-level' | 'junior';
  mentoring?: boolean;
}

export interface AgentLlm {
  provider?: string;
  modelKey?: string;
  model?: string;
}

export interface AgentSkill {
  id: string;
  name: string;
  description?: string;
  tags?: string[];
  examples?: string[];
}

export interface AgentCapabilities {
  streaming?: boolean;
  multimodal?: boolean;
  codeExecution?: boolean;
  reasoning?: boolean;
}

export interface Agent {
  id: string;
  name: string;
  role: string;
  type?: 'executive' | 'leadership' | 'team-lead' | 'individual-contributor' | 'quality-gate' | 'cross-concern' | 'product';
  contextLevel?: 'task' | 'module' | 'feature' | 'repository' | 'organization';
  reportsTo?: string;
  features?: string[];
  specializations?: string[];
  tools?: string[];
  cliTools?: string[];
  canDelegate?: boolean;
  delegatesTo?: string[];
  availableFor?: string[];
  status?: 'available' | 'busy' | 'in-meeting' | 'offline';
  markdown?: string;  // Portfolio/bio content
  avatar?: AvatarConfig;
  personality?: AgentPersonality;
  pronouns?: string;
  timezone?: string;
  workHours?: string;
  goal?: string;
  backstory?: string;
  skills?: AgentSkill[];
  capabilities?: AgentCapabilities;
  memory?: boolean;
  maxIterations?: number;
  llm?: AgentLlm;
  createdAt?: string;
  lastInteraction?: string;
  conversationCount?: number;
}

export type EdgeType =
  | 'reports-to'
  | 'reports-to-unresolved'
  | 'manages'
  | 'owns-feature'
  | 'contributes-to'
  | 'consults-on'
  | 'shares-context';

export interface GraphNode {
  id: string;
  type: 'agent' | 'feature';
  data: {
    label: string;
    agent?: Agent;
    feature?: any;
    role?: string;
    status?: Agent['status'];
  };
  position?: { x: number; y: number };
}

export interface GraphEdge {
  id: string;
  source: string;
  target: string;
  type: EdgeType;
  label?: string;
  error?: string;
}

export interface GraphData {
  nodes: GraphNode[];
  edges: GraphEdge[];
}

export interface ChatMessage {
  from: string; // Agent ID or developer ID (e.g., 'clemens-meier')
  to?: string; // Target agent ID (used for handoff messages)
  isHuman?: boolean; // True if message is from human developer
  content: string;
  timestamp: string;
  archived?: boolean;
  handoffType?: 'user-acknowledgment' | 'agent-briefing'; // Type of handoff message
  targetAgentId?: string; // Target agent for briefing messages
  // Cross-session handoff tracking (added with /thread API)
  handoffId?: string;              // UUID shared by all messages in one handoff event
  handoffFromSessionId?: string;   // Session this briefing came FROM
  handoffToSessionId?: string;     // Session this briefing is directed TO
}

export interface ChatSession {
  id: string;  // e.g., 'session-2026-02-27-abc123'
  agentId: string;      // deprecated — use agentIds[0]
  agentIds?: string[];  // Primary agent IDs for this session
  developerId: string;  // e.g., 'clemens-meier'
  title?: string;       // Optional session title
  startedAt: string;    // ISO timestamp
  lastActivityAt: string;  // ISO timestamp
  messageCount: number;
  artifacts: string[];  // Artifact IDs or paths in context
  allowedFiles: string[];  // Files agent can access in this session
  previousSessionId?: string;      // ID of session this was handed off from
  mergedFromSessionIds?: string[] | null;  // Sessions merged into this one
}

/** One directed handoff edge in the session thread graph */
export interface HandoffEdge {
  handoffId: string;
  fromSessionId: string | null;  // null if source session was deleted
  toSessionId: string | null;    // null if target session was deleted
  fromAgentIds: string[];
  toAgentIds: string[];
}

/** A single node in the session thread, as returned by GET /api/sessions/:id/thread */
export interface SessionNode {
  sessionId: string;
  agentIds: string[];
  agentNames: string[];
  developerId: string | null;
  title: string | null;
  startedAt: string;
  lastActivityAt: string;
  previousSessionId: string | null;
  mergedFromSessionIds: string[] | null;
  messageCount: number;
  messages: ChatMessage[];
}

/** Full session thread returned by GET /api/sessions/:id/thread */
export interface SessionThread {
  rootSessionId: string;
  currentSessionId: string;
  depth: number;
  handoffs: HandoffEdge[];
  sessions: SessionNode[];
}

export interface Artifact {
  id: string;  // e.g., 'brief-user-auth-design'
  type: 'brief' | 'summary' | 'record' | 'document';
  title: string;
  content: string;  // Markdown content
  createdAt: string;
  createdBy: string;  // developer ID
  sourceSessionId: string;  // Session where it was created
  fromMessageIndex: number;  // Start of summarized range
  toMessageIndex: number;  // End of summarized range
  filepath: string;  // .ai-team/artifacts/briefs/{filename}.md
  tags?: string[];
}

// Task Management Types
export enum TaskStatus {
  NOT_STARTED = "not_started",
  IN_PROGRESS = "in_progress",
  BLOCKED = "blocked",
  WAITING_APPROVAL = "waiting_approval",
  COMPLETED = "completed",
  CANCELLED = "cancelled",
  DELEGATED = "delegated",
}

export enum TaskPriority {
  LOW = "low",
  MEDIUM = "medium",
  HIGH = "high",
  URGENT = "urgent",
}

export enum TaskType {
  FEATURE = "feature",
  BUG = "bug",
  DOCUMENTATION = "documentation",
}

export enum TaskExecutionMode {
  SEQUENTIAL = "sequential",
  PARALLEL = "parallel",
}

export interface TimeLogEntry {
  id: string;
  taskId: string;
  agentId: string;
  startTime: string;
  endTime?: string;
  durationMinutes?: number;
  description?: string;
  createdAt: string;
}

export interface WorkflowStep {
  id: string;
  title: string;
  description?: string;
  assignedTo?: string;
  autoAssign: boolean;
  accepted?: boolean;
  status: TaskStatus;
  dependencies?: string[];
  order: number;
  completedAt?: string;
}

export interface TaskDelegationRecord {
  id: string;
  fromAgentId: string;
  toAgentId: string;
  delegatedAt: string;
  reason?: string;
  accepted: boolean;
  acceptedAt?: string;
}

export interface Task {
  id: string;
  type: TaskType;
  title: string;
  description?: string;
  createdBy: string;
  createdByType: "human" | "agent";
  assignedTo?: string;
  status: TaskStatus;
  priority: TaskPriority;
  requiresApproval: boolean;
  approved?: boolean;
  approvedBy?: string;
  approvedAt?: string;
  parentTaskId?: string;
  subtaskIds?: string[];
  executionMode?: TaskExecutionMode;
  workflowSteps?: WorkflowStep[];
  estimatedHours?: number;
  actualHours?: number;
  timeLog?: TimeLogEntry[];
  dueDate?: string;
  startedAt?: string;
  completedAt?: string;
  cancelledAt?: string;
  tags?: string[];
  sessionId?: string;
  artifactIds?: string[];
  delegationHistory?: TaskDelegationRecord[];
  delegatedTo?: string;
  blockedReason?: string;
  blockedBy?: string[];
  metadata?: Record<string, any>;
  createdAt: string;
  updatedAt: string;
}

export interface TaskTemplate {
  id: string;
  name: string;
  type: TaskType;
  description: string;
  titleTemplate: string;
  descriptionTemplate: string;
  priority: TaskPriority;
  estimatedHours?: number;
  workflowSteps?: Omit<WorkflowStep, "id" | "status" | "completedAt">[];
  tags?: string[];
  requiresApproval: boolean;
}

export interface TaskStatistics {
  totalTasks: number;
  tasksByStatus: Record<TaskStatus, number>;
  tasksByPriority: Record<TaskPriority, number>;
  tasksByAgent: Record<string, number>;
  averageCompletionTime?: number;
  totalEstimatedHours: number;
  totalActualHours: number;
}

export interface SystemInfo {
  apiUrl: string;
  workspace: string;
  branch: string | null;
  package: {
    name: string | null;
    version: string | null;
    description: string | null;
  } | null;
}
